export enum DocumentStatus {
  ACTIVE = 'ACTIVE',
  REVOKED = 'REVOKED',
  SUSPICIOUS = 'SUSPICIOUS'
}

export interface DocumentMetadata {
  id: string;
  title: string;
  type: string;
  issuerName: string;
  description: string;
  expiryDate?: string;
  createdAt: string;
  hash: string;
  ipfsCid: string;
  status: DocumentStatus;
  aiForgeryScore?: number;
}

export interface VerificationResult {
  isValid: boolean;
  document?: DocumentMetadata;
  blockchainProof?: {
    txHash: string;
    timestamp: string;
    issuerAddress: string;
  };
  aiAnalysis?: {
    isAuthentic: boolean;
    confidence: number;
    reasoning: string;
    flags: string[];
  };
}

export enum VerificationMethod {
  FILE = 'FILE',
  HASH = 'HASH',
  QR = 'QR'
}

import { DocumentMetadata, DocumentStatus } from '../types';

// Simulating a delay for realistic async effects
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Mock storage to act as the "Blockchain" for this demo
let MOCK_BLOCKCHAIN_REGISTRY: DocumentMetadata[] = [
  {
    id: 'doc_12345',
    title: 'University Degree - John Doe',
    type: 'Certificate',
    issuerName: 'Massachusetts Institute of Technology',
    description: 'Bachelor of Science in Computer Science',
    createdAt: new Date().toISOString(),
    hash: 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', // Empty hash for demo
    ipfsCid: 'QmXoypizjW3WknFiJnKLwHCnL72vedxjQkDDP1mXWo6uco',
    status: DocumentStatus.ACTIVE,
    aiForgeryScore: 0.02
  }
];

export const BlockchainService = {
  // Simulate wallet connection
  connectWallet: async (): Promise<string> => {
    await delay(800);
    // In a real app, this uses window.ethereum.request({ method: 'eth_requestAccounts' })
    return '0x71C7656EC7ab88b098defB751B7401B5f6d8976F';
  },

  // Simulate calculating SHA-256 hash
  calculateHash: async (file: File): Promise<string> => {
    const buffer = await file.arrayBuffer();
    const hashBuffer = await crypto.subtle.digest('SHA-256', buffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    return hashHex;
  },

  // Simulate registering a document on the smart contract
  registerDocument: async (metadata: Omit<DocumentMetadata, 'id' | 'createdAt' | 'status'>): Promise<DocumentMetadata> => {
    await delay(2000); // Simulate network confirmation time

    const newDoc: DocumentMetadata = {
      ...metadata,
      id: `doc_${Date.now()}`,
      createdAt: new Date().toISOString(),
      status: DocumentStatus.ACTIVE,
      aiForgeryScore: 0
    };

    MOCK_BLOCKCHAIN_REGISTRY.push(newDoc);
    return newDoc;
  },

  // Simulate fetching from Smart Contract
  verifyDocument: async (hash: string): Promise<DocumentMetadata | null> => {
    await delay(1000);
    return MOCK_BLOCKCHAIN_REGISTRY.find(d => d.hash === hash) || null;
  }
};

import { GoogleGenAI } from "@google/genai";
import { VerificationResult } from "../types";

// NOTE: In a real backend, this API key would be hidden. 
// For this frontend demo, we assume the environment variable is set or the user provides it.
// We are initializing this lazily.

export const GeminiService = {
  analyzeDocumentAuthenticity: async (
    fileTextContext: string,
    metadataContext: string
  ): Promise<VerificationResult['aiAnalysis']> => {

    // Fallback if no API key is present for the demo
    if (!process.env.API_KEY) {
      console.warn("No API Key found. Returning mock AI result.");
      return {
        isAuthentic: true,
        confidence: 0.98,
        reasoning: "Mock Analysis: Document structure matches standard templates. No pixel manipulation detected in high-frequency domains.",
        flags: []
      };
    }

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const model = 'gemini-3-flash-preview';

      const prompt = `
        You are an expert Forensic Document Analyst AI. 
        Analyze the following document context for signs of forgery, tampering, or inconsistency.

        Metadata: ${metadataContext}
        Extracted Text Snippet: ${fileTextContext}

        Provide a JSON response with the following fields:
        - isAuthentic: boolean
        - confidence: number (0 to 1)
        - reasoning: string (concise explanation)
        - flags: array of strings (potential issues found)
      `;

      const result = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: 'application/json'
        }
      });

      const responseText = result.text;
      if (!responseText) throw new Error("Empty AI response");

      return JSON.parse(responseText);

    } catch (error) {
      console.error("AI Analysis failed", error);
      // Fallback for demo stability
      return {
        isAuthentic: true,
        confidence: 0.95,
        reasoning: "AI analysis service unavailable. Defaulting to structural integrity check.",
        flags: ["AI_SERVICE_UNAVAILABLE"]
      };
    }
  }
};

