import React, { useState } from 'react';
import { Upload, FileText, Wallet, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { DocumentMetadata } from '../types';

export const CreateDocument = () => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [walletAddress, setWalletAddress] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [registeredDoc, setRegisteredDoc] = useState<DocumentMetadata | null>(null);

  const [formData, setFormData] = useState({
    title: '',
    issuerName: '',
    type: 'Certificate',
    description: ''
  });

  const connectWallet = async () => {
    try {
      const address = await BlockchainService.connectWallet();
      setWalletAddress(address);
    } catch (err) {
      alert("Failed to connect wallet");
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!walletAddress || !file) return;

    setIsProcessing(true);
    try {
      // 1. Calculate Hash
      const hash = await BlockchainService.calculateHash(file);

      // 2. Mock IPFS Upload (In production: await IpfsService.upload(file))
      const ipfsCid = "QmMockCidForDemoPurposeOnly12345"; 

      // 3. Register on Blockchain
      const newDoc = await BlockchainService.registerDocument({
        title: formData.title,
        issuerName: formData.issuerName,
        type: formData.type,
        description: formData.description,
        hash,
        ipfsCid
      });

      setRegisteredDoc(newDoc);
      setStep(3);
    } catch (err) {
      console.error(err);
      alert("Registration failed");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-3xl mx-auto">
        <div className="mb-10 text-center">
          <h1 className="text-3xl font-bold text-slate-900">Register New Document</h1>
          <p className="mt-2 text-slate-600">Securely anchor your document to the blockchain.</p>
        </div>

        {/* Progress Steps */}
        <div className="mb-8 flex justify-center items-center space-x-4">
          {[1, 2, 3].map((s) => (
            <div key={s} className={`flex items-center ${s < 3 ? 'w-full' : ''}`}>
               <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${
                 step >= s ? 'bg-brand-600 text-white' : 'bg-slate-200 text-slate-500'
               }`}>
                 {s}
               </div>
               {s < 3 && <div className={`h-1 flex-1 mx-2 ${step > s ? 'bg-brand-600' : 'bg-slate-200'}`} />}
            </div>
          ))}
        </div>

        <div className="bg-white shadow-xl rounded-2xl overflow-hidden">
          {/* Step 1: Wallet Connection */}
          {step === 1 && (
            <div className="p-10 text-center">
              <div className="mx-auto w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-6">
                <Wallet className="h-8 w-8 text-brand-600" />
              </div>
              <h2 className="text-2xl font-bold text-slate-900 mb-4">Connect Wallet</h2>
              <p className="text-slate-600 mb-8 max-w-md mx-auto">
                You must connect your organization's verified wallet to sign the transaction and pay gas fees.
              </p>
              {!walletAddress ? (
                <button 
                  onClick={connectWallet}
                  className="inline-flex items-center px-6 py-3 border border-transparent text-base font-medium rounded-md text-white bg-brand-600 hover:bg-brand-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-500"
                >
                  Connect MetaMask
                </button>
              ) : (
                <div className="space-y-6">
                  <div className="inline-flex items-center px-4 py-2 rounded-full bg-green-50 text-green-700 border border-green-200">
                    <CheckCircle2 className="w-5 h-5 mr-2" />
                    Connected: {walletAddress.slice(0, 6)}...{walletAddress.slice(-4)}
                  </div>
                  <div>
                    <button 
                      onClick={() => setStep(2)}
                      className="w-full sm:w-auto px-8 py-3 bg-brand-600 text-white rounded-lg font-medium hover:bg-brand-700 transition-colors"
                    >
                      Continue to Upload
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Step 2: Form & Upload */}
          {step === 2 && (
            <form onSubmit={handleSubmit} className="p-8">
              <div className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Document Title</label>
                    <input 
                      required
                      type="text" 
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500"
                      placeholder="e.g. Degree Certificate"
                      value={formData.title}
                      onChange={e => setFormData({...formData, title: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Document Type</label>
                    <select 
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500"
                      value={formData.type}
                      onChange={e => setFormData({...formData, type: e.target.value})}
                    >
                      <option>Certificate</option>
                      <option>Contract</option>
                      <option>Identity Proof</option>
                      <option>Transcripts</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Issuer Name</label>
                  <input 
                    required
                    type="text" 
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg"
                    placeholder="Organization Name"
                    value={formData.issuerName}
                    onChange={e => setFormData({...formData, issuerName: e.target.value})}
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Description (Optional)</label>
                  <textarea 
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg"
                    rows={3}
                    value={formData.description}
                    onChange={e => setFormData({...formData, description: e.target.value})}
                  />
                </div>

                <div className="border-2 border-dashed border-slate-300 rounded-xl p-8 text-center hover:bg-slate-50 transition-colors">
                  <input 
                    type="file" 
                    id="file-upload" 
                    className="hidden" 
                    onChange={handleFileChange}
                    accept=".pdf,.png,.jpg,.jpeg"
                  />
                  <label htmlFor="file-upload" className="cursor-pointer">
                    <div className="mx-auto w-12 h-12 bg-blue-50 rounded-full flex items-center justify-center mb-3">
                      <Upload className="h-6 w-6 text-brand-600" />
                    </div>
                    <span className="text-brand-600 font-medium">Click to upload</span>
                    <span className="text-slate-500"> or drag and drop</span>
                    <p className="text-xs text-slate-400 mt-2">PDF, PNG, JPG up to 10MB</p>
                  </label>
                  {file && (
                    <div className="mt-4 flex items-center justify-center text-sm text-green-600 font-medium bg-green-50 py-2 rounded-lg">
                      <FileText className="w-4 h-4 mr-2" />
                      {file.name} ({(file.size / 1024 / 1024).toFixed(2)} MB)
                    </div>
                  )}
                </div>

                <button 
                  type="submit"
                  disabled={!file || isProcessing}
                  className="w-full py-3 bg-brand-600 text-white rounded-lg font-bold text-lg hover:bg-brand-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center"
                >
                  {isProcessing ? (
                    <>
                      <Loader2 className="animate-spin mr-2 h-5 w-5" />
                      Hashing & Registering...
                    </>
                  ) : 'Register Document'}
                </button>
              </div>
            </form>
          )}

          {/* Step 3: Success */}
          {step === 3 && registeredDoc && (
            <div className="p-10 text-center">
              <div className="mx-auto w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mb-6">
                <CheckCircle2 className="h-10 w-10 text-green-600" />
              </div>
              <h2 className="text-3xl font-bold text-slate-900 mb-2">Registration Successful!</h2>
              <p className="text-slate-600 mb-8">
                Your document has been cryptographically secured on the blockchain.
              </p>

              <div className="bg-slate-50 p-6 rounded-xl text-left space-y-4 mb-8">
                <div className="flex justify-between border-b border-slate-200 pb-2">
                  <span className="text-slate-500">Document Hash</span>
                  <span className="font-mono text-sm text-slate-900">{registeredDoc.hash.slice(0, 20)}...</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-2">
                  <span className="text-slate-500">Transaction ID</span>
                  <span className="font-mono text-sm text-brand-600 cursor-pointer">0x7f...3a9c</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Status</span>
                  <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                    ACTIVE
                  </span>
                </div>
              </div>

              <button 
                onClick={() => window.location.reload()}
                className="text-brand-600 font-medium hover:underline"
              >
                Register Another Document
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Search, FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';

export const VerifyDocument = () => {
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE);
  const [file, setFile] = useState<File | null>(null);
  const [hashInput, setHashInput] = useState('');
  const [status, setStatus] = useState<'IDLE' | 'ANALYZING' | 'COMPLETE'>('IDLE');
  const [result, setResult] = useState<VerificationResult | null>(null);

  const handleVerify = async () => {
    setStatus('ANALYZING');
    setResult(null);

    try {
      let docHash = hashInput;
      let fileTextContext = "No text extracted (Hash mode)";

      // 1. If File, Calculate Hash & extract context (simulated)
      if (method === VerificationMethod.FILE && file) {
        docHash = await BlockchainService.calculateHash(file);
        // Simulate extracting text for AI
        fileTextContext = "This certifies that John Doe has successfully completed the Bachelor of Science program..."; 
      }

      // 2. Blockchain Lookup
      const blockchainDoc = await BlockchainService.verifyDocument(docHash);

      // 3. AI Analysis (Simulated concurrent run)
      // Note: We pass the metadata stringified to give context to the AI
      const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in registry.";
      const aiAnalysis = await GeminiService.analyzeDocumentAuthenticity(fileTextContext, metadataContext);

      // 4. Construct Result
      const verificationResult: VerificationResult = {
        isValid: !!blockchainDoc && blockchainDoc.status === 'ACTIVE' && aiAnalysis.isAuthentic,
        document: blockchainDoc || undefined,
        aiAnalysis
      };

      setResult(verificationResult);
    } catch (error) {
      console.error(error);
      alert("Verification error occurred.");
    } finally {
      setStatus('COMPLETE');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="text-3xl font-bold text-slate-900">Verify Document Authenticity</h1>
          <p className="mt-2 text-slate-600">Combine Blockchain immutability with AI forensics.</p>
        </div>

        {/* Verification Method Tabs */}
        <div className="bg-white rounded-2xl shadow-lg overflow-hidden mb-8">
          <div className="flex border-b border-slate-200">
            <button 
              onClick={() => setMethod(VerificationMethod.FILE)}
              className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 ${method === VerificationMethod.FILE ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <UploadCloud className="w-5 h-5" />
              <span>Upload File</span>
            </button>
            <button 
              onClick={() => setMethod(VerificationMethod.HASH)}
              className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 ${method === VerificationMethod.HASH ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <Hash className="w-5 h-5" />
              <span>Enter Hash</span>
            </button>
            <button 
              className="flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 text-slate-400 cursor-not-allowed bg-slate-50"
              disabled
            >
              <span>Scan QR (Mobile)</span>
            </button>
          </div>

          <div className="p-8">
            {method === VerificationMethod.FILE ? (
              <div className="border-2 border-dashed border-slate-300 rounded-xl p-10 text-center">
                <input 
                  type="file" 
                  id="verify-upload" 
                  className="hidden" 
                  onChange={(e) => setFile(e.target.files?.[0] || null)}
                />
                <label htmlFor="verify-upload" className="cursor-pointer block">
                  <div className="mx-auto w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-4">
                    <FileSearch className="h-8 w-8 text-brand-600" />
                  </div>
                  <span className="text-brand-600 font-bold text-lg">Choose Document</span>
                  <p className="text-slate-500 mt-2">Upload the PDF or Image to verify</p>
                </label>
                {file && <p className="mt-4 text-sm font-medium text-slate-900">Selected: {file.name}</p>}
              </div>
            ) : (
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">Document Hash (SHA-256)</label>
                <input 
                  type="text" 
                  className="w-full px-4 py-3 border border-slate-300 rounded-lg font-mono text-sm"
                  placeholder="e.g. e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
                  value={hashInput}
                  onChange={(e) => setHashInput(e.target.value)}
                />
              </div>
            )}

            <button 
              onClick={handleVerify}
              disabled={status === 'ANALYZING' || (method === 'FILE' && !file) || (method === 'HASH' && !hashInput)}
              className="mt-6 w-full py-3 bg-brand-600 text-white rounded-lg font-bold hover:bg-brand-700 transition-colors disabled:opacity-50 flex justify-center items-center"
            >
              {status === 'ANALYZING' ? (
                <>
                  <Brain className="animate-pulse w-5 h-5 mr-2" />
                  Running Blockchain & AI Analysis...
                </>
              ) : 'Verify Document'}
            </button>
          </div>
        </div>

        {/* Results Section */}
        {status === 'COMPLETE' && result && (
          <div className={`rounded-2xl shadow-xl overflow-hidden border-t-8 ${result.isValid ? 'border-green-500' : 'border-red-500'} bg-white`}>
            {/* Header */}
            <div className={`p-6 flex items-center justify-between ${result.isValid ? 'bg-green-50' : 'bg-red-50'}`}>
              <div className="flex items-center space-x-4">
                {result.isValid ? (
                  <CheckCircle className="w-10 h-10 text-green-600" />
                ) : (
                  <ShieldAlert className="w-10 h-10 text-red-600" />
                )}
                <div>
                  <h2 className="text-2xl font-bold text-slate-900">
                    {result.isValid ? 'Authentic Document' : 'Verification Failed'}
                  </h2>
                  <p className="text-sm text-slate-600">
                    {result.isValid ? 'Verified by Blockchain & AI' : 'Tampering or Forgery Detected'}
                  </p>
                </div>
              </div>
              <div className="text-right">
                <div className="text-sm text-slate-500">Confidence Score</div>
                <div className="text-xl font-bold text-slate-900">{(result.aiAnalysis?.confidence || 0) * 100}%</div>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-6 p-8">
              {/* Blockchain Evidence */}
              <div className="space-y-4">
                <h3 className="font-semibold text-slate-900 flex items-center">
                  <FileCheck className="w-5 h-5 mr-2 text-brand-600" />
                  Blockchain Evidence
                </h3>
                {result.document ? (
                  <div className="bg-slate-50 rounded-lg p-4 space-y-3 text-sm">
                    <div>
                      <span className="block text-slate-500 text-xs">Issuer</span>
                      <span className="font-medium text-slate-900">{result.document.issuerName}</span>
                    </div>
                    <div>
                      <span className="block text-slate-500 text-xs">Timestamp</span>
                      <span className="font-mono text-slate-700">{new Date(result.document.createdAt).toLocaleString()}</span>
                    </div>
                    <div>
                      <span className="block text-slate-500 text-xs">Hash Match</span>
                      <span className="text-green-600 font-bold">MATCHED (SHA-256)</span>
                    </div>
                  </div>
                ) : (
                  <div className="p-4 bg-red-50 text-red-700 rounded-lg text-sm">
                    Hash not found in the decentralized registry.
                  </div>
                )}
              </div>

              {/* AI Analysis */}
              <div className="space-y-4">
                <h3 className="font-semibold text-slate-900 flex items-center">
                  <Brain className="w-5 h-5 mr-2 text-purple-600" />
                  AI Forgery Detection
                </h3>
                <div className="bg-slate-50 rounded-lg p-4 text-sm">
                  <p className="text-slate-700 mb-3 italic">"{result.aiAnalysis?.reasoning}"</p>

                  {result.aiAnalysis?.flags && result.aiAnalysis.flags.length > 0 && (
                    <div className="space-y-1">
                      {result.aiAnalysis.flags.map((flag, i) => (
                        <div key={i} className="inline-flex items-center px-2 py-1 rounded bg-red-100 text-red-700 text-xs mr-2">
                          {flag}
                        </div>
                      ))}
                    </div>
                  )}

                  {result.aiAnalysis?.isAuthentic && (
                    <div className="mt-2 text-green-600 font-medium text-xs flex items-center">
                      <CheckCircle className="w-3 h-3 mr-1" />
                      No structural manipulation detected
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

