                  </div>
                ) : (
                  <div className="relative border border-slate-200 rounded-xl p-4 bg-slate-50 flex items-center space-x-4">
                      {previewUrl ? (
                        <img src={previewUrl} alt="Preview" className="w-16 h-16 object-cover rounded-lg border border-slate-200" />
