// pages/VerifyDocument.tsx

import { useRef, useState, useEffect } from 'react';
import jsQR from 'jsqr';
import { VerificationMethod } from '../types';
import { Loader2 } from 'lucide-react';

interface VerifyDocumentProps {
  onVerify: (hash: string) => void;
  isLoading: boolean;
  status: 'IDLE' | 'ANALYZING' | 'SUCCESS' | 'ERROR';
}

const VerifyDocument: React.FC<VerifyDocumentProps> = ({ onVerify, isLoading, status }) => {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE_UPLOAD);
  const [qrData, setQrData] = useState<string | null>(null);

  useEffect(() => {
    if (method === VerificationMethod.QR_SCAN) {
      startCamera();
    } else {
      stopCamera();
    }

    return () => stopCamera();
  }, [method]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' },
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        videoRef.current.play();
        requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error('Camera access error:', err);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
  };

  const tick = async () => {
    if (videoRef.current && canvasRef.current && streamRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (!context) {
        console.error('Canvas context not available');
        return;
      }

      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      context.drawImage(video, 0, 0, canvas.width, canvas.height);
      const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
      const code = jsQR(imageData.data, imageData.width, imageData.height, {
        inversionAttempts: "dontInvert",
      });

      if (code) {
        handleQrDetected(code.data);
      }

      requestAnimationFrame(tick);
    }
  };

  const handleQrDetected = (data: string) => {
    setQrData(data);
    setMethod(VerificationMethod.HASH);
    handleVerify(data);
  };

  const handleVerify = (data: string) => {
    onVerify(data);
  };

  return (
    <div className="flex flex-col items-center justify-center h-full">
      {method === VerificationMethod.QR_SCAN && (
        <div className="relative">
          <video
            ref={videoRef}
            style={{ width: '320px', height: '240px' }}
            className="rounded-lg"
            playsInline
          />
          <canvas ref={canvasRef} style={{ display: 'none' }} />
        </div>
      )}
      {status === 'ANALYZING' && (
        <Loader2 className="animate-spin mr-2" />
      )}
    </div>
  );
};

export default VerifyDocument;
```


