      if (rand > 0.3 && rand < 0.8) {
        setStats(prev => ({ ...prev, verify24h: prev.verify24h + 1 }));
        setActivityData(prev => {
          const newData = [...prev];
          newData[6].verify += 1;
          return newData;
        });
        if (rand > 0.7) { // smaller chance for log
             setLogs(prev => [...prev.slice(-19), {
              time: new Date().toLocaleTimeString(),
              msg: `Verification Request: ${Math.random().toString(36).substring(7)} processed`,
              type: 'info'
            }]);
        }
