export const Dashboard = () => {
  const [isLive, setIsLive] = useState(false);
  const [simulationSpeed, setSimulationSpeed] = useState<'SLOW' | 'NORMAL' | 'FAST'>('NORMAL');
  const [activityData, setActivityData] = useState(INITIAL_ACTIVITY_DATA);
  const [recentDocs, setRecentDocs] = useState(INITIAL_DOCS);
  const [stats, setStats] = useState({
    total: 12450,
    verify24h: 842,
    fraud: 128,
    issuers: 45
  });
  const [logs, setLogs] = useState<{time: string, msg: string, type: 'info' | 'success' | 'warning' | 'error'}[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    // Could add toast here
  };

  // Scroll logs to bottom
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs]);

  // Simulation Logic
  useEffect(() => {
    if (!isLive) return;

    const intervalTime = simulationSpeed === 'FAST' ? 800 : simulationSpeed === 'SLOW' ? 3000 : 1500;

    const interval = setInterval(() => {
      const rand = Math.random();

      // 30% chance to add a new document
      if (rand < 0.3) {
        const newDoc = generateRandomDoc();
        setRecentDocs(prev => [newDoc, ...prev.slice(0, 9)]);
        setStats(prev => ({ ...prev, total: prev.total + 1 }));
        setLogs(prev => [...prev.slice(-19), {
          time: new Date().toLocaleTimeString(),
          msg: `New Block Mined: Document ${newDoc.id} registered by ${newDoc.issuer}`,
          type: 'success'
        }]);
      }

      // 50% chance to increment verifications
      if (rand > 0.3 && rand < 0.8) {
        setStats(prev => ({ ...prev, verify24h: prev.verify24h + 1 }));
        setActivityData(prev => {
          const newData = [...prev];
          const lastIndex = newData.length - 1;
          // Create a shallow copy of the object being updated to avoid mutating read-only properties
          newData[lastIndex] = { 
            ...newData[lastIndex], 
            verify: newData[lastIndex].verify + 1 
          };
          return newData;
        });
        if (rand > 0.7) { // smaller chance for log
             setLogs(prev => [...prev.slice(-19), {
              time: new Date().toLocaleTimeString(),
              msg: `Verification Request: ${Math.random().toString(36).substring(7)} processed`,
              type: 'info'
            }]);
        }
      }

      // 5% chance of fraud attempt
      if (rand > 0.95) {
        setStats(prev => ({ ...prev, fraud: prev.fraud + 1 }));
        setLogs(prev => [...prev.slice(-19), {
          time: new Date().toLocaleTimeString(),
          msg: `ALERT: Suspicious hash detected in block proposal!`,
          type: 'error'
        }]);
      }

    }, intervalTime);

    return () => clearInterval(interval);
  }, [isLive, simulationSpeed]);

  return (
    <div className="min-h-screen bg-slate-50 py-8 px-4 sm:px-6 lg:px-8">
