  const [recentDocs, setRecentDocs] = useState(INITIAL_DOCS);
  const [mempool, setMempool] = useState<MempoolTx[]>([]);
  const [blockHeight, setBlockHeight] = useState(1849201);
  const [stats, setStats] = useState({
    total: 12450,
    verify24h: 842,
    fraud: 128,
    issuers: 45
  });
  const [logs, setLogs] = useState<{time: string, msg: string, type: 'info' | 'success' | 'warning' | 'error'}[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    addNotification('info', 'Copied to clipboard');
  };

  // Scroll logs to bottom
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs]);

  // Simulation Logic
  useEffect(() => {
    if (!isLive) return;

    const intervalTime = simulationSpeed === 'FAST' ? 800 : simulationSpeed === 'SLOW' ? 3000 : 1500;

    const interval = setInterval(() => {
      const rand = Math.random();

      // Add tx to mempool
      const newTx: MempoolTx = {
        id: Math.random().toString(36),
        hash: '0x' + Math.random().toString(16).substr(2, 8),
        type: rand > 0.5 ? 'mint' : 'verify',
        color: rand > 0.5 ? 'bg-blue-400' : 'bg-green-400'
      };
      setMempool(prev => [...prev, newTx]);

      // If mempool gets big, mine a block
      if (mempool.length > 8) {
         const minedCount = mempool.length;
         setMempool([]); // Clear pool
         setBlockHeight(prev => prev + 1);
         addNotification('success', `Block #${blockHeight + 1} Mined!`, `${minedCount} transactions processed`);
         setLogs(prev => [...prev.slice(-19), {
            time: new Date().toLocaleTimeString(),
            msg: `Block #${blockHeight + 1} finalized with ${minedCount} txs`,
            type: 'success'
          }]);
      }

      // 30% chance to add a new document (Incoming)
      if (rand < 0.3) {
        const newDoc = { 
            ...generateRandomDoc(), 
            date: new Date().toLocaleTimeString() 
        };
        setRecentDocs(prev => [newDoc, ...prev.slice(0, 9)]);
        setStats(prev => ({ ...prev, total: prev.total + 1 }));
        setLogs(prev => [...prev.slice(-19), {
            time: new Date().toLocaleTimeString(),
            msg: `Incoming Tx: ${newDoc.id} - Status: PENDING`,
            type: 'info'
        }]);
      }

      // Update Pending Documents (Simulate Processing)
      setRecentDocs(prev => prev.map(doc => {
        if (doc.status === 'PENDING') {
            // Chance to complete processing
            if (Math.random() > 0.6) {
                const isSuccess = Math.random() > 0.1;
                const newStatus = isSuccess ? 'ACTIVE' : (Math.random() > 0.5 ? 'SUSPICIOUS' : 'REVOKED');
                return { ...doc, status: newStatus };
            }
        }
        return doc;
      }));

      // 50% chance to increment verifications
      if (rand > 0.3 && rand < 0.8) {
        setStats(prev => ({ ...prev, verify24h: prev.verify24h + 1 }));
        setActivityData(prev => {
          const newData = [...prev];
          const lastIndex = newData.length - 1;
          newData[lastIndex] = { 
            ...newData[lastIndex], 
            verify: newData[lastIndex].verify + 1 
          };
          return newData;
        });
      }

      // Network Alerts (Real-time notifications)
      if (rand > 0.96) {
        setStats(prev => ({ ...prev, fraud: prev.fraud + 1 }));
        addNotification('warning', 'Suspicious Activity Detected', 'Flagged by AI sentinel node');
        setLogs(prev => [...prev.slice(-19), {
          time: new Date().toLocaleTimeString(),
          msg: `ALERT: Suspicious hash detected in block proposal!`,
          type: 'error'
        }]);
      } else if (rand > 0.92) {
         addNotification('success', 'Verification Confirmed', `Node 0x${Math.floor(Math.random()*1000)} just verified Batch #${Math.floor(Math.random()*1000)}`);
      }

    }, intervalTime);

    return () => clearInterval(interval);
  }, [isLive, simulationSpeed, mempool.length, blockHeight, addNotification]);

