        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Search, FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash, QrCode, Camera, Loader2, X, Image as ImageIcon } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';
import jsQR from 'jsqr';

export const VerifyDocument = () => {
  const { addNotification } = useNotification();
  const { addVerification } = useGlobalStore();
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hashInput, setHashInput] = useState('');
  const [status, setStatus] = useState<'IDLE' | 'ANALYZING' | 'COMPLETE'>('IDLE');
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);

  // QR Scanning Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  // Cleanup camera on unmount or method change
  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  useEffect(() => {
    if (method === VerificationMethod.QR) {
      startCamera();
    } else {
      stopCamera();
    }
  }, [method]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      // Request camera access
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute("playsinline", "true"); // required for iOS
        await videoRef.current.play();
        requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setCameraError("Unable to access camera. Please ensure permissions are granted.");
      addNotification('error', 'Camera access denied');
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const tick = () => {
    if (videoRef.current && videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      if (canvas) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        const ctx = canvas.getContext("2d", { willReadFrequently: true });

        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

          // Attempt to find QR code
          const code = jsQR(imageData.data, imageData.width, imageData.height, {
            inversionAttempts: "dontInvert",
          });

          if (code) {
            handleQrDetected(code.data);
            return; // Stop the loop
          }
        }
      }
    }
    // Continue scanning if no code found and camera is still active
    if (streamRef.current && streamRef.current.active) {
      animationFrameRef.current = requestAnimationFrame(tick);
    }
  };

  const handleQrDetected = (data: string) => {
    stopCamera();
    setHashInput(data);
    setMethod(VerificationMethod.HASH); // Switch UI to hash view
    addNotification('success', 'QR Code Detected', 'Processing hash...');
    handleVerify(data); // Auto-trigger verification
  };

  const handleFileSelection = (selectedFile: File) => {
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }

    setFile(selectedFile);

    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleVerify = async (manualHash?: string) => {
    setStatus('ANALYZING');
    setProgress(0);
    setResult(null);

    // Simulate progress
    const progressInterval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 90) return prev;
        return prev + Math.random() * 20;
      });
    }, 200);

    try {
      let docHash = manualHash || hashInput;
      let fileTextContext = "No text extracted (Hash mode)";

      if (method === VerificationMethod.FILE && file) {
        docHash = await BlockchainService.calculateHash(file);
        // Simulate extracting text for AI
        fileTextContext = "This certifies that John Doe has successfully completed the Bachelor of Science program..."; 
      }

      const blockchainDoc = await BlockchainService.verifyDocument(docHash);

      const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in registry.";
      const aiAnalysis = await GeminiService.analyzeDocumentAuthenticity(fileTextContext, metadataContext);

      const verificationResult: VerificationResult = {
        isValid: !!blockchainDoc && blockchainDoc.status === 'ACTIVE' && aiAnalysis.isAuthentic,
        document: blockchainDoc || undefined,
        aiAnalysis
      };

      clearInterval(progressInterval);
      setProgress(100);
      await new Promise(r => setTimeout(r, 400)); // smooth finish

      setResult(verificationResult);

      // Update Global Stats
      addVerification(verificationResult.isValid);

      if (verificationResult.isValid) {
        addNotification('success', 'Document Verified', 'Authenticity confirmed by Blockchain & AI');
      } else {
        addNotification('error', 'Verification Failed', 'Document appears forged or invalid');
      }

    } catch (error) {
      clearInterval(progressInterval);
      console.error(error);
      addNotification('error', 'Verification error occurred');
    } finally {
      setStatus('COMPLETE');
      setProgress(0);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="text-3xl font-bold text-slate-900">Verify Document Authenticity</h1>
          <p className="mt-2 text-slate-600">Combine Blockchain immutability with AI forensics.</p>
        </div>

        <div className="bg-white rounded-2xl shadow-lg overflow-hidden mb-8">
          <div className="flex border-b border-slate-200">
            <button 
              onClick={() => setMethod(VerificationMethod.FILE)}
              className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 ${method === VerificationMethod.FILE ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <UploadCloud className="w-5 h-5" />
              <span>Upload File</span>
            </button>
            <button 
              onClick={() => setMethod(VerificationMethod.HASH)}
              className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 ${method === VerificationMethod.HASH ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <Hash className="w-5 h-5" />
              <span>Enter Hash</span>
            </button>
            <button 
              onClick={() => setMethod(VerificationMethod.QR)}
              className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 ${method === VerificationMethod.QR ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <QrCode className="w-5 h-5" />
              <span>Scan QR</span>
            </button>
          </div>

          <div className="p-8">
            {method === VerificationMethod.FILE && (
              <div className="space-y-4">
                {!file ? (
                  <div 
                    onDragOver={onDragOver}
                    onDragLeave={onDragLeave}
                    onDrop={onDrop}
                    className={`border-2 border-dashed rounded-xl p-10 text-center transition-all duration-200 ease-in-out cursor-pointer ${
                        isDragging 
                          ? 'border-brand-500 bg-brand-50 scale-[1.02]' 
                          : 'border-slate-300 hover:bg-slate-50 hover:border-brand-300'
                    }`}
                  >
                    <input 
                      type="file" 
                      id="verify-upload" 
                      className="hidden" 
                      onChange={(e) => e.target.files && handleFileSelection(e.target.files[0])}
                      accept=".pdf,.png,.jpg,.jpeg"
                    />
                    <label htmlFor="verify-upload" className="cursor-pointer block h-full w-full">
                      <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4 transition-colors ${
                          isDragging ? 'bg-brand-200' : 'bg-blue-50'
                      }`}>
                        <FileSearch className={`h-8 w-8 ${isDragging ? 'text-brand-700' : 'text-brand-600'}`} />
                      </div>
                      <span className="text-brand-600 font-bold text-lg">
                         {isDragging ? 'Drop file to verify' : 'Choose Document'}
                      </span>
                      <p className="text-slate-500 mt-2">Upload the PDF or Image to verify</p>
                    </label>
                  </div>
                ) : (
                  <div className="relative border border-slate-200 rounded-xl p-4 bg-slate-50 flex items-center space-x-4 animate-fadeIn">
                      {previewUrl ? (
                        <img src={previewUrl} alt="Preview" className="w-16 h-16 object-cover rounded-lg border border-slate-200" />
                      ) : (
                        <div className="w-16 h-16 rounded-lg bg-white border border-slate-200 flex items-center justify-center">
                          <ImageIcon className="w-8 h-8 text-slate-400" />
                        </div>
                      )}

                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-slate-900 truncate">
                          {file.name}
                        </p>
                        <p className="text-xs text-slate-500">
                          {(file.size / 1024 / 1024).toFixed(2)} MB
                        </p>
                        <p className="text-xs text-brand-600 mt-1">Ready to verify</p>
                      </div>

                      {(status === 'IDLE' || status === 'COMPLETE') && (
                        <button 
                          onClick={clearFile}
                          type="button"
                          className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                        >
                          <X className="w-5 h-5" />
                        </button>
                      )}
                    </div>
                )}
              </div>
            )}

            {method === VerificationMethod.HASH && (
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">Document Hash (SHA-256)</label>
                <input 
                  type="text" 
                  className="w-full px-4 py-3 border border-slate-300 rounded-lg font-mono text-sm"
                  placeholder="e.g. e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
                  value={hashInput}
                  onChange={(e) => setHashInput(e.target.value)}
                />
              </div>
            )}

            {method === VerificationMethod.QR && (
              <div className="flex flex-col items-center justify-center">
                {cameraError ? (
                  <div className="text-red-600 bg-red-50 p-4 rounded-lg flex items-center mb-4">
                    <ShieldAlert className="w-5 h-5 mr-2" />
                    {cameraError}
                  </div>
                ) : (
                  <div className="relative w-full max-w-sm aspect-square bg-black rounded-xl overflow-hidden shadow-inner">
                    <video 
                      ref={videoRef} 
                      className="absolute inset-0 w-full h-full object-cover" 
                      muted 
                    />
                    <canvas ref={canvasRef} className="hidden" />

                    {/* Scanner Overlay UI */}
                    <div className="absolute inset-0 border-2 border-brand-500/50 flex items-center justify-center">
                      <div className="w-64 h-64 border-2 border-brand-400 rounded-lg relative animate-pulse">
                        <div className="absolute top-0 left-0 w-4 h-4 border-t-4 border-l-4 border-brand-500 -mt-1 -ml-1"></div>
                        <div className="absolute top-0 right-0 w-4 h-4 border-t-4 border-r-4 border-brand-500 -mt-1 -mr-1"></div>
                        <div className="absolute bottom-0 left-0 w-4 h-4 border-b-4 border-l-4 border-brand-500 -mb-1 -ml-1"></div>
                        <div className="absolute bottom-0 right-0 w-4 h-4 border-b-4 border-r-4 border-brand-500 -mb-1 -mr-1"></div>
                      </div>
                    </div>

                    <div className="absolute bottom-4 left-0 right-0 text-center">
                      <span className="bg-black/50 text-white px-3 py-1 rounded-full text-sm backdrop-blur-sm">
                        Align QR Code within frame
                      </span>
                    </div>
                  </div>
                )}
              </div>
            )}

            {method !== VerificationMethod.QR && (
              <>
                {status === 'ANALYZING' ? (
                  <div className="mt-6 w-full bg-slate-50 rounded-lg p-4 border border-slate-100">
                    <div className="flex justify-between text-sm mb-2 text-slate-600 font-medium">
                      <span className="flex items-center"><Loader2 className="animate-spin w-4 h-4 mr-2 text-brand-600"/> Verifying...</span>
                      <span>{Math.round(progress)}%</span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                      <div 
                        className="bg-brand-600 h-2.5 rounded-full transition-all duration-300 ease-out" 
                        style={{ width: `${progress}%` }}
                      ></div>
                    </div>
                    <p className="text-center text-xs text-slate-400 mt-2">Running Blockchain & AI Forensics</p>
                  </div>
                ) : (
                  <button 
                    onClick={() => handleVerify()}
                    disabled={(method === 'FILE' && !file) || (method === 'HASH' && !hashInput)}
                    className="mt-6 w-full py-3 bg-brand-600 text-white rounded-lg font-bold hover:bg-brand-700 transition-colors disabled:opacity-50 flex justify-center items-center shadow-md active:scale-[0.99]"
                  >
                    Verify Document
                  </button>
                )}
              </>
            )}
          </div>
        </div>

        {status === 'COMPLETE' && result && (
          <div className={`rounded-2xl shadow-xl overflow-hidden border-t-8 ${result.isValid ? 'border-green-500' : 'border-red-500'} bg-white animate-slideUp`}>
            <div className={`p-6 flex items-center justify-between ${result.isValid ? 'bg-green-50' : 'bg-red-50'}`}>
              <div className="flex items-center space-x-4">
                {result.isValid ? (
                  <CheckCircle className="w-10 h-10 text-green-600" />
                ) : (
                  <ShieldAlert className="w-10 h-10 text-red-600" />
                )}
                <div>
                  <h2 className="text-2xl font-bold text-slate-900">
                    {result.isValid ? 'Authentic Document' : 'Verification Failed'}
                  </h2>
                  <p className="text-sm text-slate-600">
                    {result.isValid ? 'Verified by Blockchain & AI' : 'Tampering or Forgery Detected'}
                  </p>
                </div>
              </div>
              <div className="text-right">
                <div className="text-sm text-slate-500">Confidence Score</div>
                <div className="text-xl font-bold text-slate-900">{(result.aiAnalysis?.confidence || 0) * 100}%</div>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-6 p-8">
              <div className="space-y-4">
                <h3 className="font-semibold text-slate-900 flex items-center">
                  <FileCheck className="w-5 h-5 mr-2 text-brand-600" />
                  Blockchain Evidence
                </h3>
                {result.document ? (
                  <div className="bg-slate-50 rounded-lg p-4 space-y-3 text-sm">
                    <div>
                      <span className="block text-slate-500 text-xs">Issuer</span>
                      <span className="font-medium text-slate-900">{result.document.issuerName}</span>
                    </div>
                    <div>
                      <span className="block text-slate-500 text-xs">Timestamp</span>
                      <span className="font-mono text-slate-700">{new Date(result.document.createdAt).toLocaleString()}</span>
                    </div>
                    <div>
                      <span className="block text-slate-500 text-xs">Hash Match</span>
                      <span className="text-green-600 font-bold">MATCHED (SHA-256)</span>
                    </div>
                  </div>
                ) : (
                  <div className="p-4 bg-red-50 text-red-700 rounded-lg text-sm">
                    Hash not found in the decentralized registry.
                  </div>
                )}
              </div>

              <div className="space-y-4">
                <h3 className="font-semibold text-slate-900 flex items-center">
                  <Brain className="w-5 h-5 mr-2 text-purple-600" />
                  AI Forgery Detection
                </h3>
                <div className="bg-slate-50 rounded-lg p-4 text-sm">
                  <p className="text-slate-700 mb-3 italic">"{result.aiAnalysis?.reasoning}"</p>

                  {result.aiAnalysis?.flags && result.aiAnalysis.flags.length > 0 && (
                    <div className="space-y-1">
                      {result.aiAnalysis.flags.map((flag, i) => (
                        <div key={i} className="inline-flex items-center px-2 py-1 rounded bg-red-100 text-red-700 text-xs mr-2">
                          {flag}
                        </div>
                      ))}
                    </div>
                  )}

                  {result.aiAnalysis?.isAuthentic && (
                    <div className="mt-2 text-green-600 font-medium text-xs flex items-center">
                      <CheckCircle className="w-3 h-3 mr-1" />
                      No structural manipulation detected
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

