import React, { useState, useRef, useEffect } from 'react';
import { Search, FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash, QrCode, Camera, Loader2, X, Image as ImageIcon } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';
import jsQR from 'jsqr';

export const VerifyDocument = () => {
  const { addNotification } = useNotification();
  const { addVerification } = useGlobalStore();
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hashInput, setHashInput] = useState('');
  const [status, setStatus] = useState<'IDLE' | 'ANALYZING' | 'COMPLETE'>('IDLE');
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);

  // QR Scanning Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  // Cleanup camera on unmount or method change
  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  useEffect(() => {
    if (method === VerificationMethod.QR) {
      startCamera();
    } else {
      stopCamera();
    }
  }, [method]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      // Request camera access
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute("playsinline", "true"); // required for iOS
        await videoRef.current.play();
        requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setCameraError("Unable to access camera. Please ensure permissions are granted.");
      addNotification('error', 'Camera access denied');
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const tick = () => {
    // Check if camera is still active
    if (!videoRef.current || !streamRef.current) return;

    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      if (canvas) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        const ctx = canvas.getContext("2d", { willReadFrequently: true });

        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

          // Attempt to find QR code
          const code = jsQR(imageData.data, imageData.width, imageData.height, {
            inversionAttempts: "dontInvert",
          });

          if (code) {
            handleQrDetected(code.data);
            return; // Stop the loop
          }
        }
      }
    }

    // Continue loop
    animationFrameRef.current = requestAnimationFrame(tick);
  };

  const handleQrDetected = (data: string) => {
    stopCamera();
    setHashInput(data);
    setMethod(VerificationMethod.HASH); // Switch UI to hash view
    addNotification('success', 'QR Code Detected', 'Processing hash...');
    handleVerify(data); // Auto-trigger verification
  };

  const handleFileSelection = (selectedFile: File) => {
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }

    setFile(selectedFile);

    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleVerify = async (manualHash?: string) => {
    setStatus('ANALYZING');
    setProgress(0);
    setResult(null);

    // Simulate progress
    const progressInterval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 90) return prev;
        return prev + Math.random() * 20;
      });
    }, 200);

    try {
      let docHash = manualHash || hashInput;
      let fileTextContext = "No text extracted (Hash mode)";

      if (method === VerificationMethod.FILE && file) {
        docHash = await BlockchainService.calculateHash(file);
        // Simulate extracting text for AI
        fileTextContext = "This certifies that John Doe has successfully completed the Bachelor of Science program..."; 
      }

      const blockchainDoc = await BlockchainService.verifyDocument(docHash);

      const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in registry.";
      const aiAnalysis = await GeminiService.analyzeDocumentAuthenticity(fileTextContext, metadataContext);

      const verificationResult: VerificationResult = {
        isValid: !!blockchainDoc && blockchainDoc.status === 'ACTIVE' && aiAnalysis.isAuthentic,
        document: blockchainDoc || undefined,
        aiAnalysis
      };

      clearInterval(progressInterval);
      setProgress(100);
      await new Promise(r => setTimeout(r, 400)); // smooth finish

      setResult(verificationResult);

      // Update Global Stats
      addVerification(verificationResult.isValid);

      if (verificationResult.isValid) {
        addNotification('success', 'Document Verified', 'Authenticity confirmed by Blockchain & AI');
      } else {
        addNotification('error', 'Verification Failed', 'Document appears forged or invalid');
      }

    } catch (error) {
      clearInterval(progressInterval);
      console.error(error);
      addNotification('error', 'Verification error occurred');
    } finally {
      setStatus('COMPLETE');
      setProgress(0);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-12">
