                          {file.name}
                        </p>
                        <p className="text-xs text-slate-500">
                          {(file.size / 1024 / 1024).toFixed(2)} MB
                        </p>
                      </div>

                      {!isProcessing && (
                        <button 
                          onClick={clearFile}
                          type="button"
                          className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                        >
                          <X className="w-5 h-5" />
                        </button>
                      )}
                    </div>
                  )}
                </div>

                {isProcessing ? (
                  <div className="w-full bg-slate-50 rounded-lg p-4 border border-slate-100">
                    <div className="flex justify-between text-sm mb-2 text-slate-600 font-medium">
                      <span>Securing Document...</span>
                      <span>{Math.round(uploadProgress)}%</span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                      <div 
                        className="bg-brand-600 h-2.5 rounded-full transition-all duration-300 ease-out" 
                        style={{ width: `${uploadProgress}%` }}
                      ></div>
                    </div>
                    <p className="text-center text-xs text-slate-400 mt-3 animate-pulse">Encrypting & Anchoring to Sepolia Testnet</p>
                  </div>
                ) : (
                  <button 
                    type="submit"
                    disabled={!file}
                    className="w-full py-3 bg-brand-600 text-white rounded-lg font-bold text-lg hover:bg-brand-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center shadow-lg hover:shadow-xl transform active:scale-[0.98]"
                  >
                    Register Document
                  </button>
                )}
              </div>
            </form>
          )}

          {/* Step 3: Success */}
          {step === 3 && registeredDoc && (
            <div className="p-10 text-center animate-fadeIn">
              <div className="mx-auto w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mb-6">
                <CheckCircle2 className="h-10 w-10 text-green-600" />
              </div>
              <h2 className="text-3xl font-bold text-slate-900 mb-2">Registration Successful!</h2>
              <p className="text-slate-600 mb-8">
