};

import React, { useState, useEffect } from 'react';
import { Upload, FileText, Wallet, Loader2, CheckCircle2, X, Copy, LogOut, Download } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { DocumentMetadata } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';

export const CreateDocument = () => {
  const { addNotification } = useNotification();
  const { addDocument } = useGlobalStore();
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [walletAddress, setWalletAddress] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [registeredDoc, setRegisteredDoc] = useState<DocumentMetadata | null>(null);

  const [formData, setFormData] = useState({
    title: '',
    issuerName: '',
    type: 'Certificate',
    description: ''
  });

  // Attempt to auto-connect if wallet was previously connected
  useEffect(() => {
    const savedAddress = localStorage.getItem('trustchain_wallet');
    if (savedAddress) {
      setWalletAddress(savedAddress);
    }
  }, []);

  const connectWallet = async () => {
    try {
      const address = await BlockchainService.connectWallet();
      setWalletAddress(address);
      localStorage.setItem('trustchain_wallet', address);
      addNotification('success', 'Wallet Connected Successfully', 'Connected to Sepolia Testnet');
    } catch (err) {
      addNotification('error', 'Failed to connect wallet');
    }
  };

  const handleFileSelection = (selectedFile: File) => {
    // Basic validation
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }

    setFile(selectedFile);

    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFileSelection(e.target.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!walletAddress || !file) return;

    setIsProcessing(true);
    setUploadProgress(0);

    // Simulate progress
    const progressInterval = setInterval(() => {
      setUploadProgress(prev => {
        if (prev >= 90) return prev;
        return prev + Math.random() * 15;
      });
    }, 400);

    try {
      // 1. Calculate Hash
      const hash = await BlockchainService.calculateHash(file);
      addNotification('info', 'File Hashed locally (SHA-256)', 'Security check passed');

      // 2. Mock IPFS Upload (In production: await IpfsService.upload(file))
      const ipfsCid = "QmMockCidForDemoPurposeOnly12345"; 

      // 3. Register on Blockchain
      const newDoc = await BlockchainService.registerDocument({
        title: formData.title,
        issuerName: formData.issuerName,
        type: formData.type,
        description: formData.description,
        hash,
        ipfsCid
      });

      // Update Global Store for Real-time Dashboard
      addDocument(newDoc);

      clearInterval(progressInterval);
      setUploadProgress(100);

      // Artificial delay to show 100% completion
      await new Promise(resolve => setTimeout(resolve, 600));

      setRegisteredDoc(newDoc);
      setStep(3);
      addNotification('success', 'Document Registered!', 'Transaction confirmed on blockchain');
    } catch (err) {
      clearInterval(progressInterval);
      console.error(err);
      addNotification('error', 'Registration failed', 'Please try again');
    } finally {
      setIsProcessing(false);
      setUploadProgress(0);
    }
  };

  const downloadReceipt = () => {
    if (!registeredDoc) return;

    const receiptData = {
      ...registeredDoc,
      transactionId: '0x7f...3a9c',
      network: 'Sepolia Testnet',
      timestamp: new Date().toISOString(),
      platform: 'TrustChain AI - Secure Document Verification',
      verificationLink: window.location.origin + '/#/verify' 
    };

    const blob = new Blob([JSON.stringify(receiptData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `trustchain-receipt-${registeredDoc.id}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    addNotification('success', 'Receipt downloaded successfully');
  };

  const copyAddress = () => {
    if (walletAddress) {
        navigator.clipboard.writeText(walletAddress);
        addNotification('info', 'Address copied to clipboard');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-3xl mx-auto">
        <div className="mb-10 text-center">
          <h1 className="text-3xl font-bold text-slate-900">Register New Document</h1>
          <p className="mt-2 text-slate-600">Securely anchor your document to the blockchain.</p>
        </div>

        {/* Progress Steps */}
        <div className="mb-8 flex justify-center items-center space-x-4">
          {[1, 2, 3].map((s) => (
            <div key={s} className={`flex items-center ${s < 3 ? 'w-full' : ''}`}>
               <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${
                 step >= s ? 'bg-brand-600 text-white' : 'bg-slate-200 text-slate-500'
               }`}>
                 {s}
               </div>
               {s < 3 && <div className={`h-1 flex-1 mx-2 ${step > s ? 'bg-brand-600' : 'bg-slate-200'}`} />}
            </div>
          ))}
        </div>

        <div className="bg-white shadow-xl rounded-2xl overflow-hidden">
          {/* Step 1: Wallet Connection */}
          {step === 1 && (
            <div className="p-10">
              <div className="text-center mb-8">
                <div className="mx-auto w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-6">
                  <Wallet className="h-8 w-8 text-brand-600" />
                </div>
                <h2 className="text-2xl font-bold text-slate-900 mb-2">Connect Wallet</h2>
                <p className="text-slate-600 max-w-md mx-auto">
                  Connect your organization's verified wallet to sign transactions and pay gas fees.
                </p>
              </div>

              {!walletAddress ? (
                <div className="flex justify-center">
                    <button 
                    onClick={connectWallet}
                    className="inline-flex items-center px-8 py-4 border border-transparent text-lg font-medium rounded-xl text-white bg-brand-600 hover:bg-brand-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-500 shadow-lg hover:shadow-xl transition-all transform hover:-translate-y-0.5"
                    >
                    {/* Using simple SVG icon instead of external image for reliability */}
                    <div className="w-6 h-6 mr-3 bg-white rounded-full flex items-center justify-center p-0.5">
                       <Wallet className="w-4 h-4 text-brand-600" />
                    </div>
                    Connect MetaMask
                    </button>
                </div>
              ) : (
                <div className="max-w-md mx-auto bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden animate-fadeIn">
                    <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex justify-between items-center">
                        <div className="flex items-center space-x-2">
                        <span className="relative flex h-2.5 w-2.5">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-green-500"></span>
                        </span>
                        <span className="text-sm font-semibold text-slate-700">Connected</span>
                        </div>
                        <span className="text-xs font-mono font-medium text-brand-600 bg-brand-50 px-2 py-1 rounded">Sepolia Testnet</span>
                    </div>

                    <div className="p-6">
                        <div className="flex items-center space-x-4 mb-6">
                            <div className="w-12 h-12 rounded-full bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white shadow-md">
                                <Wallet className="w-6 h-6" />
                            </div>
                            <div className="flex-1 overflow-hidden">
                                <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Wallet Address</p>
                                <div className="flex items-center space-x-2">
                                    <span className="font-mono text-lg font-bold text-slate-900 truncate">
                                        {walletAddress.slice(0, 6)}...{walletAddress.slice(-6)}
                                    </span>
                                    <button 
                                        onClick={copyAddress}
                                        className="text-slate-400 hover:text-brand-600 transition-colors p-1"
