                    <div className="relative border border-slate-200 rounded-xl p-4 bg-slate-50 flex items-center space-x-4 animate-fadeIn">
                      {previewUrl ? (
                        <img src={previewUrl} alt="Preview" className="w-16 h-16 object-cover rounded-lg border border-slate-200" />
                      ) : (
                        <div className="w-16 h-16 rounded-lg bg-white border border-slate-200 flex items-center justify-center">
                          <FileText className="w-8 h-8 text-slate-400" />
                        </div>
                      )}

                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-slate-900 truncate">
                          {file.name}
                        </p>
                        <p className="text-xs text-slate-500">
                          {(file.size / 1024 / 1024).toFixed(2)} MB
                        </p>
                      </div>

                      {!isProcessing && (
                        <button 
                          onClick={clearFile}
                          type="button"
                          className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                        >
                          <X className="w-5 h-5" />
                        </button>
                      )}
                    </div>
                  )}
                </div>

                {isProcessing ? (
                  <div className="w-full bg-slate-50 rounded-lg p-4 border border-slate-100">
                    <div className="flex justify-between text-sm mb-2 text-slate-600 font-medium">
                      <span>Securing Document...</span>
                      <span>{Math.round(uploadProgress)}%</span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                      <div 
                        className="bg-brand-600 h-2.5 rounded-full transition-all duration-300 ease-out" 
                        style={{ width: `${uploadProgress}%` }}
                      ></div>
                    </div>
                    <p className="text-center text-xs text-slate-400 mt-3 animate-pulse">Encrypting & Anchoring to Sepolia Testnet</p>
                  </div>
                ) : (
                  <button 
                    type="submit"
                    disabled={!file}
                    className="w-full py-3 bg-brand-600 text-white rounded-lg font-bold text-lg hover:bg-brand-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center shadow-lg hover:shadow-xl transform active:scale-[0.98]"
                  >
                    Register Document
                  </button>
                )}
              </div>
            </form>
          )}

          {/* Step 3: Success */}
          {step === 3 && registeredDoc && (
            <div className="p-10 text-center animate-fadeIn">
              <div className="mx-auto w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mb-6">
                <CheckCircle2 className="h-10 w-10 text-green-600" />
              </div>
              <h2 className="text-3xl font-bold text-slate-900 mb-2">Registration Successful!</h2>
              <p className="text-slate-600 mb-8">
                Your document has been cryptographically secured on the blockchain.
              </p>

              <div className="bg-slate-50 p-6 rounded-xl text-left space-y-4 mb-8">
                <div className="flex justify-between border-b border-slate-200 pb-2">
                  <span className="text-slate-500">Document Hash</span>
                  <span className="font-mono text-sm text-slate-900">{registeredDoc.hash.slice(0, 20)}...</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-2">
                  <span className="text-slate-500">Transaction ID</span>
                  <span className="font-mono text-sm text-brand-600 cursor-pointer">0x7f...3a9c</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Status</span>
                  <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                    ACTIVE
                  </span>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-4 justify-center">
                  <button 
                    onClick={downloadReceipt}
                    className="inline-flex items-center justify-center px-6 py-3 border border-slate-200 shadow-sm text-base font-bold rounded-xl text-slate-700 bg-white hover:bg-slate-50 hover:border-slate-300 transition-all"
                  >
                    <Download className="w-5 h-5 mr-2 text-brand-600" />
                    Download Receipt
                  </button>
                  <button 
                    onClick={() => window.location.reload()}
                    className="inline-flex items-center justify-center px-6 py-3 border border-transparent text-base font-bold rounded-xl text-white bg-brand-600 hover:bg-brand-700 shadow-md hover:shadow-lg transition-all"
                  >
                    Register Another
                  </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

