  title: string;
  message: string;
  type: 'success' | 'error' | 'warning' | 'info';
  timestamp: string;
}

interface GlobalState {
  isLive: boolean;
  setIsLive: (val: boolean) => void;
  simulationSpeed: 'SLOW' | 'NORMAL' | 'FAST';
  setSimulationSpeed: (val: 'SLOW' | 'NORMAL' | 'FAST') => void;
  recentDocs: any[];
  activityData: any[];
  stats: {
    total: number;
    verify24h: number;
    fraud: number;
    issuers: number;
  };
  mempool: MempoolTx[];
  blockHeight: number;
  logs: {time: string, msg: string, type: 'info' | 'success' | 'warning' | 'error'}[];
  latestAlert: SystemAlert | null;
  dismissAlert: () => void;
  addDocument: (doc: DocumentMetadata) => void;
  addVerification: (isValid: boolean) => void;
}

const GlobalContext = createContext<GlobalState | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { addNotification } = useNotification();
  const [isLive, setIsLive] = useState(true); // Default to true for "Real-time" feel
  const [simulationSpeed, setSimulationSpeed] = useState<'SLOW' | 'NORMAL' | 'FAST'>('NORMAL');

  const [recentDocs, setRecentDocs] = useState<any[]>(INITIAL_DOCS);
  const [activityData, setActivityData] = useState(INITIAL_ACTIVITY_DATA);
  const [mempool, setMempool] = useState<MempoolTx[]>([]);
  const [blockHeight, setBlockHeight] = useState(1849201);
  const [stats, setStats] = useState({
    total: 12450,
    verify24h: 842,
    fraud: 128,
    issuers: 45
  });
  const [logs, setLogs] = useState<{time: string, msg: string, type: 'info' | 'success' | 'warning' | 'error'}[]>([]);
  const [latestAlert, setLatestAlert] = useState<SystemAlert | null>(null);

  const dismissAlert = useCallback(() => setLatestAlert(null), []);

  // Add a real document from CreateDocument page
  const addDocument = useCallback((doc: DocumentMetadata) => {
    const newDoc = {
      id: doc.id,
      title: doc.title,
      type: doc.type,
      issuer: doc.issuerName,
      date: new Date().toLocaleTimeString(),
      status: 'PENDING', // Start as pending to show processing
      ipfsCid: doc.ipfsCid
    };
    setRecentDocs(prev => [newDoc, ...prev.slice(0, 9)]);
    setStats(prev => ({ ...prev, total: prev.total + 1 }));
    setLogs(prev => [...prev.slice(-19), {
      time: new Date().toLocaleTimeString(),
      msg: `New User Registration: ${doc.title}`,
      type: 'info'
    }]);

    // Add to mempool
    setMempool(prev => [...prev, {
      id: Math.random().toString(36),
      hash: doc.hash.substring(0, 10),
      type: 'mint',
      color: 'bg-blue-500'
    }]);

    // Show alert for the new document
    setLatestAlert({
        id: Math.random().toString(),
        title: 'Transaction Submitted',
        message: `Registering "${doc.title}" on Sepolia network...`,
        type: 'info',
        timestamp: new Date().toLocaleTimeString()
    });
    setTimeout(() => setLatestAlert(null), 5000);

  }, []);

  const addVerification = useCallback((isValid: boolean) => {
    setStats(prev => ({ 
      ...prev, 
      verify24h: prev.verify24h + 1,
      fraud: !isValid ? prev.fraud + 1 : prev.fraud
    }));

    setLogs(prev => [...prev.slice(-19), {
      time: new Date().toLocaleTimeString(),
      msg: `User Verification: ${isValid ? 'Success' : 'Failed/Fraud Detected'}`,
      type: isValid ? 'success' : 'error'
    }]);

    setMempool(prev => [...prev, {
      id: Math.random().toString(36),
      hash: '0x' + Math.random().toString(16).substr(2, 8),
      type: 'verify',
      color: isValid ? 'bg-green-400' : 'bg-red-400'
    }]);
  }, []);

  // Simulation Logic
  useEffect(() => {
    if (!isLive) return;

    const intervalTime = simulationSpeed === 'FAST' ? 800 : simulationSpeed === 'SLOW' ? 3000 : 1500;

    const interval = setInterval(() => {
      const rand = Math.random();

      // Add random tx to mempool
      if (rand > 0.3) {
        const newTx: MempoolTx = {
          id: Math.random().toString(36),
          hash: '0x' + Math.random().toString(16).substr(2, 8),
          type: rand > 0.6 ? 'mint' : 'verify',
          color: rand > 0.6 ? 'bg-blue-400' : 'bg-green-400'
        };
        setMempool(prev => [...prev, newTx]);
      }

      // Mine Block
      if (mempool.length > 8) {
         const minedCount = mempool.length;
         setMempool([]); 
         setBlockHeight(prev => prev + 1);
         // Don't toast every block to avoid spam, just log
         setLogs(prev => [...prev.slice(-19), {
            time: new Date().toLocaleTimeString(),
            msg: `Block #${blockHeight + 1} mined (${minedCount} txs)`,
            type: 'success'
          }]);
      }

      // Incoming Documents Simulation
      if (rand < 0.2) {
        const newDoc = generateRandomDoc();
        setRecentDocs(prev => [newDoc, ...prev.slice(0, 9)]);
        setStats(prev => ({ ...prev, total: prev.total + 1 }));
      }

      // Process Pending Docs (Simulate status change)
      setRecentDocs(prev => prev.map(doc => {
        if (doc.status === 'PENDING') {
            // Higher chance to process
            if (Math.random() > 0.3) {
                const isSuccess = Math.random() > 0.05;
                const newStatus = isSuccess ? 'ACTIVE' : 'SUSPICIOUS';

                // If this was a user doc (based on title or just random chance for demo effect)
                // Trigger a completion alert for specific cases if needed, but let's keep it clean

                return { ...doc, status: newStatus };
            }
        }
        return doc;
      }));

      // Update Activity Chart
      if (rand > 0.3 && rand < 0.8) {
        setStats(prev => ({ ...prev, verify24h: prev.verify24h + 1 }));
        setActivityData(prev => {
          const newData = [...prev];
          const lastIndex = newData.length - 1;
          newData[lastIndex] = { 
            ...newData[lastIndex], 
            verify: newData[lastIndex].verify + 1 
          };
          return newData;
        });
      }

      // Random Critical Alerts (Simulated)
      if (rand < 0.015) {
        setLatestAlert({
            id: Math.random().toString(),
            title: 'Suspicious Activity',
            message: 'Multiple failed verification attempts from unknown source.',
            type: 'warning',
            timestamp: new Date().toLocaleTimeString()
        });
        setTimeout(() => setLatestAlert(null), 6000);
      } else if (rand > 0.985) {
         setLatestAlert({
            id: Math.random().toString(),
            title: 'System Audit',
            message: 'Automated smart contract audit completed successfully.',
            type: 'success',
            timestamp: new Date().toLocaleTimeString()
        });
        setTimeout(() => setLatestAlert(null), 6000);
      }

    }, intervalTime);

    return () => clearInterval(interval);
  }, [isLive, simulationSpeed, mempool.length, blockHeight]);

  return (
    <GlobalContext.Provider value={{
      isLive, setIsLive,
      simulationSpeed, setSimulationSpeed,
      recentDocs,
      activityData,
      stats,
      mempool,
      blockHeight,
      logs,
      latestAlert,
      dismissAlert,
      addDocument,
      addVerification
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobalStore = () => {
  const context = useContext(GlobalContext);
  if (!context) {
    throw new Error('useGlobalStore must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { Upload, FileText, Wallet, Loader2, CheckCircle2, X, Copy, LogOut, Download, Shield, UploadCloud } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { DocumentMetadata } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';

export const CreateDocument = () => {
  const { addNotification } = useNotification();
  const { addDocument } = useGlobalStore();
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [walletAddress, setWalletAddress] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [registeredDoc, setRegisteredDoc] = useState<DocumentMetadata | null>(null);

  const [formData, setFormData] = useState({
    title: '',
    issuerName: '',
    type: 'Certificate',
    description: ''
  });

  // Attempt to auto-connect if wallet was previously connected
  useEffect(() => {
    const savedAddress = localStorage.getItem('trustchain_wallet');
    if (savedAddress) {
      setWalletAddress(savedAddress);
    }
  }, []);

  const connectWallet = async () => {
    try {
      const address = await BlockchainService.connectWallet();
      setWalletAddress(address);
      localStorage.setItem('trustchain_wallet', address);
      addNotification('success', 'Wallet Connected Successfully', 'Connected to Sepolia Testnet');
    } catch (err) {
      addNotification('error', 'Failed to connect wallet');
    }
  };

  const handleFileSelection = (selectedFile: File) => {
    // Basic validation
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }

    setFile(selectedFile);

    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFileSelection(e.target.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!walletAddress || !file) return;

    setIsProcessing(true);
    setUploadProgress(0);

    // Simulate progress
    const progressInterval = setInterval(() => {
      setUploadProgress(prev => {
        if (prev >= 90) return prev;
        return prev + Math.random() * 15;
      });
    }, 400);

    try {
      // 1. Calculate Hash
      const hash = await BlockchainService.calculateHash(file);
      addNotification('info', 'File Hashed locally (SHA-256)', 'Security check passed');

      // 2. Mock IPFS Upload (In production: await IpfsService.upload(file))
      const ipfsCid = "QmMockCidForDemoPurposeOnly12345"; 

      // 3. Register on Blockchain
      const newDoc = await BlockchainService.registerDocument({
        title: formData.title,
        issuerName: formData.issuerName,
        type: formData.type,
        description: formData.description,
        hash,
        ipfsCid
      });

      // Update Global Store for Real-time Dashboard
      addDocument(newDoc);

      clearInterval(progressInterval);
      setUploadProgress(100);

      // Artificial delay to show 100% completion
      await new Promise(resolve => setTimeout(resolve, 600));

      setRegisteredDoc(newDoc);
      setStep(3);
      addNotification('success', 'Document Registered!', 'Transaction confirmed on blockchain');
    } catch (err) {
      clearInterval(progressInterval);
      console.error(err);
      addNotification('error', 'Registration failed', 'Please try again');
    } finally {
      setIsProcessing(false);
      setUploadProgress(0);
    }
  };

  const downloadReceipt = () => {
    if (!registeredDoc) return;

    const receiptData = {
      ...registeredDoc,
      transactionId: '0x7f...3a9c',
      network: 'Sepolia Testnet',
      timestamp: new Date().toISOString(),
      platform: 'TrustChain AI - Secure Document Verification',
      verificationLink: window.location.origin + '/#/verify' 
    };

    const blob = new Blob([JSON.stringify(receiptData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `trustchain-receipt-${registeredDoc.id}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    addNotification('success', 'Receipt downloaded successfully');
  };

  const copyAddress = () => {
    if (walletAddress) {
        navigator.clipboard.writeText(walletAddress);
        addNotification('info', 'Address copied to clipboard');
