import React, { useState, useRef, useEffect } from 'react';
import { FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash, QrCode, Loader2, X, Image as ImageIcon, Shield, CheckCircle2, Sparkles, FileWarning } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';
import jsQR from 'jsqr';

export const VerifyDocument = () => {
  const { addNotification } = useNotification();
  const { addVerification } = useGlobalStore();
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hashInput, setHashInput] = useState('');
  const [status, setStatus] = useState<'IDLE' | 'ANALYZING' | 'COMPLETE'>('IDLE');
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);

  // QR Scanning Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  // Cleanup camera on unmount or method change
  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  useEffect(() => {
    if (method === VerificationMethod.QR) {
      startCamera();
    } else {
      stopCamera();
    }
  }, [method]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      // Request camera access
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute("playsinline", "true"); // required for iOS
        await videoRef.current.play();
        requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setCameraError("Unable to access camera. Please ensure permissions are granted.");
      addNotification('error', 'Camera access denied');
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const tick = () => {
    // Check if camera is still active
    if (!videoRef.current || !streamRef.current) return;

    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      if (canvas && video.videoWidth > 0 && video.videoHeight > 0) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        const ctx = canvas.getContext("2d", { willReadFrequently: true });

        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);

          // Attempt to find QR code
          const code = jsQR(imageData.data, imageData.width, imageData.height, {
            inversionAttempts: "dontInvert",
          });

          if (code) {
            handleQrDetected(code.data);
            return; // Stop the loop
          }
        }
      }
    }

    // Continue loop
    animationFrameRef.current = requestAnimationFrame(tick);
  };

  const handleQrDetected = (data: string) => {
    stopCamera();
    setHashInput(data);
    setMethod(VerificationMethod.HASH); // Switch UI to hash view
    addNotification('success', 'QR Code Detected', 'Processing hash...');
    handleVerify(data); // Auto-trigger verification
  };

  const handleFileSelection = (selectedFile: File) => {
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }

    setFile(selectedFile);

    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const loadSample = (type: 'authentic' | 'forged') => {
    const content = type === 'authentic' 
      ? "Valid Certificate Content: This document is certified authentic by the issuer." 
      : "Tampered Content: This document has been modified by an unauthorized party.";

    const fileName = type === 'authentic' ? 'authentic-certificate-sample.pdf' : 'suspicious-contract-sample.pdf';

    // Create a mock file
    const blob = new Blob([content], { type: 'application/pdf' });
    const sampleFile = new File([blob], fileName, { type: 'application/pdf' });

    handleFileSelection(sampleFile);
    addNotification('info', `Loaded ${type} sample document`);
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setStatus('IDLE');
    setResult(null);
  };

  const handleVerify = async (manualHash?: string) => {
    setStatus('ANALYZING');
    setProgress(0);
    setResult(null);

    // Simulate progress
    const progressInterval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 90) return prev;
        return prev + Math.random() * 20;
      });
    }, 200);

    try {
      let docHash = manualHash || hashInput;
      let fileTextContext = "No text extracted (Hash mode)";

      if (method === VerificationMethod.FILE && file) {
        docHash = await BlockchainService.calculateHash(file);

        // In a real app, this text would be OCR'd from the file.
        // For the demo sample, we check the filename to simulate content.
        if (file.name.includes('suspicious') || file.name.includes('altered')) {
            fileTextContext = "INCONSISTENT CONTENT DETECTED. The signature block appears pixelated and the date format does not match standard ISO 8601 used by the issuer.";
        } else {
            fileTextContext = "This certifies that the holder has successfully completed all requirements for the Bachelor of Science program. Signed by the Registrar."; 
        }
      }

      const blockchainDoc = await BlockchainService.verifyDocument(docHash);

      // Force simulated failure for the "forged" sample even if hash doesn't match (logic above handles hash, this adds AI flavor)
      let aiAnalysis;

      // If it's our specific sample file that we know is "fake" (based on name for demo logic), force AI to be suspicious
      if (file && file.name.includes('suspicious')) {
         const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in registry.";
         // We pass a flag to the AI service (conceptually) or just simulate it here for the hardcoded sample button
         aiAnalysis = {
            isAuthentic: false,
            confidence: 0.92,
            reasoning: "Visual anomalies detected in signature region. Font weight inconsistencies suggest digital alteration.",
            flags: ["PIXEL_MANIPULATION", "FONT_MISMATCH"]
         };
      } else {
         const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in registry.";
         aiAnalysis = await GeminiService.analyzeDocumentAuthenticity(fileTextContext, metadataContext);
      }

      const verificationResult: VerificationResult = {
        isValid: !!blockchainDoc && blockchainDoc.status === 'ACTIVE' && aiAnalysis.isAuthentic,
        document: blockchainDoc || undefined,
        aiAnalysis
      };

      clearInterval(progressInterval);
      setProgress(100);
      await new Promise(r => setTimeout(r, 400)); // smooth finish

      setResult(verificationResult);

      // Update Global Stats
      addVerification(verificationResult.isValid);

      if (verificationResult.isValid) {
        addNotification('success', 'Document Verified', 'Authenticity confirmed by Blockchain & AI');
      } else {
        addNotification('error', 'Verification Failed', 'Document appears forged or invalid');
      }

    } catch (error) {
      clearInterval(progressInterval);
      console.error(error);
      addNotification('error', 'Verification error occurred');
    } finally {
      setStatus('COMPLETE');
      setProgress(0);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-4xl mx-auto animate-slideUp">
        <div className="text-center mb-12">
          <h1 className="text-3xl font-bold text-slate-900">Verify Document Authenticity</h1>
          <p className="mt-2 text-slate-600">Combine Blockchain immutability with AI forensics.</p>
        </div>

        <div className="bg-white rounded-2xl shadow-lg overflow-hidden mb-8 transition-all duration-300">
          <div className="flex border-b border-slate-200">
            <button 
              onClick={() => setMethod(VerificationMethod.FILE)}
              className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.FILE ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <UploadCloud className="w-5 h-5" />
              <span>Upload File</span>
            </button>
            <button 
              onClick={() => setMethod(VerificationMethod.HASH)}
              className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.HASH ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <Hash className="w-5 h-5" />
              <span>Enter Hash</span>
            </button>
            <button 
              onClick={() => setMethod(VerificationMethod.QR)}
              className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.QR ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              <QrCode className="w-5 h-5" />
              <span>Scan QR</span>
            </button>
          </div>

          <div className="p-8">
            {method === VerificationMethod.FILE && (
              <div className="space-y-4 animate-fadeIn">
                {!file ? (
                  <>
                    <div 
                      onDragOver={onDragOver}
                      onDragLeave={onDragLeave}
                      onDrop={onDrop}
                      className={`relative border-2 border-dashed rounded-xl p-10 text-center transition-all duration-300 ease-in-out cursor-pointer overflow-hidden ${
                          isDragging 
                            ? 'border-brand-500 bg-brand-50/50 scale-[1.01] shadow-lg' 
                            : 'border-slate-300 hover:bg-slate-50 hover:border-brand-300'
                      }`}
                    >
                      <input 
                        type="file" 
                        id="verify-upload" 
                        className="hidden" 
                        onChange={(e) => e.target.files && handleFileSelection(e.target.files[0])}
                        accept=".pdf,.png,.jpg,.jpeg"
                      />
                      <label htmlFor="verify-upload" className="cursor-pointer block h-full w-full relative z-10">
                        <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4 transition-transform duration-300 ${
                            isDragging ? 'bg-brand-100 scale-110' : 'bg-slate-100'
                        }`}>
                          <FileSearch className={`h-8 w-8 ${isDragging ? 'text-brand-600' : 'text-slate-400'}`} />
                        </div>
                        <span className="text-brand-600 font-bold text-lg block">
                          {isDragging ? 'Drop to verify' : 'Choose Document'}
                        </span>
                        <p className="text-slate-500 mt-2 text-sm">Upload PDF or Image (Max 10MB)</p>

                        <div className="mt-4 inline-flex items-center px-3 py-1 rounded-full bg-slate-100 text-xs font-medium text-slate-600">
                            <Shield className="w-3 h-3 mr-1.5" />
                            Secure Local Verification
                        </div>
                      </label>

                      {/* Visual background effect when dragging */}
                      {isDragging && (
                          <div className="absolute inset-0 bg-brand-50/50 backdrop-blur-[1px] flex items-center justify-center z-0">
                              <div className="absolute inset-0 bg-grid-brand-500/[0.05] [mask-image:linear-gradient(0deg,white,transparent)]"></div>
                          </div>
                      )}
                    </div>

                    {/* Auto Fill / Sample Options */}
                    <div className="pt-4 flex flex-col sm:flex-row justify-center items-center gap-3">
                      <span className="text-xs font-medium text-slate-400 uppercase tracking-wider mb-2 sm:mb-0 sm:mr-2">Quick Test:</span>
                      <button 
                        onClick={() => loadSample('authentic')}
                        className="flex items-center px-3 py-1.5 bg-green-50 text-green-700 text-xs font-semibold rounded-lg border border-green-200 hover:bg-green-100 transition-colors"
                      >
                        <CheckCircle2 className="w-3.5 h-3.5 mr-1.5" />
                        Load Authentic Sample
                      </button>
                      <button 
                        onClick={() => loadSample('forged')}
                        className="flex items-center px-3 py-1.5 bg-red-50 text-red-700 text-xs font-semibold rounded-lg border border-red-200 hover:bg-red-100 transition-colors"
                      >
                        <FileWarning className="w-3.5 h-3.5 mr-1.5" />
                        Load Forged Sample
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm animate-scaleIn group relative">
                      <div className="p-4 flex items-center space-x-4">
                          <div className="relative w-16 h-16 rounded-lg overflow-hidden bg-slate-100 border border-slate-200 flex-shrink-0">
                              {previewUrl ? (
                                  <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" />
                              ) : (
                                  <div className="w-full h-full flex items-center justify-center">
                                      <ImageIcon className="w-8 h-8 text-slate-400" />
                                  </div>
                              )}
                          </div>
                          <div className="flex-1 min-w-0">
                              <h4 className="text-sm font-semibold text-slate-900 truncate">{file.name}</h4>
                              <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB • {file.type || 'Unknown Type'}</p>
                              <div className="mt-1 flex items-center text-xs text-brand-600 font-medium">
                                  <CheckCircle2 className="w-3 h-3 mr-1" />
                                  Ready to verify
                              </div>
                          </div>
                          {(status === 'IDLE' || status === 'COMPLETE') && (
                              <button 
                                  onClick={clearFile}
                                  type="button"
                                  className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                                  title="Remove file"
                              >
                                  <X className="w-5 h-5" />
                              </button>
                          )}
                      </div>
                  </div>
                )}
              </div>
            )}

            {method === VerificationMethod.HASH && (
              <div className="animate-fadeIn">
                <label className="block text-sm font-medium text-slate-700 mb-2">Document Hash (SHA-256)</label>
                <input 
                  type="text" 
                  className="w-full px-4 py-3 border border-slate-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500 transition-shadow"
                  placeholder="e.g. e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
                  value={hashInput}
                  onChange={(e) => setHashInput(e.target.value)}
                />
              </div>
            )}

            {method === VerificationMethod.QR && (
              <div className="flex flex-col items-center justify-center animate-fadeIn">
                {cameraError ? (
                  <div className="text-red-600 bg-red-50 p-4 rounded-lg flex items-center mb-4 animate-scaleIn">
                    <ShieldAlert className="w-5 h-5 mr-2" />
                    {cameraError}
                  </div>
                ) : (
                  <div className="relative w-full max-w-sm aspect-square bg-black rounded-xl overflow-hidden shadow-inner">
                    <video 
                      ref={videoRef} 
                      className="absolute inset-0 w-full h-full object-cover" 
                      muted 
                    />
                    <canvas ref={canvasRef} className="hidden" />

                    {/* Scanner Overlay UI */}
                    <div className="absolute inset-0 border-2 border-brand-500/50 flex items-center justify-center pointer-events-none">
                      <div className="w-64 h-64 border-2 border-brand-400 rounded-lg relative animate-pulse shadow-[0_0_15px_rgba(56,189,248,0.5)]">
                        <div className="absolute top-0 left-0 w-4 h-4 border-t-4 border-l-4 border-brand-500 -mt-1 -ml-1"></div>
                        <div className="absolute top-0 right-0 w-4 h-4 border-t-4 border-r-4 border-brand-500 -mt-1 -mr-1"></div>
                        <div className="absolute bottom-0 left-0 w-4 h-4 border-b-4 border-l-4 border-brand-500 -mb-1 -ml-1"></div>
                        <div className="absolute bottom-0 right-0 w-4 h-4 border-b-4 border-r-4 border-brand-500 -mb-1 -mr-1"></div>
                      </div>
                    </div>

                    <div className="absolute bottom-4 left-0 right-0 text-center pointer-events-none">
                      <span className="bg-black/50 text-white px-3 py-1 rounded-full text-sm backdrop-blur-sm animate-slideUp">
                        Align QR Code within frame
                      </span>
                    </div>
                  </div>
                )}
              </div>
            )}

            {method !== VerificationMethod.QR && (
              <>
                {status === 'ANALYZING' ? (
                  <div className="mt-6 w-full bg-slate-50 rounded-lg p-4 border border-slate-100 animate-fadeIn">
                    <div className="flex justify-between text-sm mb-2 text-slate-600 font-medium">
                      <span className="flex items-center"><Loader2 className="animate-spin w-4 h-4 mr-2 text-brand-600"/> Verifying...</span>
                      <span>{Math.round(progress)}%</span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                      <div 
                        className="bg-brand-600 h-2.5 rounded-full transition-all duration-300 ease-out" 
                        style={{ width: `${progress}%` }}
                      ></div>
                    </div>
                    <p className="text-center text-xs text-slate-400 mt-2">Running Blockchain & AI Forensics</p>
                  </div>
                ) : (
                  <button 
                    onClick={() => handleVerify()}
                    disabled={(method === 'FILE' && !file) || (method === 'HASH' && !hashInput)}
                    className="mt-6 w-full py-3 bg-brand-600 text-white rounded-lg font-bold hover:bg-brand-700 transition-colors disabled:opacity-50 flex justify-center items-center shadow-md active:scale-[0.99] hover:shadow-lg hover:-translate-y-0.5 transform"
                  >
                    Verify Document
                  </button>
                )}
              </>
            )}
          </div>
        </div>

        {status === 'COMPLETE' && result && (
          <div className={`rounded-2xl shadow-xl overflow-hidden border-t-8 ${result.isValid ? 'border-green-500' : 'border-red-500'} bg-white animate-slideUp`}>
            <div className={`p-6 flex items-center justify-between ${result.isValid ? 'bg-green-50' : 'bg-red-50'}`}>
              <div className="flex items-center space-x-4">
                {result.isValid ? (
                  <CheckCircle className="w-10 h-10 text-green-600 animate-scaleIn" />
                ) : (
                  <ShieldAlert className="w-10 h-10 text-red-600 animate-scaleIn" />
                )}
                <div>
                  <h2 className="text-2xl font-bold text-slate-900">
                    {result.isValid ? 'Authentic Document' : 'Verification Failed'}
                  </h2>
                  <p className="text-sm text-slate-600">
                    {result.isValid ? 'Verified by Blockchain & AI' : 'Tampering or Forgery Detected'}
                  </p>
                </div>
              </div>
              <div className="text-right">
                <div className="text-sm text-slate-500">Confidence Score</div>
                <div className="text-xl font-bold text-slate-900">{(result.aiAnalysis?.confidence || 0) * 100}%</div>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-6 p-8">
              <div className="space-y-4 animate-slideIn delay-100">
                <h3 className="font-semibold text-slate-900 flex items-center">
                  <FileCheck className="w-5 h-5 mr-2 text-brand-600" />
                  Blockchain Evidence
                </h3>
                {result.document ? (
                  <div className="bg-slate-50 rounded-lg p-4 space-y-3 text-sm hover:bg-slate-100 transition-colors">
                    <div>
                      <span className="block text-slate-500 text-xs">Issuer</span>
                      <span className="font-medium text-slate-900">{result.document.issuerName}</span>
                    </div>
                    <div>
                      <span className="block text-slate-500 text-xs">Timestamp</span>
                      <span className="font-mono text-slate-700">{new Date(result.document.createdAt).toLocaleString()}</span>
                    </div>
                    <div>
                      <span className="block text-slate-500 text-xs">Hash Match</span>
                      <span className="text-green-600 font-bold">MATCHED (SHA-256)</span>
                    </div>
                  </div>
                ) : (
                  <div className="p-4 bg-red-50 text-red-700 rounded-lg text-sm">
                    Hash not found in the decentralized registry.
                  </div>
                )}
              </div>

              <div className="space-y-4 animate-slideIn delay-200">
                <h3 className="font-semibold text-slate-900 flex items-center">
                  <Brain className="w-5 h-5 mr-2 text-purple-600" />
                  AI Forgery Detection
                </h3>
                <div className="bg-slate-50 rounded-lg p-4 text-sm hover:bg-slate-100 transition-colors">
                  <p className="text-slate-700 mb-3 italic">"{result.aiAnalysis?.reasoning}"</p>

                  {result.aiAnalysis?.flags && result.aiAnalysis.flags.length > 0 && (
                    <div className="space-y-1">
                      {result.aiAnalysis.flags.map((flag, i) => (
                        <div key={i} className="inline-flex items-center px-2 py-1 rounded bg-red-100 text-red-700 text-xs mr-2">
                          {flag}
                        </div>
                      ))}
                    </div>
                  )}

                  {result.aiAnalysis?.isAuthentic && (
                    <div className="mt-2 text-green-600 font-medium text-xs flex items-center">
                      <CheckCircle className="w-3 h-3 mr-1" />
                      No structural manipulation detected
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Upload, FileText, Wallet, Loader2, CheckCircle2, X, Copy, LogOut, Download, Shield, UploadCloud, Sparkles } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { DocumentMetadata } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';

export const CreateDocument = () => {
  const { addNotification } = useNotification();
  const { addDocument } = useGlobalStore();
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [walletAddress, setWalletAddress] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [registeredDoc, setRegisteredDoc] = useState<DocumentMetadata | null>(null);

  const [formData, setFormData] = useState({
    title: '',
    issuerName: '',
    type: 'Certificate',
    description: ''
  });

  // Attempt to auto-connect if wallet was previously connected
  useEffect(() => {
    const savedAddress = localStorage.getItem('trustchain_wallet');
    if (savedAddress) {
      setWalletAddress(savedAddress);
    }
  }, []);

  const connectWallet = async () => {
    try {
      const address = await BlockchainService.connectWallet();
      setWalletAddress(address);
      localStorage.setItem('trustchain_wallet', address);
      addNotification('success', 'Wallet Connected Successfully', 'Connected to Sepolia Testnet');
    } catch (err) {
      addNotification('error', 'Failed to connect wallet');
    }
  };

  const handleFileSelection = (selectedFile: File) => {
    // Basic validation
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }

    setFile(selectedFile);

    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const handleAutoFill = () => {
    const titles = ['Supply Chain Manifest', 'University Diploma', 'Real Estate Deed', 'Employment Agreement'];
    const issuers = ['Logistics Global Inc.', 'Stanford University', 'City Land Registry', 'TechInnovate Corp'];
    const types = ['Certificate', 'Contract', 'Identity Proof', 'Transcripts'];

    const rand = Math.floor(Math.random() * titles.length);

    setFormData({
      title: titles[rand] + ` #${Math.floor(Math.random() * 1000)}`,
      issuerName: issuers[rand],
      type: types[rand],
      description: `Auto-generated sample document for demonstration purposes. Verified on ${new Date().toLocaleDateString()}.`
    });

    // Create a dummy file
    const content = "This is a sample document content generated for auto-fill testing. It simulates a valid digital asset.";
    const blob = new Blob([content], { type: 'application/pdf' });
    const dummyFile = new File([blob], `sample_${titles[rand].toLowerCase().replace(/\s/g, '_')}.pdf`, { type: 'application/pdf' });
    handleFileSelection(dummyFile);

    addNotification('info', 'Form Auto-Filled', 'Sample data and file loaded.');
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFileSelection(e.target.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!walletAddress || !file) return;

    setIsProcessing(true);
    setUploadProgress(0);

    // Simulate progress
    const progressInterval = setInterval(() => {
      setUploadProgress(prev => {
        if (prev >= 90) return prev;
        return prev + Math.random() * 15;
      });
    }, 400);

    try {
      // 1. Calculate Hash
      const hash = await BlockchainService.calculateHash(file);
      addNotification('info', 'File Hashed locally (SHA-256)', 'Security check passed');

      // 2. Mock IPFS Upload (In production: await IpfsService.upload(file))
      const ipfsCid = "QmMockCidForDemoPurposeOnly12345"; 

      // 3. Register on Blockchain
      const newDoc = await BlockchainService.registerDocument({
        title: formData.title,
        issuerName: formData.issuerName,
        type: formData.type,
        description: formData.description,
        hash,
        ipfsCid
      });

      // Update Global Store for Real-time Dashboard
      addDocument(newDoc);

      clearInterval(progressInterval);
      setUploadProgress(100);

      // Artificial delay to show 100% completion
      await new Promise(resolve => setTimeout(resolve, 600));

      setRegisteredDoc(newDoc);
      setStep(3);
      addNotification('success', 'Document Registered!', 'Transaction confirmed on blockchain');
    } catch (err) {
      clearInterval(progressInterval);
      console.error(err);
      addNotification('error', 'Registration failed', 'Please try again');
    } finally {
      setIsProcessing(false);
      setUploadProgress(0);
    }
  };

  const downloadReceipt = () => {
    if (!registeredDoc) return;

    const receiptData = {
      ...registeredDoc,
      transactionId: '0x7f...3a9c',
      network: 'Sepolia Testnet',
      timestamp: new Date().toISOString(),
      platform: 'TrustChain AI - Secure Document Verification',
      verificationLink: window.location.origin + '/#/verify' 
    };

    const blob = new Blob([JSON.stringify(receiptData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `trustchain-receipt-${registeredDoc.id}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    addNotification('success', 'Receipt downloaded successfully');
  };

  const copyAddress = () => {
    if (walletAddress) {
        navigator.clipboard.writeText(walletAddress);
        addNotification('info', 'Address copied to clipboard');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-3xl mx-auto animate-slideUp">
        <div className="mb-10 text-center">
          <h1 className="text-3xl font-bold text-slate-900">Register New Document</h1>
          <p className="mt-2 text-slate-600">Securely anchor your document to the blockchain.</p>
        </div>

        {/* Progress Steps */}
        <div className="mb-8 flex justify-center items-center space-x-4">
          {[1, 2, 3].map((s) => (
            <div key={s} className={`flex items-center ${s < 3 ? 'w-full' : ''}`}>
               <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm transition-all duration-300 ${
                 step >= s ? 'bg-brand-600 text-white scale-110' : 'bg-slate-200 text-slate-500'
               }`}>
                 {s}
               </div>
               {s < 3 && <div className={`h-1 flex-1 mx-2 transition-all duration-500 ${step > s ? 'bg-brand-600' : 'bg-slate-200'}`} />}
            </div>
          ))}
        </div>

        <div className="bg-white shadow-xl rounded-2xl overflow-hidden transition-all duration-300">
          {/* Step 1: Wallet Connection */}
          {step === 1 && (
            <div className="p-10 animate-fadeIn">
              <div className="text-center mb-8">
                <div className="mx-auto w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-6">
