                    )}
                  </div>

                  {isProcessing ? (
                    <div className="w-full bg-slate-50 rounded-lg p-4 border border-slate-100 text-center">
                      <Loader2 className="w-8 h-8 text-brand-600 animate-spin mx-auto mb-3" />
