// Simulating a delay for realistic async effects
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

interface NetworkConfig {
  name: string;
  blockTimeMs: number; // Average block time in milliseconds
  currency: string;
  chainId: number;
}

export const NETWORK_CONFIGS: Record<NetworkType, NetworkConfig> = {
  SEPOLIA: { name: 'Sepolia Testnet', blockTimeMs: 12000, currency: 'SepoliaETH', chainId: 11155111 },
  MAINNET: { name: 'Ethereum Mainnet', blockTimeMs: 12000, currency: 'ETH', chainId: 1 },
  POLYGON: { name: 'Polygon PoS', blockTimeMs: 2200, currency: 'MATIC', chainId: 137 },
  BNB: { name: 'BNB Smart Chain', blockTimeMs: 3000, currency: 'BNB', chainId: 56 },
  AVALANCHE: { name: 'Avalanche C-Chain', blockTimeMs: 800, currency: 'AVAX', chainId: 43114 },
