// Mock storage to act as the "Blockchain" for this demo
let MOCK_BLOCKCHAIN_REGISTRY: DocumentMetadata[] = [
  {
    id: 'doc_12345',
    title: 'University Degree - John Doe',
    type: 'Certificate',
    issuerName: 'Massachusetts Institute of Technology',
    description: 'Bachelor of Science in Computer Science',
    createdAt: new Date().toISOString(),
    hash: 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', // Empty hash for demo
    ipfsCid: 'QmXoypizjW3WknFiJnKLwHCnL72vedxjQkDDP1mXWo6uco',
    status: DocumentStatus.ACTIVE,
    aiForgeryScore: 0.02,
    network: 'MAINNET'
  }
];

export const BlockchainService = {
  getNetworkConfig: (network: NetworkType) => NETWORK_CONFIGS[network],

  // Simulate wallet connection
  connectWallet: async (network: NetworkType = 'SEPOLIA'): Promise<string> => {
    await delay(600);
    // In a real app, this uses window.ethereum.request({ method: 'eth_requestAccounts' })
    // and checks if window.ethereum.chainId matches NETWORK_CONFIGS[network].chainId
    return '0x71C7656EC7ab88b098defB751B7401B5f6d8976F';
  },

  // Simulate calculating SHA-256 hash
  calculateHash: async (file: File): Promise<string> => {
    const buffer = await file.arrayBuffer();
    const hashBuffer = await crypto.subtle.digest('SHA-256', buffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    return hashHex;
  },

  // Simulate registering a document on the smart contract with realistic timing
  registerDocument: async (
    metadata: Omit<DocumentMetadata, 'id' | 'createdAt' | 'status'>,
    network: NetworkType
  ): Promise<DocumentMetadata> => {
    const config = NETWORK_CONFIGS[network];

    // Simulate real-world block confirmation delay
    await delay(config.blockTimeMs); 

    const newDoc: DocumentMetadata = {
      ...metadata,
      id: `doc_${Date.now()}`,
      createdAt: new Date().toISOString(),
      status: DocumentStatus.ACTIVE,
      aiForgeryScore: 0,
      network: network
    };

    MOCK_BLOCKCHAIN_REGISTRY.push(newDoc);
    return newDoc;
  },

  // Simulate fetching from Smart Contract
  verifyDocument: async (hash: string, network: NetworkType): Promise<DocumentMetadata | null> => {
    // Reading from blockchain is usually fast (node lookup), but varies slightly by chain
    const readDelay = network === 'HYPERLEDGER' || network === 'AVALANCHE' ? 100 : 500;
    await delay(readDelay);

    // In a real multi-chain app, we would query the specific chain RPC.
    // Here we check if the doc exists in our mock registry and matches the expected network 
    // (optional: allows cross-chain verification if we relax the check).
    return MOCK_BLOCKCHAIN_REGISTRY.find(d => d.hash === hash) || null;
  }
};

