import React, { useState, useRef, useEffect } from 'react';
import { FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash, QrCode, Loader2, X, Image as ImageIcon, Shield, CheckCircle2, Sparkles, FileWarning, Fingerprint, ScanEye, Zap } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';
import jsQR from 'jsqr';

export const VerifyDocument = () => {
  const { addNotification } = useNotification();
  const { addVerification, currentNetwork } = useGlobalStore();
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hashInput, setHashInput] = useState('');
  const [status, setStatus] = useState<'IDLE' | 'ANALYZING' | 'COMPLETE'>('IDLE');
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);

  // QR Scanning Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  // Cleanup camera on unmount or method change
  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  useEffect(() => {
    if (method === VerificationMethod.QR) {
      startCamera();
    } else {
      stopCamera();
    }
  }, [method]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute("playsinline", "true"); 
        await videoRef.current.play();
        requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setCameraError("Unable to access camera. Please ensure permissions are granted.");
      addNotification('error', 'Camera access denied');
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const tick = () => {
    if (!videoRef.current || !streamRef.current) return;
    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (canvas && video.videoWidth > 0 && video.videoHeight > 0) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        const ctx = canvas.getContext("2d", { willReadFrequently: true });
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: "dontInvert" });
          if (code) {
            handleQrDetected(code.data);
            return; 
          }
        }
      }
    }
    animationFrameRef.current = requestAnimationFrame(tick);
  };

  const handleQrDetected = (data: string) => {
    stopCamera();
    setHashInput(data);
    setMethod(VerificationMethod.HASH);
    addNotification('success', 'QR Code Detected', 'Processing hash...');
    handleVerify(data);
  };

  const handleFileSelection = (selectedFile: File) => {
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }
    setFile(selectedFile);
    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const loadSample = (type: 'authentic' | 'forged') => {
    const content = type === 'authentic' 
      ? "Valid Certificate Content: This document is certified authentic by the issuer." 
      : "Tampered Content: This document has been modified by an unauthorized party.";
    const fileName = type === 'authentic' ? 'authentic-certificate-sample.pdf' : 'suspicious-contract-sample.pdf';
    const blob = new Blob([content], { type: 'application/pdf' });
    const sampleFile = new File([blob], fileName, { type: 'application/pdf' });
    handleFileSelection(sampleFile);
    addNotification('info', `Loaded ${type} sample document`);
  };

  const onDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const onDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setStatus('IDLE');
    setResult(null);
  };

  const handleVerify = async (manualHash?: string) => {
    setStatus('ANALYZING');
    setProgress(0);
    setResult(null);

    const progressInterval = setInterval(() => {
      setProgress(prev => {
        if (prev >= 90) return prev;
        return prev + Math.random() * 20;
      });
    }, 200);

    try {
      let docHash = manualHash || hashInput;
      let fileTextContext = "No text extracted (Hash mode)";

      if (method === VerificationMethod.FILE && file) {
        docHash = await BlockchainService.calculateHash(file);
        if (file.name.includes('suspicious') || file.name.includes('altered')) {
            fileTextContext = "INCONSISTENT CONTENT DETECTED. The signature block appears pixelated and the date format does not match standard ISO 8601 used by the issuer.";
        } else {
            fileTextContext = "This certifies that the holder has successfully completed all requirements for the Bachelor of Science program. Signed by the Registrar."; 
        }
      }

      const blockchainDoc = await BlockchainService.verifyDocument(docHash, currentNetwork);

      let aiAnalysis;
      if (file && file.name.includes('suspicious')) {
         aiAnalysis = {
            isAuthentic: false,
            confidence: 0.92,
            reasoning: "Visual anomalies detected in signature region. Font weight inconsistencies suggest digital alteration.",
            flags: ["PIXEL_MANIPULATION", "FONT_MISMATCH"],
            advancedMetrics: {
                deepfakeProbability: 0.89,
                metadataConsistency: 0.12,
                entropyScore: 0.45
            }
         };
      } else {
         const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in registry.";
         aiAnalysis = await GeminiService.analyzeDocumentAuthenticity(fileTextContext, metadataContext);
         // Simulate advanced metrics for authentic docs
         aiAnalysis.advancedMetrics = {
             deepfakeProbability: 0.02,
             metadataConsistency: 0.99,
             entropyScore: 0.15
         };
      }

      const verificationResult: VerificationResult = {
        isValid: !!blockchainDoc && blockchainDoc.status === 'ACTIVE' && aiAnalysis.isAuthentic,
        document: blockchainDoc || undefined,
        aiAnalysis,
        blockchainProof: blockchainDoc ? {
            txHash: '0x' + Array(64).fill(0).map(() => Math.floor(Math.random() * 16).toString(16)).join(''),
            timestamp: blockchainDoc.createdAt,
            issuerAddress: '0x71...5f',
            network: blockchainDoc.network || currentNetwork
        } : undefined
      };

      clearInterval(progressInterval);
      setProgress(100);
      await new Promise(r => setTimeout(r, 400)); 

      setResult(verificationResult);
      addVerification(verificationResult.isValid);

      if (verificationResult.isValid) {
        addNotification('success', 'Document Verified', `Authenticity confirmed on ${currentNetwork}`);
      } else {
        addNotification('error', 'Verification Failed', 'Document appears forged or invalid');
      }

    } catch (error) {
      clearInterval(progressInterval);
      console.error(error);
      addNotification('error', 'Verification error occurred');
    } finally {
      setStatus('COMPLETE');
      setProgress(0);
    }
  };

  const renderAdvancedMetric = (label: string, value: number, inverse = false) => {
    // Inverse: High value is bad (e.g., Deepfake Prob)
    // Normal: High value is good (e.g., Consistency)
    const isGood = inverse ? value < 0.3 : value > 0.7;
    const colorClass = isGood ? 'bg-green-500' : value > (inverse ? 0.6 : 0.4) ? 'bg-red-500' : 'bg-yellow-500';

    return (
        <div className="mb-3">
            <div className="flex justify-between text-xs mb-1">
                <span className="text-slate-500">{label}</span>
                <span className="font-mono font-medium text-slate-700">{(value * 100).toFixed(1)}%</span>
            </div>
            <div className="h-1.5 w-full bg-slate-200 rounded-full overflow-hidden">
                <div 
                    className={`h-full ${colorClass} transition-all duration-500`} 
                    style={{ width: `${value * 100}%` }}
                ></div>
            </div>
        </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-4xl mx-auto animate-slideUp">
        <div className="text-center mb-12">
          <h1 className="text-3xl font-bold text-slate-900">Verify Document Authenticity</h1>
          <p className="mt-2 text-slate-600">Combine Blockchain immutability with AI forensics.</p>
        </div>

        {/* Method Selector & Upload UI - Same as before */}
        <div className="bg-white rounded-2xl shadow-lg overflow-hidden mb-8 transition-all duration-300">
          <div className="flex border-b border-slate-200">
            <button onClick={() => setMethod(VerificationMethod.FILE)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.FILE ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <UploadCloud className="w-5 h-5" /> <span>Upload File</span>
            </button>
            <button onClick={() => setMethod(VerificationMethod.HASH)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.HASH ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <Hash className="w-5 h-5" /> <span>Enter Hash</span>
            </button>
            <button onClick={() => setMethod(VerificationMethod.QR)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.QR ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <QrCode className="w-5 h-5" /> <span>Scan QR</span>
            </button>
          </div>

          <div className="p-8">
            {method === VerificationMethod.FILE && (
              <div className="space-y-4 animate-fadeIn">
                {!file ? (
                  <>
                    <div 
                      onDragOver={onDragOver}
                      onDragLeave={onDragLeave}
                      onDrop={onDrop}
                      className={`relative border-2 border-dashed rounded-xl p-10 text-center transition-all duration-300 ease-in-out cursor-pointer overflow-hidden ${
                          isDragging 
                            ? 'border-brand-500 bg-brand-50/50 scale-[1.01] shadow-lg' 
                            : 'border-slate-300 hover:bg-slate-50 hover:border-brand-300'
                      }`}
                    >
                      <input type="file" id="verify-upload" className="hidden" onChange={(e) => e.target.files && handleFileSelection(e.target.files[0])} accept=".pdf,.png,.jpg,.jpeg" />
                      <label htmlFor="verify-upload" className="cursor-pointer block h-full w-full relative z-10">
                        <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4 transition-transform duration-300 ${isDragging ? 'bg-brand-100 scale-110' : 'bg-slate-100'}`}>
                          <FileSearch className={`h-8 w-8 ${isDragging ? 'text-brand-600' : 'text-slate-400'}`} />
                        </div>
                        <span className="text-brand-600 font-bold text-lg block">{isDragging ? 'Drop to verify' : 'Choose Document'}</span>
                        <p className="text-slate-500 mt-2 text-sm">Upload PDF or Image (Max 10MB)</p>
                      </label>
                    </div>

                    <div className="pt-4 flex flex-col sm:flex-row justify-center items-center gap-3">
                      <span className="text-xs font-medium text-slate-400 uppercase tracking-wider mb-2 sm:mb-0 sm:mr-2">Quick Test:</span>
                      <button onClick={() => loadSample('authentic')} className="flex items-center px-3 py-1.5 bg-green-50 text-green-700 text-xs font-semibold rounded-lg border border-green-200 hover:bg-green-100 transition-colors">
                        <CheckCircle2 className="w-3.5 h-3.5 mr-1.5" /> Load Authentic Sample
                      </button>
                      <button onClick={() => loadSample('forged')} className="flex items-center px-3 py-1.5 bg-red-50 text-red-700 text-xs font-semibold rounded-lg border border-red-200 hover:bg-red-100 transition-colors">
                        <FileWarning className="w-3.5 h-3.5 mr-1.5" /> Load Forged Sample
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm animate-scaleIn">
                      <div className="p-4 flex items-center space-x-4">
                          <div className="relative w-16 h-16 rounded-lg overflow-hidden bg-slate-100 border border-slate-200 flex-shrink-0">
                              {previewUrl ? <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" /> : <ImageIcon className="w-8 h-8 text-slate-400" />}
                          </div>
                          <div className="flex-1 min-w-0">
                              <h4 className="text-sm font-semibold text-slate-900 truncate">{file.name}</h4>
                              <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB • {file.type || 'Unknown Type'}</p>
                              <div className="mt-1 flex items-center text-xs text-brand-600 font-medium"><CheckCircle2 className="w-3 h-3 mr-1" /> Ready to verify</div>
                          </div>
                          {(status === 'IDLE' || status === 'COMPLETE') && (
                              <button onClick={clearFile} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"><X className="w-5 h-5" /></button>
                          )}
                      </div>
                  </div>
                )}
              </div>
            )}

            {method === VerificationMethod.HASH && (
              <div className="animate-fadeIn">
                <label className="block text-sm font-medium text-slate-700 mb-2">Document Hash (SHA-256)</label>
                <input type="text" className="w-full px-4 py-3 border border-slate-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-brand-500" placeholder="e.g. e3b0c442..." value={hashInput} onChange={(e) => setHashInput(e.target.value)} />
              </div>
            )}

            {method === VerificationMethod.QR && (
              <div className="flex flex-col items-center justify-center animate-fadeIn">
                {cameraError ? (
                  <div className="text-red-600 bg-red-50 p-4 rounded-lg flex items-center mb-4"><ShieldAlert className="w-5 h-5 mr-2" />{cameraError}</div>
                ) : (
                  <div className="relative w-full max-w-sm aspect-square bg-black rounded-xl overflow-hidden shadow-inner">
                    <video ref={videoRef} className="absolute inset-0 w-full h-full object-cover" muted />
                    <canvas ref={canvasRef} className="hidden" />
                    <div className="absolute inset-0 border-2 border-brand-500/50 flex items-center justify-center pointer-events-none">
                      <div className="w-64 h-64 border-2 border-brand-400 rounded-lg relative animate-pulse shadow-[0_0_15px_rgba(56,189,248,0.5)]"></div>
                    </div>
                  </div>
                )}
              </div>
            )}

            {method !== VerificationMethod.QR && (
              <>
                {status === 'ANALYZING' ? (
                  <div className="mt-6 w-full bg-slate-50 rounded-lg p-4 border border-slate-100 animate-fadeIn">
                    <div className="flex justify-between text-sm mb-2 text-slate-600 font-medium">
                      <span className="flex items-center"><Loader2 className="animate-spin w-4 h-4 mr-2 text-brand-600"/> Verifying...</span>
                      <span>{Math.round(progress)}%</span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                      <div className="bg-brand-600 h-2.5 rounded-full transition-all duration-300 ease-out" style={{ width: `${progress}%` }}></div>
                    </div>
                    <p className="text-center text-xs text-slate-400 mt-2">Running Blockchain & AI Forensics on {currentNetwork}</p>
                  </div>
                ) : (
                  <button 
                    onClick={() => handleVerify()}
                    disabled={(method === 'FILE' && !file) || (method === 'HASH' && !hashInput)}
                    className="mt-6 w-full py-3 bg-brand-600 text-white rounded-lg font-bold hover:bg-brand-700 transition-colors disabled:opacity-50 flex justify-center items-center shadow-md active:scale-[0.99] hover:shadow-lg hover:-translate-y-0.5 transform"
                  >
                    Verify Document
                  </button>
                )}
              </>
            )}
          </div>
        </div>

        {status === 'COMPLETE' && result && (
          <div className={`rounded-2xl shadow-xl overflow-hidden border-t-8 ${result.isValid ? 'border-green-500' : 'border-red-500'} bg-white animate-slideUp`}>
            {/* Header Result */}
            <div className={`p-6 flex items-center justify-between ${result.isValid ? 'bg-green-50' : 'bg-red-50'}`}>
              <div className="flex items-center space-x-4">
                {result.isValid ? <CheckCircle className="w-10 h-10 text-green-600 animate-scaleIn" /> : <ShieldAlert className="w-10 h-10 text-red-600 animate-scaleIn" />}
                <div>
                  <h2 className="text-2xl font-bold text-slate-900">{result.isValid ? 'Authentic Document' : 'Verification Failed'}</h2>
                  <p className="text-sm text-slate-600">{result.isValid ? 'Verified by Blockchain & AI' : 'Tampering or Forgery Detected'}</p>
                </div>
              </div>
              <div className="text-right">
                <div className="text-sm text-slate-500">Confidence Score</div>
                <div className="text-xl font-bold text-slate-900">{(result.aiAnalysis?.confidence || 0) * 100}%</div>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-6 p-8">
              {/* Blockchain Evidence */}
              <div className="space-y-4 animate-slideIn delay-100">
                <h3 className="font-semibold text-slate-900 flex items-center">
                  <FileCheck className="w-5 h-5 mr-2 text-brand-600" /> Blockchain Evidence
                </h3>
                {result.document ? (
                  <div className="bg-slate-50 rounded-lg p-4 space-y-3 text-sm hover:bg-slate-100 transition-colors border border-slate-100">
                    <div><span className="block text-slate-500 text-xs">Issuer</span><span className="font-medium text-slate-900">{result.document.issuerName}</span></div>
                    <div><span className="block text-slate-500 text-xs">Timestamp</span><span className="font-mono text-slate-700">{new Date(result.document.createdAt).toLocaleString()}</span></div>
                    <div><span className="block text-slate-500 text-xs">Hash Match</span><span className="text-green-600 font-bold">MATCHED (SHA-256)</span></div>
                    <div>
                        <span className="block text-slate-500 text-xs">Network</span>
                        <div className="flex items-center mt-1">
                            <span className="w-2 h-2 rounded-full bg-blue-500 mr-2"></span>
                            <span className="font-medium text-slate-900">{result.blockchainProof?.network || currentNetwork}</span>
                        </div>
                    </div>
                  </div>
                ) : (
                  <div className="p-4 bg-red-50 text-red-700 rounded-lg text-sm">Hash not found in the decentralized registry.</div>
                )}
              </div>

              {/* AI & Advanced Forensics */}
              <div className="space-y-4 animate-slideIn delay-200">
                <h3 className="font-semibold text-slate-900 flex items-center">
                  <Brain className="w-5 h-5 mr-2 text-purple-600" /> AI Forgery Detection
                </h3>
                <div className="bg-slate-50 rounded-lg p-4 text-sm hover:bg-slate-100 transition-colors border border-slate-100">
                  <p className="text-slate-700 mb-3 italic">"{result.aiAnalysis?.reasoning}"</p>

                  {result.aiAnalysis?.flags && result.aiAnalysis.flags.length > 0 && (
                    <div className="space-y-1 mb-3">
                      {result.aiAnalysis.flags.map((flag, i) => (
                        <div key={i} className="inline-flex items-center px-2 py-1 rounded bg-red-100 text-red-700 text-xs mr-2">{flag}</div>
                      ))}
                    </div>
                  )}

                  {/* Advanced Metrics Visualization */}
                  {result.aiAnalysis?.advancedMetrics && (
                      <div className="mt-4 pt-4 border-t border-slate-200">
                          <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 flex items-center">
                              <Zap className="w-3 h-3 mr-1" /> Advanced Forensics
                          </h4>
                          {renderAdvancedMetric("Deepfake Probability", result.aiAnalysis.advancedMetrics.deepfakeProbability, true)}
                          {renderAdvancedMetric("Metadata Consistency", result.aiAnalysis.advancedMetrics.metadataConsistency)}
                          {renderAdvancedMetric("Entropy/Noise Analysis", result.aiAnalysis.advancedMetrics.entropyScore, true)}
                      </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export enum DocumentStatus {
  ACTIVE = 'ACTIVE',
  REVOKED = 'REVOKED',
  SUSPICIOUS = 'SUSPICIOUS',
  PENDING = 'PENDING'
}

export type UserRole = 'GUEST' | 'ISSUER' | 'ADMIN' | 'AUDITOR';

export type NetworkType = 'SEPOLIA' | 'MAINNET' | 'POLYGON' | 'BNB' | 'AVALANCHE' | 'HYPERLEDGER';

export interface DocumentMetadata {
  id: string;
  title: string;
  type: string;
  issuerName: string;
  description: string;
  expiryDate?: string;
  createdAt: string;
  hash: string;
  ipfsCid: string;
  status: DocumentStatus;
  aiForgeryScore?: number;
  network?: NetworkType;
}

export interface ForensicMetric {
  score: number; // 0 to 1
  status: 'SAFE' | 'WARNING' | 'CRITICAL';
  details: string;
  detectedIssues?: string[];
}

export interface VerificationResult {
  isValid: boolean;
  document?: DocumentMetadata;
  blockchainProof?: {
    txHash: string;
    timestamp: string;
    issuerAddress: string;
    network: NetworkType;
  };
  aiAnalysis?: {
    isAuthentic: boolean;
    confidence: number;
    reasoning: string;
    flags: string[];
    forensics: {
      visual: ForensicMetric;
      metadata: ForensicMetric;
      content: ForensicMetric;
      overallScore: number;
    };
  };
}

export enum VerificationMethod {
  FILE = 'FILE',
  HASH = 'HASH',
  QR = 'QR'
}

import { GoogleGenAI } from "@google/genai";
import { VerificationResult, ForensicMetric } from "../types";

// Simulating external Computer Vision API latency
const visionDelay = () => new Promise(resolve => setTimeout(resolve, 1500));

export const GeminiService = {
  analyzeDocumentAuthenticity: async (
    fileTextContext: string,
    metadataContext: string,
    file?: File
  ): Promise<VerificationResult['aiAnalysis']> => {

    // 1. Simulate Computer Vision Analysis (OpenCV/CNN)
    // In a real app, we would send the file to a Python backend with OpenCV
    await visionDelay();

    const isSuspiciousFile = file?.name.toLowerCase().includes('suspicious') || 
                             file?.name.toLowerCase().includes('altered') ||
                             file?.name.toLowerCase().includes('fake');

    // Mock Vision Metrics
    const visualMetric: ForensicMetric = isSuspiciousFile 
      ? {
          score: 0.45,
          status: 'CRITICAL',
          details: 'Pixel inconsistency detected in signature region (Error Level Analysis).',
          detectedIssues: ['High-frequency noise variance', 'Aliasing artifacts on font edges', 'Signature background mismatch']
        }
      : {
          score: 0.98,
          status: 'SAFE',
          details: 'No visual manipulation artifacts detected via Error Level Analysis (ELA).',
          detectedIssues: []
        };

    // Mock Metadata Metrics
    const fileLastModified = file ? new Date(file.lastModified) : new Date();
    const isRecentEdit = (new Date().getTime() - fileLastModified.getTime()) < 86400000; // Modified in last 24h

    const metadataMetric: ForensicMetric = (isSuspiciousFile || (isRecentEdit && file))
      ? {
          score: 0.60,
          status: 'WARNING',
          details: 'File metadata indicates modification after initial creation timestamp.',
          detectedIssues: ['Creation/Modification date mismatch', 'Editing software footprint found (Adobe Photoshop)']
        }
      : {
          score: 0.99,
          status: 'SAFE',
          details: 'Metadata timestamps line up with blockchain anchor time.',
          detectedIssues: []
        };

    // 2. LLM Content Analysis (Gemini)
    let contentMetric: ForensicMetric;
    let reasoning = "";
    let isAuthentic = true;
    let flags: string[] = [];

    if (!process.env.API_KEY) {
      console.warn("No API Key found. Returning mock AI result.");
      contentMetric = isSuspiciousFile 
        ? { score: 0.70, status: 'WARNING', details: 'Terminology inconsistent with standard issuer templates.', detectedIssues: ['Non-standard date format', 'Typographical anomalies'] }
        : { score: 0.95, status: 'SAFE', details: 'Content structure matches verified issuer templates.', detectedIssues: [] };

      reasoning = isSuspiciousFile 
        ? "Multi-model analysis detected critical visual anomalies and metadata inconsistencies."
        : "All forensic layers (Visual, Metadata, Content) confirm document integrity.";

      isAuthentic = !isSuspiciousFile;
      flags = isSuspiciousFile ? ['VISUAL_TAMPERING', 'METADATA_MISMATCH'] : [];

    } else {
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const model = 'gemini-3-flash-preview';

        const prompt = `
          Act as a Forensic Document Examiner. Analyze this document data.

          Blockchain Metadata: ${metadataContext}
          Extracted Text: ${fileTextContext}

          Task: Check for logical inconsistencies, date mismatches, or terminology errors that suggest forgery.

          Return JSON:
          {
            "contentScore": number (0-1),
            "reasoning": string,
            "issues": string[]
          }
        `;

        const result = await ai.models.generateContent({
          model,
          contents: prompt,
          config: { responseMimeType: 'application/json' }
        });

        const responseText = result.text;
        if (!responseText) throw new Error("Empty AI response");
        const json = JSON.parse(responseText);

        contentMetric = {
          score: json.contentScore,
          status: json.contentScore > 0.8 ? 'SAFE' : json.contentScore > 0.5 ? 'WARNING' : 'CRITICAL',
          details: json.reasoning,
          detectedIssues: json.issues
        };

        // Combine logic for final result
        // Ensemble Score: Weighted average (Vision 40%, Metadata 30%, Content 30%)
        const ensembleScore = (visualMetric.score * 0.4) + (metadataMetric.score * 0.3) + (contentMetric.score * 0.3);

        isAuthentic = ensembleScore > 0.75;
        reasoning = `Ensemble Confidence: ${(ensembleScore * 100).toFixed(1)}%. ${visualMetric.details} ${contentMetric.details}`;
        flags = [...(visualMetric.detectedIssues || []), ...(metadataMetric.detectedIssues || []), ...(contentMetric.detectedIssues || [])];

      } catch (error) {
        console.error("AI Analysis failed", error);
        contentMetric = { score: 0.5, status: 'WARNING', details: 'AI Analysis unavailable', detectedIssues: ['AI_SERVICE_OFFLINE'] };
        reasoning = "Partial analysis due to AI service unavailability.";
        isAuthentic = !isSuspiciousFile;
      }
    }

    // Final Ensemble Calculation (if not calculated in try block)
    const overallScore = (visualMetric.score * 0.4) + (metadataMetric.score * 0.3) + (contentMetric.score * 0.3);

    return {
      isAuthentic,
      confidence: overallScore,
      reasoning,
      flags,
      forensics: {
        visual: visualMetric,
        metadata: metadataMetric,
        content: contentMetric,
        overallScore: overallScore
      }
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash, QrCode, Loader2, X, Image as ImageIcon, Shield, CheckCircle2, Sparkles, FileWarning, Fingerprint, ScanEye, Zap, Activity, Microscope, Layers, FileJson } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';
import { useNotification } from '../components/NotificationSystem';
