// ==========================================
// 2. Abstraction Layer (Strategy Pattern)
// ==========================================

interface ChainAdapter {
  connectWallet(): Promise<string>;
  submitTransaction(doc: DocumentMetadata): Promise<DocumentMetadata>;
  fetchTransaction(hash: string): Promise<DocumentMetadata | null>;
}

// EVM Adapter (Ethereum, Polygon, BNB, Avalanche)
class EVMAdapter implements ChainAdapter {
  constructor(private config: NetworkConfig) {}

  async connectWallet(): Promise<string> {
    await delay(600);
    // Simulate Metamask interaction: window.ethereum.request({ method: 'eth_requestAccounts' })
    return `0x${this.config.currency}7656EC7ab88b098defB751B7401B5f6d8976F`;
  }

  async submitTransaction(doc: DocumentMetadata): Promise<DocumentMetadata> {
    // Simulate Gas estimation & Mempool wait
    console.log(`[EVM] Routing tx to Chain ID ${this.config.chainId} via ${this.config.rpcEndpoint}`);
    await delay(this.config.blockTimeMs); 

    const finalDoc = { ...doc, status: DocumentStatus.ACTIVE };
    GLOBAL_LEDGER.push(finalDoc);
    return finalDoc;
  }

  async fetchTransaction(hash: string): Promise<DocumentMetadata | null> {
    await delay(300); // Fast read from RPC node
    return GLOBAL_LEDGER.find(d => d.hash === hash) || null;
  }
}

// Fabric Adapter (Private Permissioned Chain)
class FabricAdapter implements ChainAdapter {
  constructor(private config: NetworkConfig) {}

  async connectWallet(): Promise<string> {
    await delay(200);
    return "Org1MSP::User1"; // Fabric Identity
  }

  async submitTransaction(doc: DocumentMetadata): Promise<DocumentMetadata> {
    console.log(`[Fabric] Invoking Chaincode on Channel 'mychannel'`);
    await delay(100); // Instant finality
    const finalDoc = { ...doc, status: DocumentStatus.ACTIVE };
    GLOBAL_LEDGER.push(finalDoc);
    return finalDoc;
  }

  async fetchTransaction(hash: string): Promise<DocumentMetadata | null> {
    await delay(50);
    return GLOBAL_LEDGER.find(d => d.hash === hash) || null;
  }
}

// ==========================================
// 3. Service Facade (Router)
// ==========================================

export const BlockchainService = {

  getNetworkConfig: (network: NetworkType) => NETWORK_CONFIGS[network],

  // Factory method to get the correct adapter based on protocol type
  getAdapter: (network: NetworkType): ChainAdapter => {
    const config = NETWORK_CONFIGS[network];
    if (config.type === 'FABRIC') {
      return new FabricAdapter(config);
    }
    return new EVMAdapter(config);
  },

  connectWallet: async (network: NetworkType): Promise<string> => {
    const adapter = BlockchainService.getAdapter(network);
    return adapter.connectWallet();
  },

  calculateHash: async (file: File): Promise<string> => {
    const buffer = await file.arrayBuffer();
    const hashBuffer = await crypto.subtle.digest('SHA-256', buffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  },

  registerDocument: async (
    metadata: Omit<DocumentMetadata, 'id' | 'createdAt' | 'status'>,
    network: NetworkType
  ): Promise<DocumentMetadata> => {

    // Abstracted Logic: Service doesn't know about block times or gas, logic is inside the adapter
    const adapter = BlockchainService.getAdapter(network);

    const pendingDoc: DocumentMetadata = {
      ...metadata,
      id: `doc_${Date.now()}_${NETWORK_CONFIGS[network].chainId}`,
      createdAt: new Date().toISOString(),
      status: DocumentStatus.PENDING,
      aiForgeryScore: 0,
      network: network
    };

    return adapter.submitTransaction(pendingDoc);
  },

  verifyDocument: async (hash: string, network: NetworkType): Promise<DocumentMetadata | null> => {
    // Cross-chain verification: In a real app, we might query an aggregator or specific chain
    // For now, we query the specific network adapter requested by the UI
    const adapter = BlockchainService.getAdapter(network);
    return adapter.fetchTransaction(hash);
  }
};

