                          </div>
                          {isProcessing && (
                               <div className="absolute bottom-0 left-0 right-0 h-1 bg-slate-100">
                                   <div 
                                      className="h-full bg-brand-600 transition-all duration-300" 
                                      style={{ width: `${uploadProgress}%` }}
                                   ></div>
                               </div>
                          )}
