import React, { useState, useRef, useEffect } from 'react';
import { FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash, QrCode, Loader2, X, Image as ImageIcon, Shield, CheckCircle2, Sparkles, FileWarning, Fingerprint, ScanEye, Zap, Activity, Microscope, Layers, FileJson, ExternalLink, Download } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { PDFService } from '../services/pdfGenerator';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';
import jsQR from 'jsqr';

export const VerifyDocument = () => {
  const { addNotification } = useNotification();
  const { addVerification, currentNetwork } = useGlobalStore();
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hashInput, setHashInput] = useState('');
  const [status, setStatus] = useState<'IDLE' | 'ANALYZING' | 'COMPLETE'>('IDLE');
  const [progress, setProgress] = useState(0);
  const [scanStage, setScanStage] = useState<string>('Initializing'); // For loading text
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);

  // QR Scanning Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  useEffect(() => {
    if (method === VerificationMethod.QR) {
      startCamera();
    } else {
      stopCamera();
    }
  }, [method]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute("playsinline", "true"); 
        await videoRef.current.play();
        requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setCameraError("Unable to access camera. Please ensure permissions are granted.");
      addNotification('error', 'Camera access denied');
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const tick = () => {
    if (!videoRef.current || !streamRef.current) return;
    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (canvas && video.videoWidth > 0 && video.videoHeight > 0) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        const ctx = canvas.getContext("2d", { willReadFrequently: true });
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: "dontInvert" });
          if (code) {
            handleQrDetected(code.data);
            return; 
          }
        }
      }
    }
    animationFrameRef.current = requestAnimationFrame(tick);
  };

  const handleQrDetected = (data: string) => {
    stopCamera();
    setHashInput(data);
    setMethod(VerificationMethod.HASH);
    addNotification('success', 'QR Code Detected', 'Processing hash...');
    handleVerify(data);
  };

  const handleFileSelection = (selectedFile: File) => {
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }
    setFile(selectedFile);
    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const loadSample = (type: 'authentic' | 'forged') => {
    const content = type === 'authentic' 
      ? "Valid Certificate Content: This document is certified authentic by the issuer." 
      : "Tampered Content: This document has been modified by an unauthorized party.";
    const fileName = type === 'authentic' ? 'authentic-certificate-sample.pdf' : 'suspicious-contract-sample.pdf';
    const blob = new Blob([content], { type: 'application/pdf' });
    const sampleFile = new File([blob], fileName, { type: 'application/pdf' });
    handleFileSelection(sampleFile);
    addNotification('info', `Loaded ${type} sample document`);
  };

  const onDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const onDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setStatus('IDLE');
    setResult(null);
  };

  const handleVerify = async (manualHash?: string) => {
    setStatus('ANALYZING');
    setProgress(0);
    setResult(null);

    // Simulated Deep Scan Stages
    const stages = [
      { pct: 10, text: "Calculating SHA-256 Hash..." },
      { pct: 30, text: "Querying Blockchain Smart Contract..." },
      { pct: 45, text: "Initializing Computer Vision Models..." },
      { pct: 60, text: "Scanning for Pixel Manipulation (ELA)..." },
      { pct: 75, text: "Extracting Metadata & EXIF Tags..." },
      { pct: 85, text: "Cross-referencing with Gemini AI..." },
      { pct: 95, text: "Finalizing Ensemble Confidence Score..." }
    ];

    let currentStage = 0;
    const progressInterval = setInterval(() => {
      if (currentStage < stages.length) {
        setScanStage(stages[currentStage].text);
        setProgress(stages[currentStage].pct);
        currentStage++;
      }
    }, 600); // Slower, more "forensic" feel

    try {
      let docHash = manualHash || hashInput;
      let fileTextContext = "No text extracted (Hash mode)";

      if (method === VerificationMethod.FILE && file) {
        docHash = await BlockchainService.calculateHash(file);
        if (file.name.includes('suspicious') || file.name.includes('altered')) {
            fileTextContext = "INCONSISTENT CONTENT DETECTED. The signature block appears pixelated and the date format does not match standard ISO 8601 used by the issuer.";
        } else {
            fileTextContext = "This certifies that the holder has successfully completed all requirements for the Bachelor of Science program. Signed by the Registrar."; 
        }
      }

      const blockchainDoc = await BlockchainService.verifyDocument(docHash, currentNetwork);

      const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in registry.";

      // Call the Advanced AI Pipeline
      const aiAnalysis = await GeminiService.analyzeDocumentAuthenticity(
        fileTextContext, 
        metadataContext,
        file || undefined
      );

      const verificationResult: VerificationResult = {
        isValid: !!blockchainDoc && blockchainDoc.status === 'ACTIVE' && aiAnalysis.isAuthentic,
        document: blockchainDoc || undefined,
        aiAnalysis,
        blockchainProof: blockchainDoc ? {
            txHash: '0x' + Array(64).fill(0).map(() => Math.floor(Math.random() * 16).toString(16)).join(''),
            timestamp: blockchainDoc.createdAt,
            issuerAddress: '0x71C7656EC7ab88b098defB751B7401B5f6d8976F',
            network: blockchainDoc.network || currentNetwork
        } : undefined
      };

      clearInterval(progressInterval);
      setProgress(100);
      setScanStage("Analysis Complete");

      await new Promise(r => setTimeout(r, 600)); 

      setResult(verificationResult);
      addVerification(verificationResult.isValid);

      if (verificationResult.isValid) {
        addNotification('success', 'Document Verified', `Authenticity confirmed on ${currentNetwork}`);
      } else {
        addNotification('error', 'Verification Failed', 'Document appears forged or invalid');
      }

    } catch (error) {
      clearInterval(progressInterval);
      console.error(error);
      addNotification('error', 'Verification error occurred');
    } finally {
      setStatus('COMPLETE');
      setProgress(0);
    }
  };

  const downloadReport = () => {
    if (!result) return;
    try {
      PDFService.generateVerificationReport(result);
      addNotification('success', 'Forensic report downloaded');
    } catch (error) {
      console.error(error);
      addNotification('error', 'Failed to generate report');
    }
  };

  const ForensicCard = ({ title, icon, metric }: { title: string, icon: any, metric?: any }) => (
    <div className={`p-4 rounded-xl border ${metric?.status === 'SAFE' ? 'bg-green-50 border-green-200' : metric?.status === 'WARNING' ? 'bg-amber-50 border-amber-200' : 'bg-red-50 border-red-200'} transition-all hover:shadow-md`}>
      <div className="flex items-center justify-between mb-2">
        <h4 className="font-bold flex items-center text-slate-800">
          {icon} <span className="ml-2">{title}</span>
        </h4>
        <span className={`text-xs font-bold px-2 py-1 rounded-full ${metric?.status === 'SAFE' ? 'bg-green-200 text-green-800' : metric?.status === 'WARNING' ? 'bg-amber-200 text-amber-800' : 'bg-red-200 text-red-800'}`}>
           {metric ? Math.round(metric.score * 100) : 0}% Integrity
        </span>
      </div>
      <p className="text-xs text-slate-600 mb-2">{metric?.details || "No data available."}</p>
      {metric?.detectedIssues && metric.detectedIssues.length > 0 && (
        <ul className="space-y-1">
          {metric.detectedIssues.map((issue: string, i: number) => (
            <li key={i} className="flex items-start text-[10px] font-medium text-red-700">
               <ShieldAlert className="w-3 h-3 mr-1 mt-0.5 flex-shrink-0" />
               {issue}
            </li>
          ))}
        </ul>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-5xl mx-auto animate-slideUp">
        <div className="text-center mb-12">
          <h1 className="text-3xl font-bold text-slate-900">Verify Document Authenticity</h1>
          <p className="mt-2 text-slate-600">Enterprise Forensic Suite: Blockchain • Computer Vision • AI Analysis</p>
        </div>

        {/* Method Selector & Upload UI */}
        <div className="bg-white rounded-2xl shadow-lg overflow-hidden mb-8 transition-all duration-300 border border-slate-100">
          <div className="flex border-b border-slate-200">
            <button onClick={() => setMethod(VerificationMethod.FILE)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.FILE ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <UploadCloud className="w-5 h-5" /> <span>Upload File</span>
            </button>
            <button onClick={() => setMethod(VerificationMethod.HASH)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.HASH ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <Hash className="w-5 h-5" /> <span>Enter Hash</span>
            </button>
            <button onClick={() => setMethod(VerificationMethod.QR)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.QR ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <QrCode className="w-5 h-5" /> <span>Scan QR</span>
            </button>
          </div>

          <div className="p-8">
            {method === VerificationMethod.FILE && (
              <div className="space-y-4 animate-fadeIn">
                {!file ? (
                  <>
                    <div 
                      onDragOver={onDragOver}
                      onDragLeave={onDragLeave}
                      onDrop={onDrop}
                      className={`relative border-2 border-dashed rounded-xl p-10 text-center transition-all duration-300 ease-in-out cursor-pointer overflow-hidden ${
                          isDragging 
                            ? 'border-brand-500 bg-brand-50/50 scale-[1.01] shadow-lg' 
                            : 'border-slate-300 hover:bg-slate-50 hover:border-brand-300'
                      }`}
                    >
                      <input type="file" id="verify-upload" className="hidden" onChange={(e) => e.target.files && handleFileSelection(e.target.files[0])} accept=".pdf,.png,.jpg,.jpeg" />
                      <label htmlFor="verify-upload" className="cursor-pointer block h-full w-full relative z-10">
                        <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4 transition-transform duration-300 ${isDragging ? 'bg-brand-100 scale-110' : 'bg-slate-100'}`}>
                          <FileSearch className={`h-8 w-8 ${isDragging ? 'text-brand-600' : 'text-slate-400'}`} />
                        </div>
                        <span className="text-brand-600 font-bold text-lg block">{isDragging ? 'Drop to verify' : 'Choose Document'}</span>
                        <p className="text-slate-500 mt-2 text-sm">Upload PDF or Image (Max 10MB)</p>
                        <div className="mt-4 flex justify-center space-x-2 text-xs text-slate-400">
                             <span className="flex items-center"><ScanEye className="w-3 h-3 mr-1" /> Vision Scan</span>
                             <span className="flex items-center"><FileJson className="w-3 h-3 mr-1" /> Metadata</span>
                             <span className="flex items-center"><Brain className="w-3 h-3 mr-1" /> Gemini AI</span>
                        </div>
                      </label>
                    </div>

                    <div className="pt-4 flex flex-col sm:flex-row justify-center items-center gap-3">
                      <span className="text-xs font-medium text-slate-400 uppercase tracking-wider mb-2 sm:mb-0 sm:mr-2">Quick Test:</span>
                      <button onClick={() => loadSample('authentic')} className="flex items-center px-3 py-1.5 bg-green-50 text-green-700 text-xs font-semibold rounded-lg border border-green-200 hover:bg-green-100 transition-colors">
                        <CheckCircle2 className="w-3.5 h-3.5 mr-1.5" /> Load Authentic Sample
                      </button>
                      <button onClick={() => loadSample('forged')} className="flex items-center px-3 py-1.5 bg-red-50 text-red-700 text-xs font-semibold rounded-lg border border-red-200 hover:bg-red-100 transition-colors">
                        <FileWarning className="w-3.5 h-3.5 mr-1.5" /> Load Forged Sample
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm animate-scaleIn">
                      <div className="p-4 flex items-center space-x-4">
                          <div className="relative w-16 h-16 rounded-lg overflow-hidden bg-slate-100 border border-slate-200 flex-shrink-0">
                              {previewUrl ? <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" /> : <ImageIcon className="w-8 h-8 text-slate-400" />}
                          </div>
                          <div className="flex-1 min-w-0">
                              <h4 className="text-sm font-semibold text-slate-900 truncate">{file.name}</h4>
                              <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB • {file.type || 'Unknown Type'}</p>
                              <div className="mt-1 flex items-center text-xs text-brand-600 font-medium"><CheckCircle2 className="w-3 h-3 mr-1" /> Ready to verify</div>
                          </div>
                          {(status === 'IDLE' || status === 'COMPLETE') && (
                              <button onClick={clearFile} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"><X className="w-5 h-5" /></button>
                          )}
                      </div>
                  </div>
                )}
              </div>
            )}

            {method === VerificationMethod.HASH && (
              <div className="animate-fadeIn">
                <label className="block text-sm font-medium text-slate-700 mb-2">Document Hash (SHA-256)</label>
                <input type="text" className="w-full px-4 py-3 border border-slate-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-brand-500" placeholder="e.g. e3b0c442..." value={hashInput} onChange={(e) => setHashInput(e.target.value)} />
              </div>
            )}

            {method === VerificationMethod.QR && (
              <div className="flex flex-col items-center justify-center animate-fadeIn">
                {cameraError ? (
                   <div className="text-red-600 bg-red-50 p-4 rounded-lg flex items-center mb-4"><ShieldAlert className="w-5 h-5 mr-2" />{cameraError}</div>
                ) : (
                   <div className="relative w-full max-w-sm aspect-square bg-black rounded-xl overflow-hidden shadow-inner">
                     <video ref={videoRef} className="absolute inset-0 w-full h-full object-cover" muted />
                     <canvas ref={canvasRef} className="hidden" />
                     <div className="absolute inset-0 border-2 border-brand-500/50 flex items-center justify-center pointer-events-none">
                       <div className="w-64 h-64 border-2 border-brand-400 rounded-lg relative animate-pulse shadow-[0_0_15px_rgba(56,189,248,0.5)]"></div>
                     </div>
                   </div>
                )}
              </div>
            )}

            {method !== VerificationMethod.QR && (
              <>
                {status === 'ANALYZING' ? (
                  <div className="mt-6 w-full bg-slate-50 rounded-lg p-6 border border-slate-100 animate-fadeIn">
                    <div className="flex justify-between text-sm mb-3 text-slate-600 font-medium">
                      <span className="flex items-center text-brand-600"><Microscope className="w-4 h-4 mr-2 animate-pulse"/> {scanStage}</span>
                      <span>{Math.round(progress)}%</span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-3 overflow-hidden mb-2">
                      <div className="bg-brand-600 h-full rounded-full transition-all duration-300 ease-out relative overflow-hidden" style={{ width: `${progress}%` }}>
                          <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite]"></div>
                      </div>
                    </div>
                    <div className="flex justify-between text-xs text-slate-400 mt-2">
                        <span>Vision Models</span>
                        <span>Metadata</span>
                        <span>Gemini AI</span>
                    </div>
                  </div>
                ) : (
                  <button 
                    onClick={() => handleVerify()}
                    disabled={(method === 'FILE' && !file) || (method === 'HASH' && !hashInput)}
                    className="mt-6 w-full py-4 bg-brand-600 text-white rounded-xl font-bold hover:bg-brand-700 transition-colors disabled:opacity-50 flex justify-center items-center shadow-lg hover:shadow-xl hover:-translate-y-0.5 transform active:scale-[0.99]"
                  >
                    <Zap className="w-5 h-5 mr-2" />
                    Run Deep Forensic Scan
                  </button>
                )}
              </>
            )}
          </div>
        </div>

        {status === 'COMPLETE' && result && (
          <div className={`rounded-2xl shadow-xl overflow-hidden border-t-8 ${result.isValid ? 'border-green-500' : 'border-red-500'} bg-white animate-slideUp`}>

            {/* Header Result */}
            <div className={`p-8 flex items-center justify-between ${result.isValid ? 'bg-green-50' : 'bg-red-50'}`}>
              <div className="flex items-center space-x-4">
                {result.isValid ? <CheckCircle className="w-12 h-12 text-green-600 animate-scaleIn" /> : <ShieldAlert className="w-12 h-12 text-red-600 animate-scaleIn" />}
                <div>
                  <h2 className="text-3xl font-bold text-slate-900">{result.isValid ? 'Authentic Document' : 'Verification Failed'}</h2>
                  <p className="text-slate-600 font-medium">{result.isValid ? 'Passed all forensic layers' : 'Tampering detected in deep scan'}</p>
                </div>
              </div>
              <div className="text-right">
                <div className="text-sm font-semibold text-slate-500 uppercase tracking-wide">Ensemble Score</div>
                <div className={`text-4xl font-extrabold ${result.isValid ? 'text-green-600' : 'text-red-600'}`}>
                    {(result.aiAnalysis?.forensics?.overallScore || 0) * 100}%
                </div>
              </div>
            </div>

            <div className="p-8">
               {/* Advanced Forensic Dashboard Grid */}
               <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center justify-between">
                  <div className="flex items-center">
                    <Activity className="w-5 h-5 mr-2 text-brand-600" />
                    Forensic Analysis Report
                  </div>
                  <button 
                    onClick={downloadReport}
                    className="flex items-center px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-bold transition-colors"
                  >
                    <Download className="w-4 h-4 mr-2" /> Download Full Report
                  </button>
               </h3>

               <div className="grid md:grid-cols-3 gap-4 mb-8">
                  <ForensicCard 
                    title="Visual Forensics" 
                    icon={<ScanEye className="w-5 h-5 text-purple-500" />} 
                    metric={result.aiAnalysis?.forensics?.visual}
                  />
                  <ForensicCard 
                    title="Metadata Analysis" 
                    icon={<Layers className="w-5 h-5 text-blue-500" />} 
                    metric={result.aiAnalysis?.forensics?.metadata}
                  />
                  <ForensicCard 
                    title="Semantic Logic" 
                    icon={<Brain className="w-5 h-5 text-emerald-500" />} 
                    metric={result.aiAnalysis?.forensics?.content}
                  />
               </div>

               <div className="grid md:grid-cols-2 gap-8 pt-4 border-t border-slate-100">
                  <div className="space-y-4">
                      <h3 className="font-semibold text-slate-900 flex items-center">
                        <FileCheck className="w-5 h-5 mr-2 text-brand-600" /> Blockchain Evidence
                      </h3>
                      {result.document ? (
                        <div className="bg-slate-50 rounded-lg p-4 space-y-3 text-sm hover:bg-slate-100 transition-colors border border-slate-200">
                          <div className="flex justify-between border-b border-slate-200 pb-2">
                             <span className="text-slate-500">Issuer</span>
                             <span className="font-medium text-slate-900">{result.document.issuerName}</span>
                          </div>
                          <div className="flex justify-between border-b border-slate-200 pb-2">
                             <span className="text-slate-500">Anchored</span>
                             <span className="font-mono text-slate-700">{new Date(result.document.createdAt).toLocaleDateString()}</span>
                          </div>
                          <div className="flex justify-between items-center">
                              <span className="text-slate-500">Network</span>
                              <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-bold bg-slate-200 text-slate-800">
                                {result.blockchainProof?.network || currentNetwork}
                              </span>
                          </div>
                          <div className="mt-2 text-xs font-mono text-slate-400 break-all mb-2">
                              Tx: {result.blockchainProof?.txHash}
                          </div>
                          <div className="pt-2 border-t border-slate-200">
                            <span className="block text-slate-500 text-xs mb-1">IPFS Storage</span>
                            <div className="flex items-center">
                                <span className="font-mono text-xs text-slate-700 mr-2">{result.document.ipfsCid.substring(0, 15)}...</span>
                                <a href={`https://ipfs.io/ipfs/${result.document.ipfsCid}`} target="_blank" rel="noreferrer" className="text-brand-600 hover:text-brand-700 text-xs font-bold flex items-center">
                                    View <ExternalLink className="w-3 h-3 ml-1" />
                                </a>
                            </div>
                          </div>
                        </div>
                      ) : (
                        <div className="p-4 bg-red-50 text-red-700 rounded-lg text-sm border border-red-100">
                           <div className="font-bold flex items-center mb-1"><X className="w-4 h-4 mr-1"/> Hash Mismatch</div>
                           No record found in the decentralized registry.
                        </div>
                      )}
                  </div>

                  <div className="space-y-4">
                      <h3 className="font-semibold text-slate-900 flex items-center">
                        <Brain className="w-5 h-5 mr-2 text-purple-600" /> AI Executive Summary
                      </h3>
                      <div className="bg-slate-50 rounded-lg p-5 text-sm leading-relaxed border border-slate-200 relative overflow-hidden">
                          <div className="absolute top-0 right-0 p-2 opacity-10">
                              <Fingerprint className="w-16 h-16" />
                          </div>
                          <p className="text-slate-700 italic relative z-10">
                              "{result.aiAnalysis?.reasoning}"
                          </p>
                      </div>
                  </div>
               </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
import QRCode from "qrcode";
import { DocumentMetadata, VerificationResult } from "../types";

export const PDFService = {

  // 1. Generate Registration Receipt with QR Code
  generateRegistrationReceipt: async (doc: DocumentMetadata) => {
    const pdf = new jsPDF();

    // Header
    pdf.setFillColor(14, 165, 233); // Brand color
    pdf.rect(0, 0, 210, 40, 'F');
    pdf.setTextColor(255, 255, 255);
    pdf.setFontSize(22);
    pdf.text("TrustChain AI", 20, 20);
    pdf.setFontSize(12);
    pdf.text("Digital Asset Registration Receipt", 20, 30);

    // QR Code Generation
    // Create a link to the verify page with the hash as a query parameter
    const verificationLink = `${window.location.origin}/#/verify?hash=${doc.hash}`;

    try {
      const qrDataUrl = await QRCode.toDataURL(verificationLink, { 
        errorCorrectionLevel: 'H',
        margin: 1,
        color: {
            dark: '#000000',
            light: '#ffffff'
        }
      });

      // Add QR Code to Top Right
      pdf.addImage(qrDataUrl, 'PNG', 160, 5, 30, 30);
      pdf.setFontSize(8);
      pdf.text("Scan to Verify", 175, 38, { align: "center" });

    } catch (err) {
      console.error("Error generating QR code for PDF", err);
    }

    // Content
    pdf.setTextColor(33, 33, 33);
    pdf.setFontSize(10);
    pdf.text(`Generated: ${new Date().toLocaleString()}`, 20, 50);

    const data = [
      ["Document Title", doc.title],
      ["Document Type", doc.type],
      ["Issuer Identity", doc.issuerName],
      ["Registration Date", new Date(doc.createdAt).toLocaleString()],
      ["Blockchain Network", doc.network || "Unknown"],
      ["Status", doc.status],
    ];

    autoTable(pdf, {
      startY: 60,
      head: [['Attribute', 'Details']],
      body: data,
      theme: 'grid',
      headStyles: { fillColor: [14, 165, 233] },
    });

    // Hash & Technical Details
    const finalY = (pdf as any).lastAutoTable.finalY + 10;
    pdf.setFontSize(12);
    pdf.setFont("helvetica", "bold");
    pdf.text("Cryptographic Proofs", 20, finalY);

    pdf.setFontSize(10);
    pdf.setFont("helvetica", "normal");

    pdf.text("SHA-256 Hash:", 20, finalY + 10);
    pdf.setFont("courier");
    pdf.text(doc.hash, 20, finalY + 16);

    pdf.setFont("helvetica");
    pdf.text("IPFS Content Identifier (CID):", 20, finalY + 26);
    pdf.setFont("courier");
    pdf.text(doc.ipfsCid, 20, finalY + 32);

    // Footer
    pdf.setFont("helvetica");
    pdf.setFontSize(8);
    pdf.setTextColor(150);
    pdf.text("This document is cryptographically secured on the blockchain.", 105, 280, { align: "center" });
    pdf.text(`Receipt ID: ${doc.id}`, 105, 285, { align: "center" });

    pdf.save(`Receipt_${doc.id}.pdf`);
  },

  // 2. Generate Verification Forensic Report
  generateVerificationReport: (result: VerificationResult) => {
    const pdf = new jsPDF();
    const isAuthentic = result.isValid;
    const color = isAuthentic ? [34, 197, 94] : [239, 68, 68]; // Green or Red

    // Header
    pdf.setFillColor(color[0], color[1], color[2]);
    pdf.rect(0, 0, 210, 40, 'F');
    pdf.setTextColor(255, 255, 255);
    pdf.setFontSize(22);
    pdf.text("TrustChain AI", 20, 20);
    pdf.setFontSize(14);
    pdf.text("Forensic Verification Report", 20, 32);

    // Status Banner
    pdf.setTextColor(33, 33, 33);
    pdf.setFontSize(16);
    pdf.setFont("helvetica", "bold");
    pdf.text(`VERIFICATION STATUS: ${isAuthentic ? 'AUTHENTIC' : 'FAILED'}`, 20, 55);

    pdf.setFontSize(10);
    pdf.setFont("helvetica", "normal");
    pdf.text(`Ensemble Confidence Score: ${(result.aiAnalysis?.forensics?.overallScore || 0) * 100}%`, 20, 62);

    // AI Reasoning
    if (result.aiAnalysis?.reasoning) {
        pdf.setDrawColor(200);
        pdf.setFillColor(245, 247, 250);
        pdf.roundedRect(20, 70, 170, 25, 3, 3, 'FD');
        pdf.setFontSize(9);
        pdf.setTextColor(60);
        const splitText = pdf.splitTextToSize(result.aiAnalysis.reasoning, 160);
        pdf.text(splitText, 25, 80);
    }

    // Forensic Metrics Table
    const forensics = result.aiAnalysis?.forensics;
    const metricData = [
        ["Visual Integrity", `${(forensics?.visual?.score || 0) * 100}%`, forensics?.visual?.status || "N/A"],
        ["Metadata Analysis", `${(forensics?.metadata?.score || 0) * 100}%`, forensics?.metadata?.status || "N/A"],
        ["Content Logic", `${(forensics?.content?.score || 0) * 100}%`, forensics?.content?.status || "N/A"]
    ];

    autoTable(pdf, {
      startY: 105,
      head: [['Forensic Layer', 'Score', 'Status']],
      body: metricData,
      theme: 'striped',
      headStyles: { fillColor: [50, 50, 50] },
    });

    // Blockchain Evidence
    if (result.document) {
        const evidenceY = (pdf as any).lastAutoTable.finalY + 15;
        pdf.setFontSize(12);
        pdf.setTextColor(33);
        pdf.text("Blockchain Evidence", 20, evidenceY);

        const blockchainData = [
            ["Issuer", result.document.issuerName],
            ["Registered Date", new Date(result.document.createdAt).toLocaleString()],
            ["Network", result.blockchainProof?.network || "Unknown"],
            ["Transaction Hash", result.blockchainProof?.txHash || "N/A"],
            ["IPFS CID", result.document.ipfsCid]
        ];

        autoTable(pdf, {
            startY: evidenceY + 5,
            body: blockchainData,
            theme: 'plain',
            styles: { fontSize: 9, cellPadding: 2 },
            columnStyles: { 0: { fontStyle: 'bold', cellWidth: 50 } }
        });
    }

    pdf.save(`Forensic_Report_${new Date().getTime()}.pdf`);
  },

  // 3. Generate System Analytics Report
  generateSystemReport: (type: 'DAILY' | 'MONTHLY' | 'ANNUAL', stats: any, logs: any[]) => {
    const pdf = new jsPDF();

    // Header
    pdf.setFillColor(30, 41, 59); // Slate 800
    pdf.rect(0, 0, 210, 50, 'F');
    pdf.setTextColor(255, 255, 255);
    pdf.setFontSize(24);
    pdf.text("TrustChain AI", 20, 25);
    pdf.setFontSize(14);
    pdf.text(`System Analytics Report - ${type}`, 20, 38);
    pdf.setFontSize(10);
    pdf.setTextColor(200);
    pdf.text(`Generated: ${new Date().toLocaleString()}`, 20, 45);

    // Summary Stats
    pdf.setTextColor(33, 33, 33);
    pdf.setFontSize(14);
    pdf.text("Executive Summary", 20, 65);

    const statsData = [
        ["Total Documents Secured", stats.total.toLocaleString()],
        ["Verifications Processed", stats.verify24h.toLocaleString()],
        ["Fraud Attempts Blocked", stats.fraud.toLocaleString()],
        ["Active Issuers", stats.issuers.toString()]
    ];

    autoTable(pdf, {
        startY: 70,
        head: [['Metric', 'Value']],
        body: statsData,
        theme: 'grid',
        headStyles: { fillColor: [14, 165, 233] },
        columnStyles: { 0: { fontStyle: 'bold' } }
    });

    // Recent System Activity Log
    const logY = (pdf as any).lastAutoTable.finalY + 15;
    pdf.setFontSize(14);
    pdf.text("System Activity Log", 20, logY);

    const logData = logs.slice(0, 15).map(log => [log.time, log.type.toUpperCase(), log.msg]);

    autoTable(pdf, {
        startY: logY + 5,
        head: [['Timestamp', 'Type', 'Event Message']],
        body: logData,
        theme: 'striped',
        headStyles: { fillColor: [71, 85, 105] },
        styles: { fontSize: 8 }
    });

    // Footer
    pdf.setFontSize(8);
    pdf.setTextColor(150);
    pdf.text("TrustChain AI Enterprise Reporting Module", 105, 280, { align: "center" });

    pdf.save(`TrustChain_${type}_Report_${new Date().toISOString().split('T')[0]}.pdf`);
  }
};

import React, { useState, useEffect } from 'react';
import { Upload, FileText, Wallet, Loader2, CheckCircle2, X, Copy, LogOut, Download, Shield, UploadCloud, Sparkles, Lock, Building2, ExternalLink } from 'lucide-react';
import { BlockchainService, NETWORK_CONFIGS } from '../services/blockchain';
import { PDFService } from '../services/pdfGenerator';
import { DocumentMetadata } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';

export const CreateDocument = () => {
  const { addNotification } = useNotification();
  const { addDocument, userRole, setUserRole, currentNetwork } = useGlobalStore();
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [walletAddress, setWalletAddress] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [registeredDoc, setRegisteredDoc] = useState<DocumentMetadata | null>(null);

  const [formData, setFormData] = useState({
    title: '',
    issuerName: '',
    type: 'Certificate',
    description: ''
  });

  // Attempt to auto-connect if wallet was previously connected
  useEffect(() => {
    const savedAddress = localStorage.getItem('trustchain_wallet');
    if (savedAddress) {
      setWalletAddress(savedAddress);
    }
  }, []);

  // Access Control Gate
  if (userRole === 'GUEST') {
    return (
      <div className="min-h-screen bg-slate-50 py-20 px-4">
        <div className="max-w-xl mx-auto text-center animate-slideUp">
          <div className="bg-white rounded-3xl shadow-xl p-10 border border-slate-100">
            <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-6">
              <Lock className="w-10 h-10 text-slate-400" />
            </div>
            <h1 className="text-3xl font-bold text-slate-900 mb-4">Enterprise Access Only</h1>
            <p className="text-slate-600 mb-8">
              Document issuance is restricted to verified organizations. Please connect a wallet with Issuer credentials or apply for enterprise onboarding.
            </p>

            <div className="space-y-4">
              <button 
                onClick={() => setUserRole('ISSUER')}
                className="w-full py-4 bg-brand-600 text-white rounded-xl font-bold hover:bg-brand-700 transition-all shadow-lg hover:shadow-xl hover:-translate-y-0.5"
              >
                Connect Issuer Wallet
              </button>

              <button className="w-full py-4 bg-white border border-slate-200 text-slate-700 rounded-xl font-bold hover:bg-slate-50 transition-all">
                Apply for Enterprise Verification
              </button>
            </div>

            <div className="mt-8 pt-8 border-t border-slate-100">
               <div className="flex items-center justify-center space-x-2 text-xs text-slate-500 font-medium uppercase tracking-wider">
                  <Building2 className="w-4 h-4" />
                  <span>TrustChain Gov/Enterprise Gateway</span>
               </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const connectWallet = async () => {
    try {
      const address = await BlockchainService.connectWallet(currentNetwork);
      setWalletAddress(address);
      localStorage.setItem('trustchain_wallet', address);
      addNotification('success', 'Wallet Connected Successfully', `Connected to ${currentNetwork}`);
    } catch (err) {
      addNotification('error', 'Failed to connect wallet');
    }
  };

  const handleFileSelection = (selectedFile: File) => {
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }
    setFile(selectedFile);
    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const handleAutoFill = () => {
    const titles = ['Supply Chain Manifest', 'University Diploma', 'Real Estate Deed', 'Employment Agreement'];
    const issuers = ['Logistics Global Inc.', 'Stanford University', 'City Land Registry', 'TechInnovate Corp'];
    const types = ['Certificate', 'Contract', 'Identity Proof', 'Transcripts'];

    const rand = Math.floor(Math.random() * titles.length);

    setFormData({
      title: titles[rand] + ` #${Math.floor(Math.random() * 1000)}`,
      issuerName: issuers[rand],
      type: types[rand],
      description: `Auto-generated sample document for demonstration purposes. Verified on ${new Date().toLocaleDateString()}.`
    });

    const content = "This is a sample document content generated for auto-fill testing. It simulates a valid digital asset.";
    const blob = new Blob([content], { type: 'application/pdf' });
    const dummyFile = new File([blob], `sample_${titles[rand].toLowerCase().replace(/\s/g, '_')}.pdf`, { type: 'application/pdf' });
    handleFileSelection(dummyFile);

    addNotification('info', 'Form Auto-Filled', 'Sample data and file loaded.');
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFileSelection(e.target.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!walletAddress || !file) return;

    setIsProcessing(true);
    setUploadProgress(0);

    // Dynamic animation speed based on block time
    // Fast chains (Avalanche) update very quickly, Mainnet updates slowly
    const blockTime = NETWORK_CONFIGS[currentNetwork].blockTimeMs;
    const updateInterval = blockTime / 20; // Break into ~20 steps

    const progressInterval = setInterval(() => {
      setUploadProgress(prev => {
        if (prev >= 90) return prev;
        return prev + Math.random() * 10;
      });
    }, updateInterval);

    try {
      const hash = await BlockchainService.calculateHash(file);
      addNotification('info', 'File Hashed locally (SHA-256)', 'Security check passed');

      const ipfsCid = "QmMockCidForDemoPurposeOnly12345"; 

      // Pass current network to service to get realistic delay
      const newDoc = await BlockchainService.registerDocument({
        title: formData.title,
        issuerName: formData.issuerName,
        type: formData.type,
        description: formData.description,
        hash,
        ipfsCid
      }, currentNetwork);

      addDocument(newDoc);

      clearInterval(progressInterval);
      setUploadProgress(100);

      await new Promise(resolve => setTimeout(resolve, 600));

      setRegisteredDoc(newDoc);
      setStep(3);
      addNotification('success', 'Document Registered!', `Transaction confirmed on ${currentNetwork}`);
    } catch (err) {
      clearInterval(progressInterval);
      console.error(err);
      addNotification('error', 'Registration failed', 'Please try again');
    } finally {
      setIsProcessing(false);
      setUploadProgress(0);
    }
  };

  const downloadReceipt = async () => {
    if (!registeredDoc) return;

    // Use the new PDF Service with await for QR code generation
    try {
      await PDFService.generateRegistrationReceipt(registeredDoc);
      addNotification('success', 'Receipt downloaded successfully');
    } catch (error) {
      console.error(error);
      addNotification('error', 'Failed to generate receipt PDF');
    }
  };

  const copyAddress = () => {
    if (walletAddress) {
        navigator.clipboard.writeText(walletAddress);
        addNotification('info', 'Address copied to clipboard');
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-3xl mx-auto animate-slideUp">
        <div className="mb-10 text-center">
          <div className="inline-flex items-center px-3 py-1 rounded-full bg-slate-100 text-slate-600 text-xs font-bold uppercase tracking-wider mb-4 border border-slate-200">
             <Building2 className="w-3 h-3 mr-2" />
             Enterprise Portal
          </div>
          <h1 className="text-3xl font-bold text-slate-900">Register New Document</h1>
          <p className="mt-2 text-slate-600">Securely anchor your document to the <span className="font-bold text-brand-600">{currentNetwork}</span>.</p>
        </div>

        {/* Progress Steps */}
        <div className="mb-8 flex justify-center items-center space-x-4">
          {[1, 2, 3].map((s) => (
            <div key={s} className={`flex items-center ${s < 3 ? 'w-full' : ''}`}>
               <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm transition-all duration-300 ${
                 step >= s ? 'bg-brand-600 text-white scale-110' : 'bg-slate-200 text-slate-500'
               }`}>
                 {s}
               </div>
               {s < 3 && <div className={`h-1 flex-1 mx-2 transition-all duration-500 ${step > s ? 'bg-brand-600' : 'bg-slate-200'}`} />}
            </div>
          ))}
        </div>

        <div className="bg-white shadow-xl rounded-2xl overflow-hidden transition-all duration-300">
          {/* Step 1: Wallet Connection */}
          {step === 1 && (
            <div className="p-10 animate-fadeIn">
              <div className="text-center mb-8">
                <div className="mx-auto w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mb-6">
                  <Wallet className="h-8 w-8 text-brand-600" />
                </div>
                <h2 className="text-2xl font-bold text-slate-900 mb-2">Connect Enterprise Wallet</h2>
                <p className="text-slate-600 max-w-md mx-auto">
                  Connect your organization's verified wallet to sign transactions and pay gas fees on {currentNetwork}.
                </p>
              </div>

              {!walletAddress ? (
                <div className="flex justify-center">
                    <button 
                    onClick={connectWallet}
                    className="inline-flex items-center px-8 py-4 border border-transparent text-lg font-medium rounded-xl text-white bg-brand-600 hover:bg-brand-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-brand-500 shadow-lg hover:shadow-xl transition-all transform hover:-translate-y-0.5"
                    >
                    <div className="w-6 h-6 mr-3 bg-white rounded-full flex items-center justify-center p-0.5">
                       <Wallet className="w-4 h-4 text-brand-600" />
                    </div>
                    Connect MetaMask
                    </button>
                </div>
              ) : (
                <div className="max-w-md mx-auto bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden animate-scaleIn">
                    <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex justify-between items-center">
                        <div className="flex items-center space-x-2">
                        <span className="relative flex h-2.5 w-2.5">
                            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                            <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-green-500"></span>
                        </span>
                        <span className="text-sm font-semibold text-slate-700">Connected</span>
                        </div>
                        <span className="text-xs font-mono font-medium text-brand-600 bg-brand-50 px-2 py-1 rounded">{currentNetwork}</span>
                    </div>

                    <div className="p-6">
                        <div className="flex items-center space-x-4 mb-6">
                            <div className="w-12 h-12 rounded-full bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white shadow-md">
                                <Wallet className="w-6 h-6" />
                            </div>
                            <div className="flex-1 overflow-hidden">
                                <p className="text-xs text-slate-500 uppercase tracking-wider font-semibold">Wallet Address</p>
                                <div className="flex items-center space-x-2">
                                    <span className="font-mono text-lg font-bold text-slate-900 truncate">
                                        {walletAddress.slice(0, 6)}...{walletAddress.slice(-6)}
                                    </span>
                                    <button 
                                        onClick={copyAddress}
                                        className="text-slate-400 hover:text-brand-600 transition-colors p-1"
                                        title="Copy Address"
                                    >
                                        <Copy className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        </div>

                        <div className="bg-slate-50 rounded-lg p-4 mb-6 border border-slate-100 flex justify-between items-center">
                            <div>
                                <p className="text-xs text-slate-500 mb-0.5">Estimated Balance</p>
                                <p className="text-xl font-bold text-slate-900">1.842 {NETWORK_CONFIGS[currentNetwork].currency}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-xs text-slate-500 mb-0.5">Role</p>
                                <p className="text-sm font-medium text-purple-600 flex items-center justify-end">
                                    <CheckCircle2 className="w-3 h-3 mr-1" /> {userRole}
                                </p>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            <button 
                                onClick={() => {
                                  setWalletAddress(null);
                                  localStorage.removeItem('trustchain_wallet');
                                  addNotification('info', 'Wallet Disconnected');
                                }} 
                                className="flex items-center justify-center py-2.5 border border-slate-300 rounded-lg text-slate-600 hover:bg-red-50 hover:text-red-600 hover:border-red-200 text-sm font-medium transition-colors"
                            >
                                <LogOut className="w-4 h-4 mr-2" />
                                Disconnect
                            </button>
                            <button 
                                onClick={() => setStep(2)} 
                                className="flex items-center justify-center py-2.5 bg-brand-600 rounded-lg text-white hover:bg-brand-700 text-sm font-bold shadow-md hover:shadow-lg transition-all"
                            >
                                Continue
                                <CheckCircle2 className="w-4 h-4 ml-2" />
                            </button>
                        </div>
                    </div>
                </div>
              )}
            </div>
          )}

          {/* Step 2: Form & Upload */}
          {step === 2 && (
            <div className="p-8 animate-fadeIn relative">
              <div className="absolute top-8 right-8 z-10">
                 <button 
                   type="button"
                   onClick={handleAutoFill}
                   className="flex items-center text-xs font-bold text-brand-600 hover:text-brand-700 bg-brand-50 hover:bg-brand-100 px-3 py-1.5 rounded-full transition-colors"
                   title="Fill form with sample data"
                 >
                   <Sparkles className="w-3.5 h-3.5 mr-1" />
                   Auto-Fill
                 </button>
              </div>

              <form onSubmit={handleSubmit} className="mt-2">
                <div className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Document Title</label>
                      <input 
                        required
                        type="text" 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500 focus:border-brand-500"
                        placeholder="e.g. Degree Certificate"
                        value={formData.title}
                        onChange={e => setFormData({...formData, title: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">Document Type</label>
                      <select 
                        className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-brand-500"
                        value={formData.type}
                        onChange={e => setFormData({...formData, type: e.target.value})}
                      >
                        <option>Certificate</option>
                        <option>Contract</option>
                        <option>Identity Proof</option>
                        <option>Transcripts</option>
                      </select>
                    </div>
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Issuer Name</label>
                    <input 
                      required
                      type="text" 
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg"
                      placeholder="Organization Name"
                      value={formData.issuerName}
                      onChange={e => setFormData({...formData, issuerName: e.target.value})}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Description (Optional)</label>
                    <textarea 
                      className="w-full px-4 py-2 border border-slate-300 rounded-lg"
                      rows={3}
                      value={formData.description}
                      onChange={e => setFormData({...formData, description: e.target.value})}
                    />
                  </div>

                  <div className="space-y-2">
                    <label className="block text-sm font-medium text-slate-700">Document File</label>

                    {!file ? (
                      <div 
                        onDragOver={onDragOver}
                        onDragLeave={onDragLeave}
                        onDrop={onDrop}
                        className={`relative border-2 border-dashed rounded-xl p-8 text-center transition-all duration-300 ease-in-out cursor-pointer overflow-hidden ${
                          isDragging 
                            ? 'border-brand-500 bg-brand-50/50 scale-[1.01] shadow-lg' 
                            : 'border-slate-300 hover:border-brand-400 hover:bg-slate-50'
                        }`}
                      >
                        <input 
                          type="file" 
                          id="file-upload" 
                          className="hidden" 
                          onChange={handleFileChange}
                          accept=".pdf,.png,.jpg,.jpeg"
                        />
                        <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center justify-center h-full w-full relative z-10">
                          <div className={`w-16 h-16 rounded-full flex items-center justify-center mb-4 transition-transform duration-300 ${
                            isDragging ? 'bg-brand-100 scale-110' : 'bg-slate-100'
                          }`}>
                            <UploadCloud className={`h-8 w-8 ${isDragging ? 'text-brand-600' : 'text-slate-400'}`} />
                          </div>
                          <h3 className="text-lg font-semibold text-slate-900 mb-1">
                            {isDragging ? 'Drop to upload' : 'Click or drag file here'}
                          </h3>
                          <p className="text-sm text-slate-500 mb-4">
                              PDF, PNG, JPG (Max 10MB)
                          </p>
                          <div className="inline-flex items-center px-3 py-1 rounded-full bg-slate-100 text-xs font-medium text-slate-600">
                               <Shield className="w-3 h-3 mr-1.5" />
                               Secure Local Hashing
                          </div>
                        </label>

                        {isDragging && (
                          <div className="absolute inset-0 bg-brand-50/50 backdrop-blur-[1px] flex items-center justify-center z-0">
                               <div className="absolute inset-0 bg-grid-brand-500/[0.05] [mask-image:linear-gradient(0deg,white,transparent)]"></div>
                          </div>
                        )}
                      </div>
                    ) : (
                      <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm animate-scaleIn group relative">
                          <div className="p-4 flex items-center space-x-4">
                              <div className="relative w-16 h-16 rounded-lg overflow-hidden bg-slate-100 border border-slate-200 flex-shrink-0">
                                  {previewUrl ? (
                                      <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" />
                                  ) : (
                                      <div className="w-full h-full flex items-center justify-center">
                                          <FileText className="w-8 h-8 text-slate-400" />
                                      </div>
                                  )}
                              </div>
                              <div className="flex-1 min-w-0">
                                  <h4 className="text-sm font-semibold text-slate-900 truncate">{file.name}</h4>
                                  <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB • {file.type || 'Unknown Type'}</p>
                                  <div className="mt-1 flex items-center text-xs text-green-600 font-medium">
                                      <CheckCircle2 className="w-3 h-3 mr-1" />
                                      Ready for hashing
                                  </div>
                              </div>
                              {!isProcessing && (
                                  <button 
                                      onClick={clearFile}
                                      type="button"
                                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                                      title="Remove file"
                                  >
                                      <X className="w-5 h-5" />
                                  </button>
                              )}
                          </div>
                          {isProcessing && (
                               <div className="absolute bottom-0 left-0 right-0 h-1 bg-slate-100">
                                   <div 
                                      className="h-full bg-brand-600 transition-all duration-300" 
                                      style={{ width: `${uploadProgress}%` }}
                                   ></div>
                               </div>
                          )}
                      </div>
                    )}
                  </div>

                  {isProcessing ? (
                    <div className="w-full bg-slate-50 rounded-lg p-4 border border-slate-100 text-center">
                      <Loader2 className="w-8 h-8 text-brand-600 animate-spin mx-auto mb-3" />
                      <h3 className="text-sm font-bold text-slate-900">Securing Document</h3>
                      <p className="text-xs text-slate-500 mt-1">Encrypting & Anchoring to {currentNetwork}...</p>
                      <p className="text-xs text-brand-600 font-mono mt-1">Routing to Chain ID: {NETWORK_CONFIGS[currentNetwork].chainId}</p>
                    </div>
                  ) : (
                    <button 
                      type="submit"
                      disabled={!file}
                      className="w-full py-3 bg-brand-600 text-white rounded-lg font-bold text-lg hover:bg-brand-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center shadow-lg hover:shadow-xl transform active:scale-[0.98]"
                    >
                      Register Document
                    </button>
                  )}
                </div>
              </form>
            </div>
          )}

          {/* Step 3: Success */}
          {step === 3 && registeredDoc && (
            <div className="p-10 text-center animate-scaleIn">
              <div className="mx-auto w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mb-6">
                <CheckCircle2 className="h-10 w-10 text-green-600" />
              </div>
              <h2 className="text-3xl font-bold text-slate-900 mb-2">Registration Successful!</h2>
              <p className="text-slate-600 mb-8">
                Your document has been cryptographically secured on the <span className="font-bold">{currentNetwork}</span> blockchain.
              </p>

              <div className="bg-slate-50 p-6 rounded-xl text-left space-y-4 mb-8">
                <div className="flex justify-between border-b border-slate-200 pb-2">
                  <span className="text-slate-500">Document Hash</span>
                  <span className="font-mono text-sm text-slate-900">{registeredDoc.hash.slice(0, 20)}...</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-2">
                  <span className="text-slate-500">Transaction ID</span>
                  <span className="font-mono text-sm text-brand-600 cursor-pointer">0x7f...3a9c</span>
                </div>
                <div className="flex justify-between border-b border-slate-200 pb-2">
                  <span className="text-slate-500">IPFS CID</span>
                  <div className="flex items-center">
                     <span className="font-mono text-xs text-slate-700 mr-2">{registeredDoc.ipfsCid.substring(0, 12)}...</span>
                     <ExternalLink className="w-3 h-3 text-slate-400 cursor-pointer hover:text-brand-600" onClick={() => window.open(`https://ipfs.io/ipfs/${registeredDoc.ipfsCid}`, '_blank')} />
                  </div>
                </div>
                <div className="flex justify-between">
                  <span className="text-slate-500">Network</span>
                  <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                    {currentNetwork}
                  </span>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-4 justify-center">
                  <button 
                    onClick={downloadReceipt}
                    className="inline-flex items-center justify-center px-6 py-3 border border-slate-200 shadow-sm text-base font-bold rounded-xl text-slate-700 bg-white hover:bg-slate-50 hover:border-slate-300 transition-all hover:-translate-y-0.5"
                  >
                    <Download className="w-5 h-5 mr-2 text-brand-600" />
                    Download Receipt (PDF)
                  </button>
                  <button 
                    onClick={() => window.location.reload()}
                    className="inline-flex items-center justify-center px-6 py-3 border border-transparent text-base font-bold rounded-xl text-white bg-brand-600 hover:bg-brand-700 shadow-md hover:shadow-lg transition-all hover:-translate-y-0.5"
                  >
                    Register Another
                  </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash, QrCode, Loader2, X, Image as ImageIcon, Shield, CheckCircle2, Sparkles, FileWarning, Fingerprint, ScanEye, Zap, Activity, Microscope, Layers, FileJson, ExternalLink, Download } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { PDFService } from '../services/pdfGenerator';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';
import jsQR from 'jsqr';

export const VerifyDocument = () => {
  const { addNotification } = useNotification();
  const { addVerification, currentNetwork } = useGlobalStore();
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hashInput, setHashInput] = useState('');
  const [status, setStatus] = useState<'IDLE' | 'ANALYZING' | 'COMPLETE'>('IDLE');
  const [progress, setProgress] = useState(0);
  const [scanStage, setScanStage] = useState<string>('Initializing'); // For loading text
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);

  // QR Scanning Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  useEffect(() => {
    if (method === VerificationMethod.QR) {
      startCamera();
    } else {
      stopCamera();
    }
  }, [method]);

  // Check for URL parameters (e.g. from QR code scan)
  useEffect(() => {
    const checkUrlParams = () => {
      try {
        const hashPart = window.location.hash.split('?')[1];
        if (hashPart) {
            const params = new URLSearchParams(hashPart);
            const urlHash = params.get('hash');
            if (urlHash) {
                setHashInput(urlHash);
                setMethod(VerificationMethod.HASH);
                // Optionally auto-trigger
                // handleVerify(urlHash);
                addNotification('info', 'Hash detected from URL', 'Ready to verify');
            }
        }
      } catch (e) {
        console.error("Error parsing URL params", e);
      }
    };

    checkUrlParams();
  }, [addNotification]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute("playsinline", "true"); 
        await videoRef.current.play();
        requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setCameraError("Unable to access camera. Please ensure permissions are granted.");
      addNotification('error', 'Camera access denied');
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const tick = () => {
    if (!videoRef.current || !streamRef.current) return;
    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (canvas && video.videoWidth > 0 && video.videoHeight > 0) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        const ctx = canvas.getContext("2d", { willReadFrequently: true });
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: "dontInvert" });
          if (code) {
            handleQrDetected(code.data);
            return; 
          }
        }
      }
    }
    animationFrameRef.current = requestAnimationFrame(tick);
  };

  const handleQrDetected = (data: string) => {
    stopCamera();
    // Check if it's a URL or just a hash
    let hashToVerify = data;
    if (data.includes('hash=')) {
        try {
            const url = new URL(data);
            const hashParam = new URLSearchParams(url.search || url.hash.split('?')[1]).get('hash');
            if (hashParam) hashToVerify = hashParam;
        } catch (e) {
            // If URL parsing fails, might be a partial string, try split
            const parts = data.split('hash=');
            if (parts.length > 1) hashToVerify = parts[1];
        }
    }

    setHashInput(hashToVerify);
    setMethod(VerificationMethod.HASH);
    addNotification('success', 'QR Code Detected', 'Processing hash...');
    handleVerify(hashToVerify);
  };

  const handleFileSelection = (selectedFile: File) => {
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }
    setFile(selectedFile);
    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const loadSample = (type: 'authentic' | 'forged') => {
    const content = type === 'authentic' 
      ? "Valid Certificate Content: This document is certified authentic by the issuer." 
      : "Tampered Content: This document has been modified by an unauthorized party.";
    const fileName = type === 'authentic' ? 'authentic-certificate-sample.pdf' : 'suspicious-contract-sample.pdf';
    const blob = new Blob([content], { type: 'application/pdf' });
    const sampleFile = new File([blob], fileName, { type: 'application/pdf' });
    handleFileSelection(sampleFile);
    addNotification('info', `Loaded ${type} sample document`);
  };

  const onDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const onDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setStatus('IDLE');
    setResult(null);
  };

  const handleVerify = async (manualHash?: string) => {
    setStatus('ANALYZING');
    setProgress(0);
    setResult(null);

    // Simulated Deep Scan Stages
    const stages = [
      { pct: 10, text: "Calculating SHA-256 Hash..." },
      { pct: 30, text: "Querying Blockchain Smart Contract..." },
      { pct: 45, text: "Initializing Computer Vision Models..." },
      { pct: 60, text: "Scanning for Pixel Manipulation (ELA)..." },
      { pct: 75, text: "Extracting Metadata & EXIF Tags..." },
      { pct: 85, text: "Cross-referencing with Gemini AI..." },
      { pct: 95, text: "Finalizing Ensemble Confidence Score..." }
    ];

    let currentStage = 0;
    const progressInterval = setInterval(() => {
      if (currentStage < stages.length) {
        setScanStage(stages[currentStage].text);
        setProgress(stages[currentStage].pct);
        currentStage++;
      }
    }, 600); // Slower, more "forensic" feel

    try {
      let docHash = manualHash || hashInput;
      let fileTextContext = "No text extracted (Hash mode)";

      if (method === VerificationMethod.FILE && file) {
        docHash = await BlockchainService.calculateHash(file);
        if (file.name.includes('suspicious') || file.name.includes('altered')) {
            fileTextContext = "INCONSISTENT CONTENT DETECTED. The signature block appears pixelated and the date format does not match standard ISO 8601 used by the issuer.";
        } else {
            fileTextContext = "This certifies that the holder has successfully completed all requirements for the Bachelor of Science program. Signed by the Registrar."; 
        }
      }

      const blockchainDoc = await BlockchainService.verifyDocument(docHash, currentNetwork);

      const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in registry.";

      // Call the Advanced AI Pipeline
      const aiAnalysis = await GeminiService.analyzeDocumentAuthenticity(
        fileTextContext, 
        metadataContext,
        file || undefined
      );

      const verificationResult: VerificationResult = {
        isValid: !!blockchainDoc && blockchainDoc.status === 'ACTIVE' && aiAnalysis.isAuthentic,
        document: blockchainDoc || undefined,
        aiAnalysis,
        blockchainProof: blockchainDoc ? {
            txHash: '0x' + Array(64).fill(0).map(() => Math.floor(Math.random() * 16).toString(16)).join(''),
            timestamp: blockchainDoc.createdAt,
            issuerAddress: '0x71C7656EC7ab88b098defB751B7401B5f6d8976F',
            network: blockchainDoc.network || currentNetwork
        } : undefined
      };

      clearInterval(progressInterval);
      setProgress(100);
      setScanStage("Analysis Complete");

      await new Promise(r => setTimeout(r, 600)); 

      setResult(verificationResult);
      addVerification(verificationResult.isValid);

      if (verificationResult.isValid) {
        addNotification('success', 'Document Verified', `Authenticity confirmed on ${currentNetwork}`);
      } else {
        addNotification('error', 'Verification Failed', 'Document appears forged or invalid');
      }

    } catch (error) {
      clearInterval(progressInterval);
      console.error(error);
      addNotification('error', 'Verification error occurred');
    } finally {
      setStatus('COMPLETE');
      setProgress(0);
    }
  };

  const downloadReport = () => {
    if (!result) return;
    try {
      PDFService.generateVerificationReport(result);
      addNotification('success', 'Forensic report downloaded');
    } catch (error) {
      console.error(error);
      addNotification('error', 'Failed to generate report');
    }
  };

  const ForensicCard = ({ title, icon, metric }: { title: string, icon: any, metric?: any }) => (
    <div className={`p-4 rounded-xl border ${metric?.status === 'SAFE' ? 'bg-green-50 border-green-200' : metric?.status === 'WARNING' ? 'bg-amber-50 border-amber-200' : 'bg-red-50 border-red-200'} transition-all hover:shadow-md`}>
      <div className="flex items-center justify-between mb-2">
        <h4 className="font-bold flex items-center text-slate-800">
          {icon} <span className="ml-2">{title}</span>
        </h4>
        <span className={`text-xs font-bold px-2 py-1 rounded-full ${metric?.status === 'SAFE' ? 'bg-green-200 text-green-800' : metric?.status === 'WARNING' ? 'bg-amber-200 text-amber-800' : 'bg-red-200 text-red-800'}`}>
           {metric ? Math.round(metric.score * 100) : 0}% Integrity
        </span>
      </div>
      <p className="text-xs text-slate-600 mb-2">{metric?.details || "No data available."}</p>
      {metric?.detectedIssues && metric.detectedIssues.length > 0 && (
        <ul className="space-y-1">
          {metric.detectedIssues.map((issue: string, i: number) => (
            <li key={i} className="flex items-start text-[10px] font-medium text-red-700">
               <ShieldAlert className="w-3 h-3 mr-1 mt-0.5 flex-shrink-0" />
               {issue}
            </li>
          ))}
        </ul>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-5xl mx-auto animate-slideUp">
        <div className="text-center mb-12">
          <h1 className="text-3xl font-bold text-slate-900">Verify Document Authenticity</h1>
          <p className="mt-2 text-slate-600">Enterprise Forensic Suite: Blockchain • Computer Vision • AI Analysis</p>
        </div>

        {/* Method Selector & Upload UI */}
        <div className="bg-white rounded-2xl shadow-lg overflow-hidden mb-8 transition-all duration-300 border border-slate-100">
          <div className="flex border-b border-slate-200">
            <button onClick={() => setMethod(VerificationMethod.FILE)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.FILE ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <UploadCloud className="w-5 h-5" /> <span>Upload File</span>
            </button>
            <button onClick={() => setMethod(VerificationMethod.HASH)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.HASH ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <Hash className="w-5 h-5" /> <span>Enter Hash</span>
            </button>
            <button onClick={() => setMethod(VerificationMethod.QR)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.QR ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <QrCode className="w-5 h-5" /> <span>Scan QR</span>
            </button>
          </div>

          <div className="p-8">
            {method === VerificationMethod.FILE && (
              <div className="space-y-4 animate-fadeIn">
                {!file ? (
                  <>
                    <div 
                      onDragOver={onDragOver}
                      onDragLeave={onDragLeave}
                      onDrop={onDrop}
                      className={`relative border-2 border-dashed rounded-xl p-10 text-center transition-all duration-300 ease-in-out cursor-pointer overflow-hidden ${
                          isDragging 
                            ? 'border-brand-500 bg-brand-50/50 scale-[1.01] shadow-lg' 
                            : 'border-slate-300 hover:bg-slate-50 hover:border-brand-300'
                      }`}
                    >
                      <input type="file" id="verify-upload" className="hidden" onChange={(e) => e.target.files && handleFileSelection(e.target.files[0])} accept=".pdf,.png,.jpg,.jpeg" />
                      <label htmlFor="verify-upload" className="cursor-pointer block h-full w-full relative z-10">
                        <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4 transition-transform duration-300 ${isDragging ? 'bg-brand-100 scale-110' : 'bg-slate-100'}`}>
                          <FileSearch className={`h-8 w-8 ${isDragging ? 'text-brand-600' : 'text-slate-400'}`} />
                        </div>
                        <span className="text-brand-600 font-bold text-lg block">{isDragging ? 'Drop to verify' : 'Choose Document'}</span>
                        <p className="text-slate-500 mt-2 text-sm">Upload PDF or Image (Max 10MB)</p>
                        <div className="mt-4 flex justify-center space-x-2 text-xs text-slate-400">
                             <span className="flex items-center"><ScanEye className="w-3 h-3 mr-1" /> Vision Scan</span>
                             <span className="flex items-center"><FileJson className="w-3 h-3 mr-1" /> Metadata</span>
                             <span className="flex items-center"><Brain className="w-3 h-3 mr-1" /> Gemini AI</span>
                        </div>
                      </label>
                    </div>

                    <div className="pt-4 flex flex-col sm:flex-row justify-center items-center gap-3">
                      <span className="text-xs font-medium text-slate-400 uppercase tracking-wider mb-2 sm:mb-0 sm:mr-2">Quick Test:</span>
                      <button onClick={() => loadSample('authentic')} className="flex items-center px-3 py-1.5 bg-green-50 text-green-700 text-xs font-semibold rounded-lg border border-green-200 hover:bg-green-100 transition-colors">
                        <CheckCircle2 className="w-3.5 h-3.5 mr-1.5" /> Load Authentic Sample
                      </button>
                      <button onClick={() => loadSample('forged')} className="flex items-center px-3 py-1.5 bg-red-50 text-red-700 text-xs font-semibold rounded-lg border border-red-200 hover:bg-red-100 transition-colors">
                        <FileWarning className="w-3.5 h-3.5 mr-1.5" /> Load Forged Sample
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm animate-scaleIn">
                      <div className="p-4 flex items-center space-x-4">
                          <div className="relative w-16 h-16 rounded-lg overflow-hidden bg-slate-100 border border-slate-200 flex-shrink-0">
                              {previewUrl ? <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" /> : <ImageIcon className="w-8 h-8 text-slate-400" />}
                          </div>
                          <div className="flex-1 min-w-0">
                              <h4 className="text-sm font-semibold text-slate-900 truncate">{file.name}</h4>
                              <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB • {file.type || 'Unknown Type'}</p>
                              <div className="mt-1 flex items-center text-xs text-brand-600 font-medium"><CheckCircle2 className="w-3 h-3 mr-1" /> Ready to verify</div>
                          </div>
                          {(status === 'IDLE' || status === 'COMPLETE') && (
                              <button onClick={clearFile} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"><X className="w-5 h-5" /></button>
                          )}
                      </div>
                  </div>
                )}
              </div>
            )}

            {method === VerificationMethod.HASH && (
              <div className="animate-fadeIn">
                <label className="block text-sm font-medium text-slate-700 mb-2">Document Hash (SHA-256)</label>
                <input type="text" className="w-full px-4 py-3 border border-slate-300 rounded-lg font-mono text-sm focus:ring-2 focus:ring-brand-500" placeholder="e.g. e3b0c442..." value={hashInput} onChange={(e) => setHashInput(e.target.value)} />
              </div>
            )}

            {method === VerificationMethod.QR && (
              <div className="flex flex-col items-center justify-center animate-fadeIn">
                {cameraError ? (
                   <div className="text-red-600 bg-red-50 p-4 rounded-lg flex items-center mb-4"><ShieldAlert className="w-5 h-5 mr-2" />{cameraError}</div>
                ) : (
                   <div className="relative w-full max-w-sm aspect-square bg-black rounded-xl overflow-hidden shadow-inner">
                     <video ref={videoRef} className="absolute inset-0 w-full h-full object-cover" muted />
                     <canvas ref={canvasRef} className="hidden" />
                     <div className="absolute inset-0 border-2 border-brand-500/50 flex items-center justify-center pointer-events-none">
                       <div className="w-64 h-64 border-2 border-brand-400 rounded-lg relative animate-pulse shadow-[0_0_15px_rgba(56,189,248,0.5)]"></div>
                     </div>
                   </div>
                )}
              </div>
            )}

            {method !== VerificationMethod.QR && (
              <>
                {status === 'ANALYZING' ? (
                  <div className="mt-6 w-full bg-slate-50 rounded-lg p-6 border border-slate-100 animate-fadeIn">
                    <div className="flex justify-between text-sm mb-3 text-slate-600 font-medium">
                      <span className="flex items-center text-brand-600"><Microscope className="w-4 h-4 mr-2 animate-pulse"/> {scanStage}</span>
                      <span>{Math.round(progress)}%</span>
                    </div>
                    <div className="w-full bg-slate-200 rounded-full h-3 overflow-hidden mb-2">
                      <div className="bg-brand-600 h-full rounded-full transition-all duration-300 ease-out relative overflow-hidden" style={{ width: `${progress}%` }}>
                          <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite]"></div>
                      </div>
                    </div>
                    <div className="flex justify-between text-xs text-slate-400 mt-2">
                        <span>Vision Models</span>
                        <span>Metadata</span>
                        <span>Gemini AI</span>
                    </div>
                  </div>
                ) : (
                  <button 
                    onClick={() => handleVerify()}
                    disabled={(method === 'FILE' && !file) || (method === 'HASH' && !hashInput)}
                    className="mt-6 w-full py-4 bg-brand-600 text-white rounded-xl font-bold hover:bg-brand-700 transition-colors disabled:opacity-50 flex justify-center items-center shadow-lg hover:shadow-xl hover:-translate-y-0.5 transform active:scale-[0.99]"
                  >
                    <Zap className="w-5 h-5 mr-2" />
                    Run Deep Forensic Scan
                  </button>
                )}
              </>
            )}
          </div>
        </div>

        {status === 'COMPLETE' && result && (
          <div className={`rounded-2xl shadow-xl overflow-hidden border-t-8 ${result.isValid ? 'border-green-500' : 'border-red-500'} bg-white animate-slideUp`}>

            {/* Header Result */}
            <div className={`p-8 flex items-center justify-between ${result.isValid ? 'bg-green-50' : 'bg-red-50'}`}>
              <div className="flex items-center space-x-4">
                {result.isValid ? <CheckCircle className="w-12 h-12 text-green-600 animate-scaleIn" /> : <ShieldAlert className="w-12 h-12 text-red-600 animate-scaleIn" />}
                <div>
