// ==========================================
// 3. Service Facade
// ==========================================

export const BlockchainService = {
  getAdapter: (network: NetworkType): ChainAdapter => {
    const config = NETWORK_CONFIGS[network];
    if (config.type === 'FABRIC') return new FabricAdapter(config);
    return new EVMAdapter(config);
  },

  calculateHash: async (file: File): Promise<string> => {
    const buffer = await file.arrayBuffer();
    const hashBuffer = await crypto.subtle.digest('SHA-256', buffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  },

  connectWallet: async (network: NetworkType) => {
    return BlockchainService.getAdapter(network).connectWallet();
  },

  registerDocument: async (metadata: Omit<DocumentMetadata, 'id' | 'createdAt' | 'status'>, network: NetworkType) => {
    const doc: DocumentMetadata = {
      ...metadata,
      id: `doc_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
      createdAt: new Date().toISOString(),
      status: DocumentStatus.PENDING,
      network
    };
    return BlockchainService.getAdapter(network).submitTransaction(doc);
  },

  verifyDocument: async (hash: string, network: NetworkType) => {
    return BlockchainService.getAdapter(network).fetchTransaction(hash);
  },

  estimateGas: async (network: NetworkType) => {
      return BlockchainService.getAdapter(network).estimateGas();
  }
};

