// ==========================================

interface ChainAdapter {
  connectWallet(): Promise<string>;
  submitTransaction(doc: DocumentMetadata): Promise<DocumentMetadata>;
  fetchTransaction(hash: string): Promise<DocumentMetadata | null>;
  estimateGas(): Promise<{ cost: string, usd: string }>;
}

// EVM Adapter (Ethereum, Polygon, BNB, Avalanche)
class EVMAdapter implements ChainAdapter {
  constructor(private config: NetworkConfig, private network: NetworkType) {}

  async connectWallet(): Promise<string> {
    await delay(600);
    // Simulate Metamask interaction: window.ethereum.request({ method: 'eth_requestAccounts' })
    return `0x${this.config.currency}7656EC7ab88b098defB751B7401B5f6d8976F`;
  }

  async estimateGas(): Promise<{ cost: string, usd: string }> {
    await delay(300);
    // Gas calc: 21000 base + 50000 data storage = ~71000 gas
    const gasUnits = 71000;
    const gwei = this.config.gasPriceGwei;
    const ethCost = (gasUnits * gwei) / 1000000000;

    // Mock Exchange Rates
    const rates: Record<string, number> = {
        'ETH': 3200,
        'SepoliaETH': 0,
        'MATIC': 0.85,
        'BNB': 600,
        'AVAX': 40
    };

    const rate = rates[this.config.currency] || 0;
    const usdCost = (ethCost * rate).toFixed(2);

    return {
        cost: `~${ethCost.toFixed(5)} ${this.config.currency}`,
        usd: `$${usdCost}`
    };
  }

  async submitTransaction(doc: DocumentMetadata): Promise<DocumentMetadata> {
    // Simulate Gas estimation & Mempool wait
    console.log(`[EVM] Routing tx to Chain ID ${this.config.chainId} via ${this.config.rpcEndpoint}`);
    await delay(this.config.blockTimeMs);

    const newDoc: DocumentMetadata = { ...doc, status: DocumentStatus.ACTIVE, network: this.network };
    GLOBAL_LEDGER.push(newDoc);
    return newDoc;
  }

  async fetchTransaction(hash: string): Promise<DocumentMetadata | null> {
    await delay(800);
    // Check Global Mock Ledger
    const found = GLOBAL_LEDGER.find(d => d.hash === hash || d.id === hash);
    return found || null;
  }
}

