// Converts a File object to a Base64 string compatible with Gemini's inlineData
async function fileToGenerativePart(file: File): Promise<{ inlineData: { data: string; mimeType: string } }> {
  const base64EncodedDataPromise = new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(file);
  });
  return {
    inlineData: { data: await base64EncodedDataPromise, mimeType: file.type },
  };
}

// Simulates the latency of loading heavy Computer Vision libraries (OpenCV.js / TensorFlow.js)
const visionLatency = () => new Promise(resolve => setTimeout(resolve, 800));

// ==========================================
// 2. FORENSIC AGENTS
// ==========================================

/**
 * AGENT 1: PIXEL FORENSICS (OpenCV Simulation)
 * Focus: Noise analysis, Error Level Analysis (ELA), Compression artifacts.
 */
async function runPixelForensics(file?: File): Promise<ForensicMetric> {
  await visionLatency();

  // Heuristic Simulation: Check for specific "suspicious" keywords simulating ELA findings
  const isSuspicious = file?.name.toLowerCase().includes('suspicious') || 
                       file?.name.toLowerCase().includes('fake');

  if (isSuspicious) {
    return {
      score: 0.45,
      status: 'CRITICAL',
      details: 'High-frequency noise variance detected in signature region (ELA).',
      detectedIssues: [
        'Inconsistent compression blocks',
        'Digital splicing artifacts detected'
      ]
    };
  }

  return {
    score: 0.98,
    status: 'SAFE',
    details: 'Pixel histogram and noise distribution are consistent with camera sensor/scanner signatures.',
    detectedIssues: []
  };
}

/**
 * AGENT 2: LAYOUT & GEOMETRY ANALYSIS (Vision Model)
 * Focus: Font alignment, kerning inconsistencies, grid misalignment.
 */
async function runLayoutAnalysis(file?: File): Promise<ForensicMetric> {
  await visionLatency();

  // Heuristic: Check for files named 'altered' or 'shifted' to simulate layout errors
  const isAltered = file?.name.toLowerCase().includes('altered') || 
                    file?.name.toLowerCase().includes('shifted');

  if (isAltered) {
     return {
         score: 0.55,
         status: 'WARNING',
         details: 'Optical Character Recognition (OCR) indicates variable font baselines.',
         detectedIssues: [
             'Non-standard kerning in header',
             'Grid misalignment > 2px in dates'
         ]
     };
  }

  return {
      score: 0.96,
      status: 'SAFE',
      details: 'Document geometry follows standard ISO 216 margins and font metrics.',
      detectedIssues: []
  };
}

/**
 * AGENT 3: METADATA FORENSICS
 * Focus: Timestamp analysis, Chain of Custody, File header analysis.
 */
function runMetadataAnalysis(file: File | undefined, metadataContext: string): ForensicMetric {
  if (!file) return { score: 1, status: 'SAFE', details: 'No file provided for metadata scan.', detectedIssues: [] };

  const now = new Date();
  const fileMod = new Date(file.lastModified);
  const oneDay = 24 * 60 * 60 * 1000;

  // Check 1: Time Travel Paradox
  if (fileMod.getTime() > now.getTime() + oneDay) {
    return {
      score: 0.1,
      status: 'CRITICAL',
      details: 'Temporal anomaly: File modification date is in the future.',
      detectedIssues: ['Invalid Timestamp', 'Future Modification Date']
    };
  }

  // Check 2: Blockchain Mismatch
  const isMetadataMismatch = metadataContext.includes("not found") || metadataContext.includes("mismatch");

  if (isMetadataMismatch) {
     return {
      score: 0.0,
      status: 'CRITICAL',
      details: 'Digital fingerprint does not match the anchored blockchain record.',
      detectedIssues: ['Hash Mismatch', 'Unregistered Document']
    };
  }

  // Check 3: Recent Edit Detection
  const isRecent = (now.getTime() - fileMod.getTime()) < oneDay;
  if (isRecent) {
    return {
      score: 0.70,
      status: 'WARNING',
      details: 'File metadata indicates recent modification relative to verification time.',
      detectedIssues: ['Recent Modification Detected']
    };
  }

  return {
    score: 0.99,
    status: 'SAFE',
    details: 'Metadata timestamps align with blockchain ledger history.',
    detectedIssues: []
  };
}

/**
 * AGENT 4: SEMANTIC TEXT ANALYST (Gemini)
 * Focus: Logical inconsistencies, factual verification, tone analysis.
 */
async function runGeminiSemanticAnalysis(
  fileTextContext: string, 
  metadataContext: string, 
  file?: File
): Promise<ForensicMetric> {

  if (!process.env.API_KEY) {
    console.warn("Gemini API Key missing. Returning mock analysis.");
    return { 
      score: 0.85, 
      status: 'SAFE', 
      details: 'Mock Analysis: Content logic appears sound based on heuristics.', 
      detectedIssues: [] 
    };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const modelName = 'gemini-3-flash-preview'; 

    // Prepare Multimodal Input
    const parts: any[] = [];

    parts.push({
      text: `ACT AS A FORENSIC DOCUMENT EXAMINER.

      Task: Analyze the text content of this document for semantic validity and logical consistency.

      Blockchain Record: ${metadataContext}
      Extracted Text Content: ${fileTextContext}

      Instructions:
      1. Check for logical inconsistencies (e.g., mismatched dates, math errors, conflicting names).
      2. Verify professional tone and terminology.
      3. Cross-reference extracted text with the provided Blockchain Record.

      Return a JSON object with this schema:
      {
        "score": number (0.0 to 1.0),
        "reasoning": "string",
        "issues": ["string", "string"]
      }`
    });

    if (file && (file.type === 'image/jpeg' || file.type === 'image/png' || file.type === 'image/webp')) {
      const imagePart = await fileToGenerativePart(file);
      parts.push(imagePart);
    }

    const result = await ai.models.generateContent({
      model: modelName,
      contents: { parts },
      config: { responseMimeType: 'application/json' }
    });

    const json = JSON.parse(result.text || "{}");

    return {
      score: json.score || 0.5,
      status: (json.score || 0) > 0.8 ? 'SAFE' : (json.score || 0) > 0.5 ? 'WARNING' : 'CRITICAL',
      details: json.reasoning || "AI Analysis completed.",
      detectedIssues: json.issues || []
    };

  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    return {
      score: 0.5,
      status: 'WARNING',
      details: 'AI Service Unavailable. Performing partial analysis.',
      detectedIssues: ['AI_CONNECTIVITY_ERROR']
    };
  }
}

// ==========================================
// 3. MAIN SERVICE FACADE
// ==========================================

export const GeminiService = {
  analyzeDocumentAuthenticity: async (
    fileTextContext: string,
    metadataContext: string,
    file?: File
  ): Promise<VerificationResult['aiAnalysis']> => {

    // EXECUTE MULTI-MODEL PIPELINE
    const [pixelResult, layoutResult, metadataResult, contentResult] = await Promise.all([
      runPixelForensics(file),
      runLayoutAnalysis(file),
      Promise.resolve(runMetadataAnalysis(file, metadataContext)),
      runGeminiSemanticAnalysis(fileTextContext, metadataContext, file)
    ]);

    // ENSEMBLE SCORING LOGIC
    // We weight the confidence based on the reliability of the detection method
    // Pixel (Vision): 30% - Hard to fake at pixel level
    // Layout (Vision): 20% - Structure
    // Metadata (Chain): 25% - Immutable ledger
    // Content (Semantic): 25% - Logic

    let ensembleScore = 
      (pixelResult.score * 0.30) + 
      (layoutResult.score * 0.20) + 
      (metadataResult.score * 0.25) + 
      (contentResult.score * 0.25);

    // VETO VOTE: If any critical agent fails (score < 0.4), the entire document fails
    const criticalFailure = [pixelResult, layoutResult, metadataResult, contentResult].some(r => r.status === 'CRITICAL');

    if (criticalFailure) {
      ensembleScore = Math.min(ensembleScore, 0.45); // Force Fail
    }

    const isAuthentic = ensembleScore > 0.75;

    // Aggregating Flags
    const allFlags = [
      ...(pixelResult.detectedIssues || []),
      ...(layoutResult.detectedIssues || []),
      ...(metadataResult.detectedIssues || []),
      ...(contentResult.detectedIssues || [])
    ];

    console.log(`[TrustChain Ensemble] Score=${ensembleScore.toFixed(3)} | Flags=${allFlags.length}`);

    return {
      isAuthentic,
      confidence: ensembleScore,
      reasoning: criticalFailure 
        ? `AUTOMATED REJECTION: Critical anomalies detected in ${pixelResult.status === 'CRITICAL' ? 'Pixel' : metadataResult.status === 'CRITICAL' ? 'Metadata' : 'Layout'} Analysis.` 
        : `AUTHENTICATED: Consensus reached across 4 AI models. ${contentResult.details}`,
      flags: allFlags,
      forensics: {
        visual: pixelResult,
        layout: layoutResult,
        metadata: metadataResult,
        content: contentResult,
        overallScore: ensembleScore
      }
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { FileCheck, ShieldAlert, CheckCircle, UploadCloud, Brain, FileSearch, Hash, QrCode, Loader2, X, Image as ImageIcon, Shield, CheckCircle2, Sparkles, FileWarning, Fingerprint, ScanEye, Zap, Activity, Microscope, Layers, FileJson, ExternalLink, Download, Ruler, Grid3X3 } from 'lucide-react';
import { BlockchainService } from '../services/blockchain';
import { GeminiService } from '../services/gemini';
import { PDFService } from '../services/pdfGenerator';
import { DocumentMetadata, VerificationResult, VerificationMethod } from '../types';
import { useNotification } from '../components/NotificationSystem';
import { useGlobalStore } from '../components/GlobalStore';
import jsQR from 'jsqr';

export const VerifyDocument = () => {
  const { addNotification } = useNotification();
  const { addVerification, currentNetwork } = useGlobalStore();
  const [method, setMethod] = useState<VerificationMethod>(VerificationMethod.FILE);
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hashInput, setHashInput] = useState('');
  const [status, setStatus] = useState<'IDLE' | 'ANALYZING' | 'COMPLETE'>('IDLE');
  const [progress, setProgress] = useState(0);
  const [scanStage, setScanStage] = useState<string>('Initializing'); 
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [displayScore, setDisplayScore] = useState(0);

  // QR Scanning Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  useEffect(() => {
    if (method === VerificationMethod.QR) {
      startCamera();
    } else {
      stopCamera();
    }
  }, [method]);

  // Animate score when result changes
  useEffect(() => {
    if (result?.aiAnalysis?.forensics?.overallScore) {
      setDisplayScore(0);
      const timer = setTimeout(() => {
        setDisplayScore(result.aiAnalysis!.forensics.overallScore);
      }, 300);
      return () => clearTimeout(timer);
    } else {
      setDisplayScore(0);
    }
  }, [result]);

  // Check for URL parameters (e.g. from QR code scan)
  useEffect(() => {
    const checkUrlParams = () => {
      try {
        const hashPart = window.location.hash.split('?')[1];
        if (hashPart) {
            const params = new URLSearchParams(hashPart);
            const urlHash = params.get('hash');
            if (urlHash) {
                setHashInput(urlHash);
                setMethod(VerificationMethod.HASH);
                addNotification('info', 'Hash detected from URL', 'Ready to verify');
            }
        }
      } catch (e) {
        console.error("Error parsing URL params", e);
      }
    };

    checkUrlParams();
  }, [addNotification]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.setAttribute("playsinline", "true"); 
        await videoRef.current.play();
        requestAnimationFrame(tick);
      }
    } catch (err) {
      console.error("Error accessing camera:", err);
      setCameraError("Unable to access camera. Please ensure permissions are granted.");
      addNotification('error', 'Camera access denied');
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const tick = () => {
    if (!videoRef.current || !streamRef.current) return;
    if (videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (canvas && video.videoWidth > 0 && video.videoHeight > 0) {
        canvas.height = video.videoHeight;
        canvas.width = video.videoWidth;
        const ctx = canvas.getContext("2d", { willReadFrequently: true });
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: "dontInvert" });
          if (code) {
            handleQrDetected(code.data);
            return; 
          }
        }
      }
    }
    animationFrameRef.current = requestAnimationFrame(tick);
  };

  const handleQrDetected = (data: string) => {
    stopCamera();
    let hashToVerify = data;
    if (data.includes('hash=')) {
        try {
            const url = new URL(data);
            const hashParam = new URLSearchParams(url.search || url.hash.split('?')[1]).get('hash');
            if (hashParam) hashToVerify = hashParam;
        } catch (e) {
            const parts = data.split('hash=');
            if (parts.length > 1) hashToVerify = parts[1];
        }
    }

    setHashInput(hashToVerify);
    setMethod(VerificationMethod.HASH);
    addNotification('success', 'QR Code Detected', 'Processing hash...');
    handleVerify(hashToVerify);
  };

  const handleFileSelection = (selectedFile: File) => {
    if (selectedFile.size > 10 * 1024 * 1024) {
      addNotification('error', 'File is too large (Max 10MB)');
      return;
    }
    setFile(selectedFile);
    if (selectedFile.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreviewUrl(reader.result as string);
      };
      reader.readAsDataURL(selectedFile);
    } else {
      setPreviewUrl(null);
    }
  };

  const loadSample = (type: 'authentic' | 'forged') => {
    const content = type === 'authentic' 
      ? "Valid Certificate Content: This document is certified authentic by the issuer." 
      : "Tampered Content: This document has been modified by an unauthorized party.";
    const fileName = type === 'authentic' ? 'authentic-certificate-sample.pdf' : 'suspicious-contract-sample.pdf';
    const blob = new Blob([content], { type: 'application/pdf' });
    const sampleFile = new File([blob], fileName, { type: 'application/pdf' });
    handleFileSelection(sampleFile);
    addNotification('info', `Loaded ${type} sample document`);
  };

  const onDragOver = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(true); };
  const onDragLeave = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); };
  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelection(e.dataTransfer.files[0]);
    }
  };

  const clearFile = () => {
    setFile(null);
    setPreviewUrl(null);
    setStatus('IDLE');
    setResult(null);
  };

  const handleVerify = async (manualHash?: string) => {
    setStatus('ANALYZING');
    setProgress(0);
    setResult(null);

    // Deep Scan Stages (Expanded for 4 models)
    const stages = [
      { pct: 5, text: "Calculating Cryptographic SHA-256 Hash..." },
      { pct: 15, text: "Querying Distributed Ledger (Blockchain)..." },
      { pct: 30, text: "Analyzing Pixel Noise Patterns (ELA)..." },
      { pct: 50, text: "Measuring Layout Geometry & Font Alignment..." },
      { pct: 65, text: "Verifying Time-Stamps & Metadata..." },
      { pct: 80, text: "Semantic Consistency Check (Gemini AI)..." },
      { pct: 90, text: "Calculating Ensemble Confidence Score..." }
    ];

    let currentStage = 0;
    const progressInterval = setInterval(() => {
      if (currentStage < stages.length) {
        setScanStage(stages[currentStage].text);
        setProgress(stages[currentStage].pct);
        currentStage++;
      }
    }, 500);

    try {
      let docHash = manualHash || hashInput;
      let fileTextContext = "No readable text extracted (Hash-only mode)";

      if (method === VerificationMethod.FILE && file) {
        docHash = await BlockchainService.calculateHash(file);

        if (file.name.includes('suspicious') || file.name.includes('altered')) {
            fileTextContext = "INCONSISTENT CONTENT DETECTED. The signature block appears pixelated and the date format does not match standard ISO 8601 used by the issuer.";
        } else {
            fileTextContext = "This certifies that the holder has successfully completed all requirements for the Bachelor of Science program. Signed by the Registrar of MIT."; 
        }
      }

      // 1. Blockchain Lookup
      const blockchainDoc = await BlockchainService.verifyDocument(docHash, currentNetwork);
      const metadataContext = blockchainDoc ? JSON.stringify(blockchainDoc) : "Document not found in decentralized registry.";

      // 2. Advanced AI Pipeline
      const aiAnalysis = await GeminiService.analyzeDocumentAuthenticity(
        fileTextContext, 
        metadataContext,
        file || undefined
      );

      const verificationResult: VerificationResult = {
        isValid: !!blockchainDoc && blockchainDoc.status === 'ACTIVE' && aiAnalysis.isAuthentic,
        document: blockchainDoc || undefined,
        aiAnalysis,
        blockchainProof: blockchainDoc ? {
            txHash: '0x' + Array(64).fill(0).map(() => Math.floor(Math.random() * 16).toString(16)).join(''),
            timestamp: blockchainDoc.createdAt,
            issuerAddress: '0x71C7656EC7ab88b098defB751B7401B5f6d8976F',
            network: blockchainDoc.network || currentNetwork
        } : undefined
      };

      clearInterval(progressInterval);
      setProgress(100);
      setScanStage("Deep Scan Complete");

      await new Promise(r => setTimeout(r, 600)); 

      setResult(verificationResult);
      addVerification(verificationResult.isValid);

      if (verificationResult.isValid) {
        addNotification('success', 'Document Verified', `Authenticity confirmed on ${currentNetwork}`);
      } else {
        addNotification('error', 'Verification Failed', 'Document appears forged or invalid');
      }

    } catch (error) {
      clearInterval(progressInterval);
      console.error(error);
      addNotification('error', 'Verification error occurred');
    } finally {
      setStatus('COMPLETE');
      setProgress(0);
    }
  };

  const downloadReport = () => {
    if (!result) return;
    try {
      PDFService.generateVerificationReport(result);
      addNotification('success', 'Forensic report downloaded');
    } catch (error) {
      console.error(error);
      addNotification('error', 'Failed to generate report');
    }
  };

  const ForensicCard = ({ title, icon, metric }: { title: string, icon: any, metric?: any }) => (
    <div className={`p-4 rounded-xl border ${metric?.status === 'SAFE' ? 'bg-green-50 border-green-200' : metric?.status === 'WARNING' ? 'bg-amber-50 border-amber-200' : 'bg-red-50 border-red-200'} transition-all hover:shadow-md`}>
      <div className="flex items-center justify-between mb-2">
        <h4 className="font-bold flex items-center text-slate-800 text-sm">
          {icon} <span className="ml-2">{title}</span>
        </h4>
        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${metric?.status === 'SAFE' ? 'bg-green-200 text-green-800' : metric?.status === 'WARNING' ? 'bg-amber-200 text-amber-800' : 'bg-red-200 text-red-800'}`}>
           {metric ? Math.round(metric.score * 100) : 0}%
        </span>
      </div>

      {/* Mini Progress Bar */}
      <div className="w-full bg-white/50 rounded-full h-1.5 mb-3 overflow-hidden">
         <div 
            className={`h-full rounded-full transition-all duration-1000 ease-out ${metric?.status === 'SAFE' ? 'bg-green-500' : metric?.status === 'WARNING' ? 'bg-amber-500' : 'bg-red-500'}`} 
            style={{ width: `${(metric?.score || 0) * 100}%` }}
         ></div>
      </div>

      <p className="text-xs text-slate-600 mb-2 leading-relaxed">{metric?.details || "No data available."}</p>
      {metric?.detectedIssues && metric.detectedIssues.length > 0 && (
        <ul className="space-y-1">
          {metric.detectedIssues.map((issue: string, i: number) => (
            <li key={i} className="flex items-start text-[10px] font-medium text-red-700">
               <ShieldAlert className="w-3 h-3 mr-1 mt-0.5 flex-shrink-0" />
               {issue}
            </li>
          ))}
        </ul>
      )}
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-6xl mx-auto animate-slideUp">
        <div className="text-center mb-12">
          <h1 className="text-3xl font-bold text-slate-900">Verify Document Authenticity</h1>
          <p className="mt-2 text-slate-600">Advanced Forensics: Pixel • Layout • Metadata • Semantics</p>
        </div>

        {/* Method Selector & Upload UI */}
        <div className="bg-white rounded-2xl shadow-lg overflow-hidden mb-8 transition-all duration-300 border border-slate-100 max-w-4xl mx-auto">
          <div className="flex border-b border-slate-200">
            <button onClick={() => setMethod(VerificationMethod.FILE)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.FILE ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <UploadCloud className="w-5 h-5" /> <span>Upload File</span>
            </button>
            <button onClick={() => setMethod(VerificationMethod.HASH)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.HASH ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <Hash className="w-5 h-5" /> <span>Enter Hash</span>
            </button>
            <button onClick={() => setMethod(VerificationMethod.QR)} className={`flex-1 py-4 text-sm font-medium flex items-center justify-center space-x-2 transition-colors ${method === VerificationMethod.QR ? 'bg-brand-50 text-brand-600 border-b-2 border-brand-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <QrCode className="w-5 h-5" /> <span>Scan QR</span>
            </button>
          </div>

          <div className="p-8">
            {method === VerificationMethod.FILE && (
              <div className="space-y-4 animate-fadeIn">
                {!file ? (
                  <>
                    <div 
                      onDragOver={onDragOver}
                      onDragLeave={onDragLeave}
                      onDrop={onDrop}
                      className={`relative border-2 border-dashed rounded-xl p-10 text-center transition-all duration-300 ease-in-out cursor-pointer overflow-hidden ${
                          isDragging 
                            ? 'border-brand-500 bg-brand-50/50 scale-[1.01] shadow-lg' 
                            : 'border-slate-300 hover:bg-slate-50 hover:border-brand-300'
                      }`}
                    >
                      <input type="file" id="verify-upload" className="hidden" onChange={(e) => e.target.files && handleFileSelection(e.target.files[0])} accept=".pdf,.png,.jpg,.jpeg" />
                      <label htmlFor="verify-upload" className="cursor-pointer block h-full w-full relative z-10">
                        <div className={`mx-auto w-16 h-16 rounded-full flex items-center justify-center mb-4 transition-transform duration-300 ${isDragging ? 'bg-brand-100 scale-110' : 'bg-slate-100'}`}>
                          <FileSearch className={`h-8 w-8 ${isDragging ? 'text-brand-600' : 'text-slate-400'}`} />
                        </div>
                        <span className="text-brand-600 font-bold text-lg block">{isDragging ? 'Drop to verify' : 'Choose Document'}</span>
                        <p className="text-slate-500 mt-2 text-sm">Upload PDF or Image (Max 10MB)</p>
                        <div className="mt-4 flex justify-center space-x-2 text-xs text-slate-400">
                             <span className="flex items-center"><ScanEye className="w-3 h-3 mr-1" /> Vision</span>
                             <span className="flex items-center"><Ruler className="w-3 h-3 mr-1" /> Layout</span>
                             <span className="flex items-center"><Brain className="w-3 h-3 mr-1" /> Gemini</span>
                        </div>
                      </label>
                    </div>

                    <div className="pt-4 flex flex-col sm:flex-row justify-center items-center gap-3">
                      <span className="text-xs font-medium text-slate-400 uppercase tracking-wider mb-2 sm:mb-0 sm:mr-2">Quick Test:</span>
                      <button onClick={() => loadSample('authentic')} className="flex items-center px-3 py-1.5 bg-green-50 text-green-700 text-xs font-semibold rounded-lg border border-green-200 hover:bg-green-100 transition-colors">
                        <CheckCircle2 className="w-3.5 h-3.5 mr-1.5" /> Authentic
                      </button>
                      <button onClick={() => loadSample('forged')} className="flex items-center px-3 py-1.5 bg-red-50 text-red-700 text-xs font-semibold rounded-lg border border-red-200 hover:bg-red-100 transition-colors">
                        <FileWarning className="w-3.5 h-3.5 mr-1.5" /> Forged
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm animate-scaleIn">
                      <div className="p-4 flex items-center space-x-4">
                          <div className="relative w-16 h-16 rounded-lg overflow-hidden bg-slate-100 border border-slate-200 flex-shrink-0">
                              {previewUrl ? <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" /> : <ImageIcon className="w-8 h-8 text-slate-400" />}
                          </div>
                          <div className="flex-1 min-w-0">
                              <h4 className="text-sm font-semibold text-slate-900 truncate">{file.name}</h4>
                              <p className="text-xs text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB • {file.type || 'Unknown Type'}</p>
                              <div className="mt-1 flex items-center text-xs text-brand-600 font-medium"><CheckCircle2 className="w-3 h-3 mr-1" /> Ready to verify</div>
                          </div>
                          {(status === 'IDLE' || status === 'COMPLETE') && (
