                            ) : (
                                <div className="absolute bottom-8 left-1/2 -translate-x-1/2 bg-black/60 px-4 py-2 rounded-full text-white/70 text-xs flex items-center">
                                    <Loader2 className="w-3 h-3 mr-2 animate-spin" />
